INSERT INTO `activities` (`id`, `title_mr`, `title_en`, `short_description_mr`, `short_description_en`, `description_mr`, `description_en`, `image`, `icon`, `sort_order`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'भव्य वॉटर पार्क आणि स्लाइड्स', 'Grand Water Park & Slides', 'अनेक प्रकारच्या आंतरराष्ट्रीय दर्जाच्या वॉटर स्लाइड्स, वेव्ह पूल आणि लेझी रिव्हर.', 'Multi-tier high speed water slides, artificial wave pool, and lazy river.', 'विसावा वॉटर पार्क हे संपूर्ण कुटुंबासाठी मनमुराद आनंदाचे ठिकाण आहे. येथे लहानांपासून मोठ्यांपर्यंत सर्वांसाठी सुरक्षित व स्वच्छ पाण्याचे राइड्स उपलब्ध आहेत.', 'Visava Water Park provides world-class aquatic fun with certified lifeguards, UV-filtered pure water, and exciting slides for all age groups.', NULL, '🌊', 1, 1, '2026-08-25 04:36:25', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(2, 'थ्रिल अम्युझमेंट राइड्स', 'Thrill Amusement Rides', 'रोलर कोस्टर, जायंट व्हील, बंपर कार्स आणि साहसी खेळ.', 'Roller coasters, giant wheels, bumper cars and family adventure games.', 'उत्कंठावर्धक अम्युझमेंट राइड्सचा अनुभव घ्या. आंतरराष्ट्रीय मानकांनुसार तपासणी केलेल्या सुरक्षित राइड्स.', 'Experience adrenaline-pumping mechanical rides engineered with precision safety and world-class standards.', NULL, '🎢', 2, 1, '2026-08-25 04:36:25', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(3, 'लक्झरी व्हिला व डिलक्स कॉटेजेस', 'Luxury Stay & Deluxe Cottages', 'निसर्गरम्य बागांमध्ये वसलेले आधुनिक सुविधांयुक्त कॉटेजेस.', 'Garden view luxury cottages with modern amenities and scenic balconies.', 'शांत आणि प्रसन्न वातावरणात कुटुंबासह सुट्टी घालवण्यासाठी विसावा रिसॉर्टचे सुसज्ज कॉटेजेस उत्तम पर्याय आहेत.', 'Spacious cottages equipped with high-speed Wi-Fi, air conditioning, and 24/7 room service nestled in nature.', NULL, '🏡', 3, 1, '2026-08-25 04:36:25', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(4, 'मल्टी-कुझिन रेस्टॉरंट व बुफे', 'Multi-Cuisine Dining & Cafes', 'स्वादिष्ट महाराष्ट्रीय, पंजाबी आणि चायनीज शाकाहारी व मांसाहारी भोजन.', 'Authentic Maharashtrian delicacies, North Indian buffets, and poolside cafes.', 'शुद्ध आणि ताज्या घटकांपासून तयार केलेले स्वादिष्ट अन्न. विसावा किचनमध्ये अमर्यादित बुफेची सुविधा.', 'Hygienic culinary masterclasses, authentic local flavors, and refreshing mocktails served at our resort restaurants.', NULL, '🍽️', 4, 1, '2026-08-25 04:36:25', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(5, 'रेन डान्स आणि लाईव्ह डीजे पार्टी', 'Rain Dance & Live DJ Party', 'पाण्याच्या फवाऱ्यांखाली संगीताच्या तालावर थिरकण्याचा अनोखा अनुभव.', 'High-energy rain dance floor with pulsating live DJ music beats.', 'दररोज दुपारी आणि संध्याकाळी खास रेन डान्स पार्टी आयोजित केली जाते, जिथे सर्व वयोगटातील पाहुणे उत्साहाने सहभागी होतात.', 'Groove to the latest Bollywood and global beats under artificial rain showers with state-of-the-art sound systems.', NULL, '🎵', 5, 1, '2026-08-25 04:36:25', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(6, 'किड्स फन व ॲडव्हेंचर झोन', 'Kids Fun & Adventure Zone', 'लहान मुलांसाठी सुरक्षित खेळ, ट्रॅम्पोलिन आणि टॉय ट्रेन्स.', 'Dedicated safe play area with trampolines, toy trains, and sand games.', 'लहान मुलांच्या कल्पकतेला आणि मनोरंजनाला वाव देणारे आकर्षक खेळ आणि सुरक्षित वातावरण.', 'A secure and colorful play park curated for toddlers and young children with cushioned play equipment.', NULL, '🎈', 6, 1, '2026-08-25 04:36:25', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(7, 'द्राक्ष बागा व सेंद्रिय शेती शिवार फेरी', 'Grape Vineyard & Organic Farm Tour', '१५ एकर विस्तीर्ण सेंद्रिय शेती, द्राक्ष बागा आणि फळबागांची मार्गदर्शित सफर.', 'Guided educational tour across 15 acres of organic farming, grape vineyards, and fruit orchards.', 'प्रत्यक्ष झाडावरून ताजी फळे चाखण्याचा आनंद आणि सेंद्रिय शेतीची सविस्तर माहिती.', 'Taste fresh fruits straight from the vine and learn sustainable farming practices with our resident experts.', 'https://images.unsplash.com/photo-1595974482597-4b8da8879bc5?w=800&auto=format&fit=crop&q=80', '🍇', 1, 1, '2026-08-25 05:32:17', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(8, 'चुलीवरची अस्सल गावरान मिसळ व जेवण', 'Wood-Fired Authentic Maharashtrian Dining', 'शेतात पिकवलेल्या ताज्या भाज्या आणि चुलीवरची झणझणीत गावरान चव.', 'Farm-to-table dining prepared on traditional earthen chulhas with secret village spices.', 'गरमागरम बाजरी-ज्वारीची भाकरी, पिठलं-ठेचा, वांग्याचं भरीत आणि शुद्ध गावठी तूप.', 'Savor piping hot bhakris, pithla-thecha, zanzanit misal, and farm-fresh organic vegetable curries.', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=800&auto=format&fit=crop&q=80', '🍲', 2, 1, '2026-08-25 05:32:17', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(9, 'पारंपारिक बैलगाडी सफर व ग्रामीण खेळ', 'Traditional Bullock Cart Ride & Rural Games', 'सजावट केलेल्या बैलगाडीतून मळ्याची सफर, विटी-दांडू, गोट्या व लगोरी.', 'Enjoy scenic bullock cart rides across farm trails along with nostalgic childhood village games.', 'लहान मुलांसाठी आणि कुटुंबीयांसाठी अस्सल जुन्या आठवणींना उजाळा देणारा अनुभव.', 'Relive childhood nostalgia with traditional outdoor sports, tractor rides, and pottery making.', 'https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80', '🐂', 3, 1, '2026-08-25 05:32:17', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(10, 'स्वच्छ स्विमिंग पूल, रेन डान्स व विहीर स्नान', 'Swimming Pool, Rain Dance & Well Bathing', 'शुद्ध पाण्याचा स्विमिंग पूल, रेन डान्स फ्लोअर आणि पारंपारिक विहीर स्नान.', 'Ultra-filtered clean swimming pool, pulsating rain dance floor, and traditional farm well bathing.', 'उन्हाळ्याच्या आणि सुट्टीच्या दिवसात संपूर्ण कुटुंबासाठी मनसोक्त जलविहार.', 'Cool off in our hygienic swimming pool with separate kids splash area and music-synced rain dance.', 'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?w=800&auto=format&fit=crop&q=80', '🏊‍♂️', 4, 1, '2026-08-25 05:32:17', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(11, 'हंगामी हुरडा पार्टी व शेकोटी', 'Seasonal Hurda Party & Bonfire', 'हिवाळ्यातील गरमागरम भाजलेला हुरडा, गुळ-शेंगदाणा चटणी आणि संध्याकाळची शेकोटी.', 'Roasted tender green jowar hurda served with delicious chutneys and cozy evening bonfires.', 'थंडीच्या मोसमात मळ्यातील हुरड्याची चव आणि कौटुंबिक गप्पांची रंगतदार संध्याकाळ.', 'Gather around the glowing bonfire for roasted hurda feasts under starry countryside skies.', 'https://images.unsplash.com/photo-1543083477-4f785aeafaa9?w=800&auto=format&fit=crop&q=80', '🌾', 5, 1, '2026-08-25 05:32:17', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(12, 'डिलक्स फार्म कॉटेज व निसर्गरम्य मुक्काम', 'Deluxe Farm Cottages & Peaceful Stay', 'हिरवेगार बागांमध्ये वसलेले सुसज्ज वातानुकूलित कॉटेजेस आणि प्रशस्त व्हरांडा.', 'Spacious nature-view deluxe cottages with modern amenities, AC, and serene private verandas.', 'शांत आणि प्रदूषणमुक्त वातावरणात कुटुंबासह सुरक्षित मुक्कामाची उत्तम सोय.', 'Wake up to the chirping of birds and crisp fresh air in our thoughtfully designed rustic cottages.', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=800&auto=format&fit=crop&q=80', '🏡', 6, 1, '2026-08-25 05:32:17', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(13, 'मुलांचा ॲडव्हेंचर व खेळ परिसर', 'Children\'s Play Area & Adventure Zone', 'झोपाळे, घसरगुंडी, क्लायंबिंग आणि सुरक्षित मैदानी खेळांचे विस्तीर्ण मैदान.', 'Safe outdoor playground with swings, slides, climbing nets, and spacious green turf.', 'लहान मुलांच्या सर्वांगीण विकासासाठी आणि आनंदासाठी सुरक्षित खेळाचे आकर्षण.', 'A joyful haven for kids with curated outdoor obstacles, trampolines, and sand play pits.', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?w=800&auto=format&fit=crop&q=80', '🎈', 7, 1, '2026-08-25 05:53:31', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(14, 'रेन डान्स आणि म्युझिक पार्टी', 'Rain Dance & Music Party', 'मनमुराद संगीताच्या तालावर थंडगार पाण्याच्या सरींमध्ये नाचण्याचा आनंद.', 'Dance to upbeat festive tunes under refreshing cooling water mist sprays and showers.', 'मित्र आणि कुटुंबासह आनंदोत्सव साजरा करण्यासाठी खास रेन डान्स फ्लोअर.', 'High-energy outdoor rain dance arena equipped with state-of-the-art sound systems.', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=800&auto=format&fit=crop&q=80', '🎵', 8, 1, '2026-08-25 05:53:31', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(15, 'निसर्ग पायवाट व पक्षी निरीक्षण', 'Nature Walk & Bird Watching Trail', 'हिरवेगार वृक्ष, फुलांच्या बागा आणि विविध पक्ष्यांच्या दर्शनासाठी रम्य पायवाट.', 'Scenic walking trails through green groves, flowering gardens, and birding spots.', 'सकाळच्या कोवळ्या उन्हात निसर्गाच्या कुशीत शांत मनःशांती देणारी सफर.', 'Breathe deep and reconnect with nature on our peaceful marked farm trails.', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=800&auto=format&fit=crop&q=80', '🌳', 9, 1, '2026-08-25 05:53:31', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(16, 'सेंद्रिय शेती व पिक प्रात्यक्षिके', 'Seasonal Farming & Organic Harvesting', 'भाजीपाला खुडणे, बीजारोपण आणि शेती कामांचा प्रत्यक्ष अनुभव.', 'Hands-on organic harvesting, vegetable picking, and planting demonstrations.', 'शहरी पाहुण्यांना आणि विद्यार्थ्यांना शेतीचे महत्त्व शिकवणारे प्रत्यक्ष प्रात्यक्षिक.', 'Get your hands in the soil and harvest seasonal produce straight from our living beds.', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=800&auto=format&fit=crop&q=80', '🌱', 10, 1, '2026-08-25 05:53:31', '2026-08-25 06:07:38', '2026-08-25 06:07:38'),
(17, 'स्वच्छ स्विमिंग पूल व विहीर स्नान', 'Swimming Pool', 'शुद्ध आणि स्वच्छ पाण्याचा स्विमिंग पूल, लहान मुलांचा पूल आणि पारंपारिक विहीर स्नान.', 'Crystal-clear filtered swimming pool with kids splash area and authentic farm well bathing experience.', 'उन्हाळ्याच्या आणि सुट्टीच्या दिवसात संपूर्ण कुटुंबासाठी मनसोक्त जलविहार आणि पारंपारिक विहिरीच्या पाण्याचा आनंद.', 'Relax and refresh in our hygienic swimming pool amidst nature, featuring filtered water and traditional well bathing.', 'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?w=800&auto=format&fit=crop&q=80', '🏊‍♂️', 1, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(18, 'रेन डान्स आणि म्युझिक पार्टी', 'Rain Dance', 'थंडगार पाण्याच्या सरींमध्ये डीजे संगीताच्या तालावर मनमुराद नाचण्याचा आनंद.', 'High-energy rain dance floor with cool water mist showers and live music beats.', 'मित्र आणि कुटुंबासह संगीताच्या तालावर थंडगार पाण्याच्या सरींखाली आनंदोत्सव साजरा करा.', 'Celebrate joyful moments with family and friends on our spacious rain dance arena with high-quality sound.', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=800&auto=format&fit=crop&q=80', '🎵', 2, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(19, 'द्राक्ष बागा शिवार फेरी', 'Grape Vineyard Tour', '१५ एकर विस्तीर्ण द्राक्ष बागा आणि फळबागांची मार्गदर्शित शिवार फेरी.', 'Guided educational walk through lush grape vineyards and organic fruit orchards.', 'विस्तीर्ण द्राक्ष बागांमध्ये फिरा, आधुनिक शेती पद्धतींची माहिती घ्या आणि गोड फळांचा आस्वाद घ्या.', 'Stroll through sprawling vineyards, learn about cultivation techniques, and taste freshly plucked fruits.', 'https://images.unsplash.com/photo-1595974482597-4b8da8879bc5?w=800&auto=format&fit=crop&q=80', '🍇', 3, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(20, 'चुलीवरची अस्सल गावरान मिसळ व जेवण', 'Traditional Wood-Fired Misal', 'शेतातील ताज्या भाज्या आणि चुलीवर तयार केलेली झणझणीत गावरान मिसळ व जेवण.', 'Farm-to-table dining prepared on traditional wood-fired earthen chulhas.', 'गरमागरम बाजरी-ज्वारीची भाकरी, पिठलं-ठेचा, वांग्याचं भरीत आणि शुद्ध गावठी तुपातील चविष्ट जेवण.', 'Relish piping hot wood-fired misal, bajra bhakris, pithla-thecha, and authentic rural delicacies.', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=800&auto=format&fit=crop&q=80', '🍲', 4, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(21, 'सेंद्रिय शेती व शिवार फेरी', 'Farm Visit', 'सेंद्रिय शेती, भाजीपाला आणि विविध पिकांची माहिती देणारी प्रत्यक्ष शिवार फेरी.', 'Educational agro-tour across 15 acres of organic crops, polyhouses, and vegetation.', 'सेंद्रिय शेती, आधुनिक तंत्रज्ञान आणि हिरवेगार शिवार जवळून अनुभवण्याची उत्तम संधी.', 'Explore sustainable organic farming methods, visit green polyhouses, and reconnect with agriculture roots.', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=800&auto=format&fit=crop&q=80', '🌾', 5, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(22, 'पारंपारिक बैलगाडी सफर', 'Bullock Cart Ride', 'सजावट केलेल्या पारंपारिक बैलगाडीतून मळ्याच्या बांधावरून रपेट मारण्याचा आनंद.', 'Nostalgic ride on beautifully decorated bullock carts around countryside farm trails.', 'लहान-मोठ्या सर्वांसाठी बैलगाडीतून फिरण्याचा आणि ग्रामीण संस्कृती अनुभवण्याचा आनंददायी क्षण.', 'Experience rural transport heritage with authentic bullock cart rides across rustic village tracks.', 'https://images.unsplash.com/photo-1500937386664-56d1dfef3854?w=800&auto=format&fit=crop&q=80', '🐂', 6, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(23, 'पारंपारिक ग्रामीण खेळ', 'Rural Games', 'विटी-दांडू, लगोरी, गोट्या, रस्सीखेच आणि जुन्या पारंपारिक खेळांची धमाल.', 'Classic outdoor village sports: Viti-Dandu, Lagori, Marbles, Tug-of-war, and archery.', 'मोबाईलपासून दूर मोकळ्या मैदानात विटी-दांडू, लगोरी आणि जुन्या खेळांचा मनमुराद आनंद घ्या.', 'Relive childhood nostalgia and bond with family playing traditional Maharashtrian village games.', 'https://images.unsplash.com/photo-1511882150382-421056c89033?w=800&auto=format&fit=crop&q=80', '🎯', 7, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(24, 'मुलांचा खेळ परिसर व ॲडव्हेंचर झोन', 'Children’s Play Area', 'झोपाळे, घसरगुंडी, क्लायंबिंग, ट्रॅम्पोलिन आणि वाळूचे सुरक्षित मैदान.', 'Dedicated kids outdoor adventure park with swings, slides, nets, trampoline, and sand pit.', 'निसर्गाच्या मोकळ्या हवेत लहान मुलांच्या आनंदासाठी सुरक्षित आणि सुसज्ज खेळाचे मैदान.', 'A safe and vibrant outdoor play space specially designed for kids to enjoy active play in nature.', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?w=800&auto=format&fit=crop&q=80', '🎈', 8, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(25, 'निसर्ग पायवाट व पक्षी निरीक्षण', 'Nature Walk', 'हिरवेगार वृक्ष, फुलांच्या बागा आणि पक्ष्यांच्या किलबिलाटात रम्य पायवाट सफर.', 'Peaceful shaded walking trails through tree groves with fresh morning breezes and bird sounds.', 'शहरातील प्रदूषणापासून दूर शांत निसर्गात पक्षांचा किलबिलाट ऐकत निवांत चालण्याचा आनंद.', 'Breathe fresh unpolluted air, spot native birds, and soak in tranquil greenery along marked trails.', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=800&auto=format&fit=crop&q=80', '🌳', 9, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(26, 'हंगामी शेती कामे व पिक प्रात्यक्षिके', 'Seasonal Farming Activities', 'भाजीपाला खुडणे, बीजारोपण, हुरडा भाजणे आणि शेतीच्या प्रत्यक्ष कामांचा अनुभव.', 'Hands-on vegetable harvesting, seed planting, hurda roasting, and farming traditions.', 'प्रत्यक्ष शेतात उतरून भाजीपाला खुडणे, बी लावणे आणि हुरडा पार्टीचा खरा ग्रामीण अनुभव घ्या.', 'Experience the joy of harvesting your own farm-fresh vegetables and participate in seasonal traditions.', 'https://images.unsplash.com/photo-1592417817098-8f3d69109853?w=800&auto=format&fit=crop&q=80', '🌱', 10, 1, '2026-08-25 06:07:38', '2026-08-25 06:15:30', '2026-08-25 06:15:30'),
(27, 'स्वच्छ स्विमिंग पूल व विहीर स्नान', 'Swimming Pool', 'शुद्ध आणि स्वच्छ पाण्याचा स्विमिंग पूल, लहान मुलांचा पूल आणि पारंपारिक विहीर स्नान.', 'Crystal-clear filtered swimming pool with kids splash area and authentic farm well bathing experience.', 'उन्हाळ्याच्या आणि सुट्टीच्या दिवसात संपूर्ण कुटुंबासाठी मनसोक्त जलविहार आणि पारंपारिक विहिरीच्या पाण्याचा आनंद.', 'Relax and refresh in our hygienic swimming pool amidst nature, featuring filtered water and traditional well bathing.', 'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?w=800&auto=format&fit=crop&q=80', '🏊‍♂️', 1, 1, '2026-08-25 06:15:30', '2026-08-25 06:27:15', '2026-08-25 06:27:15'),
(28, 'रेन डान्स आणि म्युझिक पार्टी', 'Rain Dance', 'थंडगार पाण्याच्या सरींमध्ये डीजे संगीताच्या तालावर मनमुराद नाचण्याचा आनंद.', 'High-energy rain dance floor with cool water mist showers and live music beats.', 'मित्र आणि कुटुंबासह संगीताच्या तालावर थंडगार पाण्याच्या सरींखाली आनंदोत्सव साजरा करा.', 'Celebrate joyful moments with family and friends on our spacious rain dance arena with high-quality sound.', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=800&auto=format&fit=crop&q=80', '🎵', 2, 1, '2026-08-25 06:15:30', '2026-08-25 06:27:15', '2026-08-25 06:27:15'),
(29, 'द्राक्ष बागा शिवार फेरी', 'Grape Vineyard Tour', '१५ एकर विस्तीर्ण द्राक्ष बागा आणि फळबागांची मार्गदर्शित शिवार फेरी.', 'Guided educational walk through lush grape vineyards and organic fruit orchards.', 'विस्तीर्ण द्राक्ष बागांमध्ये फिरा, आधुनिक शेती पद्धतींची माहिती घ्या आणि गोड फळांचा आस्वाद घ्या.', 'Stroll through sprawling vineyards, learn about cultivation techniques, and taste freshly plucked fruits.', 'https://images.unsplash.com/photo-1595974482597-4b8da8879bc5?w=800&auto=format&fit=crop&q=80', '🍇', 3, 1, '2026-08-25 06:15:30', '2026-08-25 06:27:15', '2026-08-25 06:27:15'),
