INSERT INTO `blogs` (`id`, `title_mr`, `title_en`, `title`, `slug`, `short_description_mr`, `short_description_en`, `description_mr`, `description_en`, `excerpt`, `content`, `featured_image`, `blog_video`, `youtube_url`, `instagram_url`, `status`, `created_by`, `updated_by`, `category`, `is_published`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'विसावा रिसॉर्टला भेट देण्यासाठी उत्तम वेळ कोणती?', 'Best Time to Visit Visava Amusement Park & Resort', 'Best Time to Visit Visava Amusement Park & Resort', 'best-time-to-visit-visava', 'ऋतूनुसार विसावा रिसॉर्टमधील मुख्य आकर्षणे आणि प्रवासाच्या टिप्स.', 'Seasonal attractions and travel tips for your visit to Visava Resort.', 'विसावा रिसॉर्टमध्ये वर्षभर विविध उपक्रम सुरू असतात. पावसाळ्यात निसर्ग सौंदर्य आणि हिवाळ्यात आनंददायी वातावरण पर्यटकांना आकर्षित करते.', 'Visava Resort is a year-round holiday destination with lush monsoon greenery and pleasant winter breeze for ideal family vacations.', 'Seasonal attractions and travel tips for your visit to Visava Resort.', 'Visava Resort is a year-round holiday destination with lush monsoon greenery and pleasant winter breeze for ideal family vacations.', 'uploads/blogs/visawa_cartwheel_bridge_blog.jpg', NULL, NULL, NULL, 'active', 1, NULL, NULL, 1, NULL, '2026-08-25 00:50:37', '2026-09-03 02:58:01', '2026-09-03 02:58:01'),
(2, NULL, 'this is a sample', 'this is a sample', 'this-is-a-sample-fzqar', NULL, 'dfgf g', NULL, 'fgfghgh gfh', 'dfgf g', 'fgfghgh gfh', 'uploads/blogs/visawa_grand_entrance_blog.jpg', NULL, NULL, NULL, 'active', 1, NULL, NULL, 1, NULL, '2026-08-25 01:15:54', '2026-09-02 01:43:29', '2026-09-02 01:43:29'),
(3, 'विसावा कृषी पर्यटनाचा अद्वितीय अनुभव – बाबांचा मळा', 'Experience Authentic Rural Culture at Visawa Agro Tourism', NULL, 'experience-authentic-rural-culture-at-visawa', 'निसर्गाच्या सानिध्यात ग्रामीण जीवन, सेंद्रिय शेती आणि अस्सल चवींचा विसावा घ्या.', 'Immerse yourself in authentic rustic living, organic farming tours, and wood-fired Maharashtrian hospitality.', 'विसावा कृषी पर्यटन – बाबांचा मळा येथे कौटुंबिक आनंद, द्राक्ष बागांची सफर, ग्रामीण खेळ आणि शांत मुक्कामाचा मनमुराद आनंद मिळतो.', 'Discover Maharashtra countryside charm with vineyard strolls, authentic chulha food, kids adventure rides, and serene cottage stays.', NULL, NULL, 'uploads/blogs/visawa_grand_entrance_blog.jpg', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4', 'https://www.youtube.com/watch?v=M7lc1UVf-VE', 'https://www.instagram.com/visawa', 'active', 1, NULL, NULL, 1, NULL, '2026-08-31 03:10:07', '2026-09-03 02:57:53', '2026-09-03 02:57:53'),
(4, 'विसावा कृषी पर्यटनाला भेट देण्याची प्रमुख कारणे', 'Top Reasons to Visit Visawa Agro Tourism Resort', NULL, 'top-reasons-to-visit-visawa-agro-tourism', 'शहरी धावपळीपासून दूर संपूर्ण कुटुंबासाठी एक परिपूर्ण वीकेंड विसावा ठिकाण.', 'Why Babacha Mala is Maharashtra\'s premier destination for family outings, school trips, and corporate offsites.', 'विस्तीर्ण शिवार, बैलगाडी सफर, स्वादिष्ट गावरान मिसळ आणि कौटुंबिक सुट्टीसाठी सर्वोत्तम ठिकाण म्हणजे विसावा कृषी पर्यटन.', 'From pristine nature walks and cartwheel bridges to authentic folk traditions and pool fun, explore everything Visawa offers.', NULL, NULL, 'uploads/blogs/visawa_cartwheel_bridge_blog.jpg', NULL, NULL, NULL, 'active', 1, NULL, NULL, 1, NULL, '2026-08-31 03:10:07', '2026-09-03 02:57:59', '2026-09-03 02:57:59'),
(5, 'विसावा ॲग्रो टुरिझम – ग्रामीण संस्कृती आणि निसर्गरम्य पर्यटनाचा आनंद!', 'Visawa Agro Tourism – Experience Nature, Rural Culture & Fun Activities', 'Visawa Agro Tourism – Experience Nature, Rural Culture & Fun Activities', 'visawa-agro-tourism-experience-nature-rural-culture-fun-activities-f5Zae', 'ट्रॅक्टर सफर, गावरान हुरडा पार्टी, अस्सल महाराष्ट्रीयन जेवण आणि निसर्गाचा निवांत अनुभव घेण्यासाठी विसावा ॲग्रो टुरिझमला नक्की भेट द्या.', 'Enjoy fun tractor rides, authentic Maharashtrian meals, traditional rural vibes, and group get-togethers at Visawa Agro Tourism.', 'शहराच्या धावपळीपासून दूर जाऊन निसर्गाच्या सानिध्यात निवांत वेळ घालवायचा असेल, तर विसावा ॲग्रो टुरिझम (बाबाचा मळा) हे एक सर्वोत्तम ठिकाण आहे.\r\n\r\nआमची खास वैशिष्ट्ये:\r\n\r\nग्रामीण संस्कृतीची सफर: बैलगाडी, ट्रॅक्टर ट्रेनची सफर आणि अस्सल गावरान वातावरण.\r\n\r\nअस्सल महाराष्ट्रीयन जेवण: गरमागरम बाजरी-ज्वारीची भाकरी, शेवगा रस्सा, पिठलं आणि गावरान नाश्त्याचा आस्वाद.\r\n\r\nकौटुंबिक व ग्रुप कार्यक्रम: स्नेहमेलन, कौटुंबिक कार्यक्रम आणि गेट-टुगेदरसाठी प्रशस्त हॉल व परिसर.\r\n\r\nआजच तुमचे बुकिंग करण्यासाठी आमच्याशी संपर्क साधा!', 'Looking for an authentic rural and agro-tourism experience? Visawa Agro Tourism (Babacha Mala) welcomes you to enjoy nature and traditional Maharashtrian hospitality.\r\n\r\nKey Highlights:\r\n\r\nFun Activities: Enjoy unique tractor rides, explore green orchards, and experience traditional village vibes.\r\n\r\nAuthentic Food: Relish Maharashtrian breakfast, Hurda parties, and wholesome farm-style thalis.\r\n\r\nEvents & Gatherings: Ideal venue for family get-togethers, cultural meets, and group outings.\r\n\r\nPlan your visit today and experience the warmth of nature!', 'Enjoy fun tractor rides, authentic Maharashtrian meals, traditional rural vibes, and group get-togethers at Visawa Agro Tourism.', 'Looking for an authentic rural and agro-tourism experience? Visawa Agro Tourism (Babacha Mala) welcomes you to enjoy nature and traditional Maharashtrian hospitality.\r\n\r\nKey Highlights:\r\n\r\nFun Activities: Enjoy unique tractor rides, explore green orchards, and experience traditional village vibes.\r\n\r\nAuthentic Food: Relish Maharashtrian breakfast, Hurda parties, and wholesome farm-style thalis.\r\n\r\nEvents & Gatherings: Ideal venue for family get-togethers, cultural meets, and group outings.\r\n\r\nPlan your visit today and experience the warmth of nature!', NULL, 'uploads/blogs/videos/1788424031_Vw6wCxibGy.mp4', NULL, 'https://www.instagram.com/reel/DctDNIfxMD1/?igsi=dTgyenIxNGI4Nmp0', 'active', 1, NULL, NULL, 1, NULL, '2026-09-03 02:57:11', '2026-09-03 02:57:11', NULL),
(6, 'विसावा ॲग्रो टुरिझम (बाबाचा मळा) येथे रक्षाबंधन व स्नेहसंमेलन उत्साहात संपन्न!', 'Heartwarming Rakshabandhan & Get-Together Celebration at Visawa Agro Tourism', 'Heartwarming Rakshabandhan & Get-Together Celebration at Visawa Agro Tourism', 'heartwarming-rakshabandhan-get-together-celebration-at-visawa-agro-tourism-6ZMkt', 'नात्यांचा गोडवा, संस्कृतीची जपणूक आणि आनंद! गुजराती विद्या मंदिराच्या कार्यक्रमाची खास झलक आणि आगामी गणेशोत्सव व नवरात्रीची तयारी.', 'Highlights of Rakshabandhan & senior reunion at Visawa Agro Tourism. Get ready for the upcoming Ganeshotsav & Navratri celebrations!', '🌿 विसावा ॲग्रो टुरिझम – बाबाचा मळा ❤️🍀\r\n\r\nनुकतेच आमच्या विसावा ॲग्रो टुरिझम मध्ये \'गुजराती विद्या मंदिर\' परिवाराचे रक्षाबंधन आणि खास स्नेहसंमेलन (Get-together) अतिशय उत्साहात आणि आनंदी वातावरणात पार पडले.\r\n\r\nनात्यांचा गोडवा, संस्कृतीची जपणूक आणि ज्येष्ठांचा सहवास यामुळे हा दिवस सर्वांसाठीच अविस्मरणीय ठरला. उपस्थितांनी निसर्गाच्या कुशीत ट्रॅक्टर ट्रेनची सफर, गावरान वातावरणाचा आनंद आणि अस्सल भोजनाचा आस्वाद घेतला.\r\n\r\n🚩 लवकरच गणेशोत्सव आणि नवरात्री उत्सव! 🌺\r\nराखी सेलिब्रेशनच्या अभूतपूर्व प्रतिसादानंतर आता विसावा ॲग्रो टुरिझम सज्ज होत आहे आगामी गणेशोत्सव आणि नवरात्री उत्सवासाठी! पारंपरिक संस्कृती, निसर्गाची साथ आणि उत्सवाचा जल्लोष अनुभवण्यासाठी तुमच्या कुटुंबासोबत नक्की भेट द्या.\r\n\r\n📍 पत्ता: नवीन धुळे–सोलापूर हायवे, करोडी टोलनाक्याच्या बाजूला, अमृता हॉटेलच्या पाठीमागे, बाबाचा मळा, करोडी, छत्रपती संभाजीनगर.\r\n\r\n📞 आजच तुमचे बुकिंग करण्यासाठी आमच्याशी संपर्क साधा!', '🌿 Visawa Agro Tourism – Babacha Mala ❤️🍀\r\n\r\nWe recently had the honor of hosting a wonderful Rakshabandhan & Reunion Get-Together for the \'Gujarati Vidya Mandir\' family at Visawa Agro Tourism.\r\n\r\nThe event was filled with joy, traditional values, and sweet memories. Guests thoroughly enjoyed the scenic green surroundings, fun tractor train rides, and delicious farm-style meals.\r\n\r\n🚩 Upcoming Celebrations: Ganeshotsav & Navratri! 🌺\r\nAfter the grand success of our Rakhi celebration, we are gearing up to celebrate the auspicious festivals of Ganeshotsav and Navratri! Experience the true festive spirit amidst nature with your family and loved ones.\r\n\r\n📍 Location: New Dhule–Solapur Highway, Near Karodi Toll Plaza, Behind Amruta Hotel, Babacha Mala, Karodi, Chhatrapati Sambhajinagar.\r\n\r\n📞 Contact us today to book your group events and weekend packages!', 'Highlights of Rakshabandhan & senior reunion at Visawa Agro Tourism. Get ready for the upcoming Ganeshotsav & Navratri celebrations!', '🌿 Visawa Agro Tourism – Babacha Mala ❤️🍀\r\n\r\nWe recently had the honor of hosting a wonderful Rakshabandhan & Reunion Get-Together for the \'Gujarati Vidya Mandir\' family at Visawa Agro Tourism.\r\n\r\nThe event was filled with joy, traditional values, and sweet memories. Guests thoroughly enjoyed the scenic green surroundings, fun tractor train rides, and delicious farm-style meals.\r\n\r\n🚩 Upcoming Celebrations: Ganeshotsav & Navratri! 🌺\r\nAfter the grand success of our Rakhi celebration, we are gearing up to celebrate the auspicious festivals of Ganeshotsav and Navratri! Experience the true festive spirit amidst nature with your family and loved ones.\r\n\r\n📍 Location: New Dhule–Solapur Highway, Near Karodi Toll Plaza, Behind Amruta Hotel, Babacha Mala, Karodi, Chhatrapati Sambhajinagar.\r\n\r\n📞 Contact us today to book your group events and weekend packages!', NULL, 'uploads/blogs/videos/1788428795_MyG4ARDizK.mp4', NULL, 'https://www.instagram.com/visawaagrotourism/reel/DcsPx-qTyxa/', 'active', 1, NULL, NULL, 1, NULL, '2026-09-03 04:16:35', '2026-09-03 04:16:35', NULL),
(7, 'चिमुकल्या पावलांच्या आगमनाचा आनंद | VISAWA मधील बेबी शॉवर सोहळा', 'Celebrating a Little Miracle | Baby Shower at VISAWA Agro Tourism', 'Celebrating a Little Miracle | Baby Shower at VISAWA Agro Tourism', 'celebrating-a-little-miracle-baby-shower-at-visawa-agro-tourism-av5Ao', 'चिमुकल्या पाहुण्याच्या स्वागतासाठी प्रेम, आनंद आणि आठवणींनी भरलेला बेबी शॉवर सोहळा VISAWA Agro Tourism मध्ये खास वातावरणात साजरा झाला.', 'A beautiful baby shower celebration filled with love, joy, and unforgettable memories at VISAWA Agro Tourism.', '🌙👣 चिमुकल्या पावलांचा आवाज अजून ऐकू आला नाही… पण त्याच्या आगमनाने मन मात्र आधीच भरून आलंय. 💞🍼\r\n\r\nVISAWA Agro Tourism – बाबांचा मळा येथे प्रेम, आपुलकी आणि आनंदाने भरलेला एक सुंदर Baby Shower सोहळा साजरा करण्यात आला. निसर्गाच्या सान्निध्यात, हिरवाईने वेढलेल्या शांत वातावरणात हा खास क्षण अधिकच संस्मरणीय बनला.\r\n\r\nहोणाऱ्या आईसाठी प्रेमाने सजवलेली जागा, कुटुंबियांचे आशीर्वाद आणि आनंदाने भरलेले वातावरण या प्रत्येक क्षणाला खास बनवत होते. अशा सुंदर आठवणी जपण्यासाठी VISAWA हे कुटुंबीय समारंभांसाठी एक उत्तम ठिकाण आहे.\r\n\r\nVISAWA मध्ये Baby Shower साठी खास सुविधा\r\n\r\nनिसर्गरम्य आणि शांत वातावरण\r\n\r\nसुंदर फोटो व रील्ससाठी आकर्षक लोकेशन्स\r\n\r\nकुटुंबासाठी प्रशस्त जागा\r\n\r\nपारंपरिक गावरान आदरातिथ्य\r\n\r\nखास समारंभांसाठी योग्य वातावरण\r\n\r\nचिमुकल्या पाहुण्याच्या स्वागताचा हा सुंदर प्रवास VISAWA मध्ये आणखी खास बनवा. ✨', '🌙👣 The tiny footsteps haven\'t arrived yet, but our hearts are already full of joy. 💞🍼\r\n\r\nA heartwarming Baby Shower celebration was beautifully hosted at VISAWA Agro Tourism – Babacha Mala, where nature, love, and family came together to create unforgettable memories.\r\n\r\nSurrounded by lush greenery and a peaceful countryside atmosphere, the celebration became even more special with heartfelt blessings, beautiful decorations, and joyful moments shared with loved ones.', 'A beautiful baby shower celebration filled with love, joy, and unforgettable memories at VISAWA Agro Tourism.', '🌙👣 The tiny footsteps haven\'t arrived yet, but our hearts are already full of joy. 💞🍼\r\n\r\nA heartwarming Baby Shower celebration was beautifully hosted at VISAWA Agro Tourism – Babacha Mala, where nature, love, and family came together to create unforgettable memories.\r\n\r\nSurrounded by lush greenery and a peaceful countryside atmosphere, the celebration became even more special with heartfelt blessings, beautiful decorations, and joyful moments shared with loved ones.', NULL, 'uploads/blogs/videos/1788429533_D72Y8dwi7d.mp4', NULL, 'https://www.instagram.com/reel/DZhny4xsSRv/?igsi=MW43cDMyd2FtdHpzbQ==', 'active', 1, NULL, NULL, 1, NULL, '2026-09-03 04:28:53', '2026-09-03 04:28:53', NULL),
(8, 'विसावा ॲग्रो टुरिझममध्ये आपले मनःपूर्वक स्वागत', 'Welcome to VISAWA Agro Tourism – Your Gateway to Nature', 'Welcome to VISAWA Agro Tourism – Your Gateway to Nature', 'welcome-to-visawa-agro-tourism-your-gateway-to-nature-gWA2j', 'हिरव्यागार झाडांनी वेढलेला सुंदर प्रवेशद्वार, मोकळे निसर्गरम्य वातावरण आणि अस्सल ग्रामीण सौंदर्य अनुभवण्यासाठी विसावा अॅग्रो टुरिझममध्ये आपले स्वागत आहे.', 'Experience the peaceful entrance of VISAWA Agro Tourism surrounded by lush greenery, open landscapes, and authentic village charm. Step into a relaxing getaway where nature and tradition come together.', 'विसावा ॲग्रो टुरिझम – बाबांचा मळा येथे प्रत्येक प्रवासाची सुरुवात होते एका सुंदर ग्रामीण स्वागताने.\r\n\r\nहिरव्यागार झाडांनी वेढलेला प्रवेशमार्ग, ताजी हवा आणि शांत वातावरण पाहताच मनाला एक वेगळाच विसावा मिळतो. हा निसर्गरम्य परिसर शहराच्या धकाधकीपासून दूर शांत आणि आनंददायी अनुभव देतो.\r\n\r\nप्रवेशद्वारातून आत आल्यानंतर विस्तीर्ण परिसर, सुंदर पायवाटा आणि ग्रामीण संस्कृतीची झलक प्रत्येक पाहुण्याला निसर्गाच्या अधिक जवळ घेऊन जाते.\r\n\r\nविसावा ॲग्रो टुरिझममध्ये तुम्हाला मिळतो—\r\n\r\nअस्सल महाराष्ट्रीयन गावरान जेवण\r\n\r\nपारंपरिक ग्रामीण खेळ\r\n\r\nशेतीचा प्रत्यक्ष अनुभव\r\n\r\nकुटुंब आणि मित्रांसोबत निवांत क्षण\r\n\r\nशांत, स्वच्छ आणि हिरवागार परिसर\r\n\r\nडे पिकनिक, विकेंड स्टे, कुटुंब सहल किंवा कॉर्पोरेट गेट-टुगेदर—प्रत्येकासाठी येथे एक वेगळा अनुभव आहे.\r\n\r\nया छोट्याशा व्हिडिओमधून विसावाच्या सुंदर वातावरणाची झलक पहा आणि आपल्या पुढील ग्रामीण सहलीचे नियोजन आजच करा.\r\n\r\nविसावा ॲग्रो टुरिझम – जिथे निसर्ग, परंपरा आणि आनंद एकत्र येतात.', 'Welcome to VISAWA Agro Tourism – Babacha Mala\r\n\r\nEvery journey at VISAWA Agro Tourism begins with a warm village welcome. As you enter through the beautiful entrance surrounded by lush green trees and fresh countryside air, you\'ll instantly experience the peaceful atmosphere that makes VISAWA special.\r\n\r\nThe scenic entrance leads you into a spacious agro-tourism destination where nature, tradition, and comfort come together. Beautiful walkways, open landscapes, and a refreshing environment make it the perfect escape from busy city life.\r\n\r\nWhat makes VISAWA special?\r\n\r\nAuthentic Maharashtrian village cuisine\r\n\r\nTraditional rural games and activities\r\n\r\nFarm and nature experiences\r\n\r\nPeaceful open surroundings\r\n\r\nPerfect for families, couples, and groups\r\n\r\nWhether you\'re planning a day picnic, weekend stay, family outing, or corporate gathering, VISAWA offers unforgettable moments in the heart of nature.\r\n\r\nThis short video gives you a glimpse of our beautiful entrance and serene surroundings—an invitation to experience the charm of rural Maharashtra.\r\n\r\nVISAWA Agro Tourism – Where Nature Meets Tradition.', 'Experience the peaceful entrance of VISAWA Agro Tourism surrounded by lush greenery, open landscapes, and authentic village charm. Step into a relaxing getaway where nature and tradition come together.', 'Welcome to VISAWA Agro Tourism – Babacha Mala\r\n\r\nEvery journey at VISAWA Agro Tourism begins with a warm village welcome. As you enter through the beautiful entrance surrounded by lush green trees and fresh countryside air, you\'ll instantly experience the peaceful atmosphere that makes VISAWA special.\r\n\r\nThe scenic entrance leads you into a spacious agro-tourism destination where nature, tradition, and comfort come together. Beautiful walkways, open landscapes, and a refreshing environment make it the perfect escape from busy city life.\r\n\r\nWhat makes VISAWA special?\r\n\r\nAuthentic Maharashtrian village cuisine\r\n\r\nTraditional rural games and activities\r\n\r\nFarm and nature experiences\r\n\r\nPeaceful open surroundings\r\n\r\nPerfect for families, couples, and groups\r\n\r\nWhether you\'re planning a day picnic, weekend stay, family outing, or corporate gathering, VISAWA offers unforgettable moments in the heart of nature.\r\n\r\nThis short video gives you a glimpse of our beautiful entrance and serene surroundings—an invitation to experience the charm of rural Maharashtra.\r\n\r\nVISAWA Agro Tourism – Where Nature Meets Tradition.', NULL, 'uploads/blogs/videos/1788518127_Trdo75c4MN.mov', NULL, NULL, 'active', 1, 1, NULL, 1, NULL, '2026-09-04 05:05:27', '2026-09-07 04:23:19', NULL);

