('visava-cache-api_activities_en', 'a:14:{i:0;a:15:{s:2:\"id\";i:67;s:5:\"title\";s:13:\"Swimming Pool\";s:8:\"title_mr\";s:89:\"स्वच्छ स्विमिंग पूल व विहीर स्नान\";s:8:\"title_en\";s:13:\"Swimming Pool\";s:17:\"short_description\";s:102:\"Crystal-clear filtered swimming pool with kids splash area and authentic farm well bathing experience.\";s:20:\"short_description_mr\";s:221:\"शुद्ध आणि स्वच्छ पाण्याचा स्विमिंग पूल, लहान मुलांचा पूल आणि पारंपारिक विहीर स्नान.\";s:20:\"short_description_en\";s:102:\"Crystal-clear filtered swimming pool with kids splash area and authentic farm well bathing experience.\";s:11:\"description\";s:117:\"Relax and refresh in our hygienic swimming pool amidst nature, featuring filtered water and traditional well bathing.\";s:14:\"description_mr\";s:307:\"उन्हाळ्याच्या आणि सुट्टीच्या दिवसात संपूर्ण कुटुंबासाठी मनसोक्त जलविहार आणि पारंपारिक विहिरीच्या पाण्याचा आनंद.\";s:14:\"description_en\";s:117:\"Relax and refresh in our hygienic swimming pool amidst nature, featuring filtered water and traditional well bathing.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788174622_MGV4dIsKNK.png\";s:4:\"icon\";s:13:\"🏊‍♂️\";s:10:\"sort_order\";i:1;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:1;a:15:{s:2:\"id\";i:68;s:5:\"title\";s:10:\"Rain Dance\";s:8:\"title_mr\";s:76:\"रेन डान्स आणि म्युझिक पार्टी\";s:8:\"title_en\";s:10:\"Rain Dance\";s:17:\"short_description\";s:79:\"High-energy rain dance floor with cool water mist showers and live music beats.\";s:20:\"short_description_mr\";s:204:\"थंडगार पाण्याच्या सरींमध्ये डीजे संगीताच्या तालावर मनमुराद नाचण्याचा आनंद.\";s:20:\"short_description_en\";s:79:\"High-energy rain dance floor with cool water mist showers and live music beats.\";s:11:\"description\";s:106:\"Celebrate joyful moments with family and friends on our spacious rain dance arena with high-quality sound.\";s:14:\"description_mr\";s:233:\"मित्र आणि कुटुंबासह संगीताच्या तालावर थंडगार पाण्याच्या सरींखाली आनंदोत्सव साजरा करा.\";s:14:\"description_en\";s:106:\"Celebrate joyful moments with family and friends on our spacious rain dance arena with high-quality sound.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788176575_9F5sehyrIH.png\";s:4:\"icon\";s:4:\"🎵\";s:10:\"sort_order\";i:2;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:2;a:15:{s:2:\"id\";i:69;s:5:\"title\";s:19:\"Grape Vineyard Tour\";s:8:\"title_mr\";s:63:\"द्राक्ष बागा शिवार फेरी\";s:8:\"title_en\";s:19:\"Grape Vineyard Tour\";s:17:\"short_description\";s:80:\"Guided educational walk through lush grape vineyards and organic fruit orchards.\";s:20:\"short_description_mr\";s:181:\"१५ एकर विस्तीर्ण द्राक्ष बागा आणि फळबागांची मार्गदर्शित शिवार फेरी.\";s:20:\"short_description_en\";s:80:\"Guided educational walk through lush grape vineyards and organic fruit orchards.\";s:11:\"description\";s:105:\"Stroll through sprawling vineyards, learn about cultivation techniques, and taste freshly plucked fruits.\";s:14:\"description_mr\";s:258:\"विस्तीर्ण द्राक्ष बागांमध्ये फिरा, आधुनिक शेती पद्धतींची माहिती घ्या आणि गोड फळांचा आस्वाद घ्या.\";s:14:\"description_en\";s:105:\"Stroll through sprawling vineyards, learn about cultivation techniques, and taste freshly plucked fruits.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788170900_Pnw5Bsuk4r.jpeg\";s:4:\"icon\";s:4:\"🍇\";s:10:\"sort_order\";i:3;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:3;a:15:{s:2:\"id\";i:78;s:5:\"title\";s:29:\"Authentic Village Hurda Party\";s:8:\"title_mr\";s:72:\"अस्सल गावरान हुर्डा पार्टी\";s:8:\"title_en\";s:29:\"Authentic Village Hurda Party\";s:17:\"short_description\";s:98:\"Enjoy fresh roasted tender jowar (Hurda) over open fire with jaggery and authentic spicy chutneys.\";s:20:\"short_description_mr\";s:224:\"शेकोटीवर भाजलेला गरमागरम ताजा हुर्डा, सोबत गुळ, सुके खोबरे आणि झणझणीत चटण्यांचा आनंद\";s:20:\"short_description_en\";s:98:\"Enjoy fresh roasted tender jowar (Hurda) over open fire with jaggery and authentic spicy chutneys.\";s:11:\"description\";s:438:\"Experience the authentic taste of winter with our farm-fresh tender Hurda (roasted sorghum) at Visawa Agro Tourism. Roasted to perfection over open embers in traditional style, it is served with authentic garlic & peanut chutneys, dry coconut, and organic jaggery. Relaxing around the cozy evening campfire while savoring this rich Maharashtrian culinary tradition offers a delightful and unforgettable experience for families and groups.\";s:14:\"description_mr\";s:1088:\"विसावा ॲग्रो टुरिझममध्ये हिवाळ्याच्या दिवसांत खास शेतात तयार होणाऱ्या ताज्या आणि मऊ हुर्ड्यांचा आनंद घ्या! पारंपरिक पद्धतीने निखाऱ्यांवर भाजलेला गरम हुर्डा, सोबत सोलापूर-कोल्हापूर प्रसिद्ध शेंगदाणा व लसूण चटणी, सुके खोबरे आणि अस्सल गावरान गूळ पर्यटकांना दिला जातो. संध्याकाळच्या निसर्गरम्य वातावरणात शेकोटीच्या शेजारी बसून या पारंपरिक खाद्यसंस्कृतीचा आनंद घेणे हा पर्यटकांसाठी एक अविस्मरणीय अनुभव ठरतो.\";s:14:\"description_en\";s:438:\"Experience the authentic taste of winter with our farm-fresh tender Hurda (roasted sorghum) at Visawa Agro Tourism. Roasted to perfection over open embers in traditional style, it is served with authentic garlic & peanut chutneys, dry coconut, and organic jaggery. Relaxing around the cozy evening campfire while savoring this rich Maharashtrian culinary tradition offers a delightful and unforgettable experience for families and groups.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788176558_0OI4x1bFJT.png\";s:4:\"icon\";s:4:\"🌾\";s:10:\"sort_order\";i:4;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T11:42:40+00:00\";}i:4;a:15:{s:2:\"id\";i:70;s:5:\"title\";s:36:\"Traditional Wood-Fired Village Feast\";s:8:\"title_mr\";s:72:\"चुलीवरची अस्सल गावरान जेवण\";s:8:\"title_en\";s:36:\"Traditional Wood-Fired Village Feast\";s:17:\"short_description\";s:96:\"Authentic Maharashtrian farm-to-table dining prepared on traditional wood-fired earthen chulhas.\";s:20:\"short_description_mr\";s:189:\"शेतातील ताज्या भाज्या आणि चुलीवर तयार केलेली झणझणीत गावरान मिसळ व जेवण.\";s:20:\"short_description_en\";s:96:\"Authentic Maharashtrian farm-to-table dining prepared on traditional wood-fired earthen chulhas.\";s:11:\"description\";s:208:\"Relish piping hot bajra and jowar bhakris, authentic pithla-thecha, stuffed brinjal (wangyach bharit), spiciest misal, and traditional Maharashtrian village delicacies cooked over firewood with homemade ghee.\";s:14:\"description_mr\";s:247:\"गरमागरम बाजरी-ज्वारीची भाकरी, पिठलं-ठेचा, वांग्याचं भरीत आणि शुद्ध गावठी तुपातील चविष्ट जेवण.\";s:14:\"description_en\";s:208:\"Relish piping hot bajra and jowar bhakris, authentic pithla-thecha, stuffed brinjal (wangyach bharit), spiciest misal, and traditional Maharashtrian village delicacies cooked over firewood with homemade ghee.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788778361_V2oCFrq0np.png\";s:4:\"icon\";s:4:\"🍲\";s:10:\"sort_order\";i:5;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:5;a:15:{s:2:\"id\";i:72;s:5:\"title\";s:17:\"Bullock Cart Ride\";s:8:\"title_mr\";s:59:\"पारंपारिक बैलगाडी सफर\";s:8:\"title_en\";s:17:\"Bullock Cart Ride\";s:17:\"short_description\";s:85:\"Nostalgic ride on beautifully decorated bullock carts around countryside farm trails.\";s:20:\"short_description_mr\";s:210:\"सजावट केलेल्या पारंपारिक बैलगाडीतून मळ्याच्या बांधावरून रपेट मारण्याचा आनंद.\";s:20:\"short_description_en\";s:85:\"Nostalgic ride on beautifully decorated bullock carts around countryside farm trails.\";s:11:\"description\";s:99:\"Experience rural transport heritage with authentic bullock cart rides across rustic village tracks.\";s:14:\"description_mr\";s:251:\"लहान-मोठ्या सर्वांसाठी बैलगाडीतून फिरण्याचा आणि ग्रामीण संस्कृती अनुभवण्याचा आनंददायी क्षण.\";s:14:\"description_en\";s:99:\"Experience rural transport heritage with authentic bullock cart rides across rustic village tracks.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788179326_cY2nOmcK8E.png\";s:4:\"icon\";s:4:\"🐂\";s:10:\"sort_order\";i:6;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:6;a:15:{s:2:\"id\";i:73;s:5:\"title\";s:11:\"Rural Games\";s:8:\"title_mr\";s:59:\"पारंपारिक ग्रामीण खेळ\";s:8:\"title_en\";s:11:\"Rural Games\";s:17:\"short_description\";s:85:\"Classic outdoor village sports: Viti-Dandu, Lagori, Marbles, Tug-of-war, and archery.\";s:20:\"short_description_mr\";s:184:\"विटी-दांडू, लगोरी, गोट्या, रस्सीखेच आणि जुन्या पारंपारिक खेळांची धमाल.\";s:20:\"short_description_en\";s:85:\"Classic outdoor village sports: Viti-Dandu, Lagori, Marbles, Tug-of-war, and archery.\";s:11:\"description\";s:96:\"Relive childhood nostalgia and bond with family playing traditional Maharashtrian village games.\";s:14:\"description_mr\";s:233:\"मोबाईलपासून दूर मोकळ्या मैदानात विटी-दांडू, लगोरी आणि जुन्या खेळांचा मनमुराद आनंद घ्या.\";s:14:\"description_en\";s:96:\"Relive childhood nostalgia and bond with family playing traditional Maharashtrian village games.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788331695_Bj5T8oj4ry.png\";s:4:\"icon\";s:4:\"🎯\";s:10:\"sort_order\";i:7;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:7;a:15:{s:2:\"id\";i:74;s:5:\"title\";s:22:\"Children’s Play Area\";s:8:\"title_mr\";s:89:\"मुलांचा खेळ परिसर व ॲडव्हेंचर झोन\";s:8:\"title_en\";s:22:\"Children’s Play Area\";s:17:\"short_description\";s:90:\"Dedicated kids outdoor adventure park with swings, slides, nets, trampoline, and sand pit.\";s:20:\"short_description_mr\";s:182:\"झोपाळे, घसरगुंडी, क्लायंबिंग, ट्रॅम्पोलिन आणि वाळूचे सुरक्षित मैदान.\";s:20:\"short_description_en\";s:90:\"Dedicated kids outdoor adventure park with swings, slides, nets, trampoline, and sand pit.\";s:11:\"description\";s:97:\"A safe and vibrant outdoor play space specially designed for kids to enjoy active play in nature.\";s:14:\"description_mr\";s:227:\"निसर्गाच्या मोकळ्या हवेत लहान मुलांच्या आनंदासाठी सुरक्षित आणि सुसज्ज खेळाचे मैदान.\";s:14:\"description_en\";s:97:\"A safe and vibrant outdoor play space specially designed for kids to enjoy active play in nature.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788170567_TA2d7CN5el.jpeg\";s:4:\"icon\";s:4:\"🎈\";s:10:\"sort_order\";i:8;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:8;a:15:{s:2:\"id\";i:75;s:5:\"title\";s:11:\"Nature Walk\";s:8:\"title_mr\";s:82:\"निसर्ग पायवाट व पक्षी निरीक्षण\";s:8:\"title_en\";s:11:\"Nature Walk\";s:17:\"short_description\";s:94:\"Peaceful shaded walking trails through tree groves with fresh morning breezes and bird sounds.\";s:20:\"short_description_mr\";s:203:\"हिरवेगार वृक्ष, फुलांच्या बागा आणि पक्ष्यांच्या किलबिलाटात रम्य पायवाट सफर.\";s:20:\"short_description_en\";s:94:\"Peaceful shaded walking trails through tree groves with fresh morning breezes and bird sounds.\";s:11:\"description\";s:99:\"Breathe fresh unpolluted air, spot native birds, and soak in tranquil greenery along marked trails.\";s:14:\"description_mr\";s:230:\"शहरातील प्रदूषणापासून दूर शांत निसर्गात पक्षांचा किलबिलाट ऐकत निवांत चालण्याचा आनंद.\";s:14:\"description_en\";s:99:\"Breathe fresh unpolluted air, spot native birds, and soak in tranquil greenery along marked trails.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788169295_gkiwKZSVmq.jpeg\";s:4:\"icon\";s:4:\"🌳\";s:10:\"sort_order\";i:9;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:9;a:15:{s:2:\"id\";i:76;s:5:\"title\";s:27:\"Seasonal Farming Activities\";s:8:\"title_mr\";s:98:\"हंगामी शेती कामे व पिक प्रात्यक्षिके\";s:8:\"title_en\";s:27:\"Seasonal Farming Activities\";s:17:\"short_description\";s:85:\"Hands-on vegetable harvesting, seed planting, hurda roasting, and farming traditions.\";s:20:\"short_description_mr\";s:201:\"भाजीपाला खुडणे, बीजारोपण, हुरडा भाजणे आणि शेतीच्या प्रत्यक्ष कामांचा अनुभव.\";s:20:\"short_description_en\";s:85:\"Hands-on vegetable harvesting, seed planting, hurda roasting, and farming traditions.\";s:11:\"description\";s:103:\"Experience the joy of harvesting your own farm-fresh vegetables and participate in seasonal traditions.\";s:14:\"description_mr\";s:237:\"प्रत्यक्ष शेतात उतरून भाजीपाला खुडणे, बी लावणे आणि हुरडा पार्टीचा खरा ग्रामीण अनुभव घ्या.\";s:14:\"description_en\";s:103:\"Experience the joy of harvesting your own farm-fresh vegetables and participate in seasonal traditions.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788173346_3RDB1EXAqd.jpeg\";s:4:\"icon\";s:4:\"🌱\";s:10:\"sort_order\";i:10;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:10;a:15:{s:2:\"id\";i:71;s:5:\"title\";s:10:\"Farm Visit\";s:8:\"title_mr\";s:70:\"सेंद्रिय शेती व शिवार फेरी\";s:8:\"title_en\";s:10:\"Farm Visit\";s:17:\"short_description\";s:83:\"Educational agro-tour across 15 acres of organic crops, polyhouses, and vegetation.\";s:20:\"short_description_mr\";s:207:\"सेंद्रिय शेती, भाजीपाला आणि विविध पिकांची माहिती देणारी प्रत्यक्ष शिवार फेरी.\";s:20:\"short_description_en\";s:83:\"Educational agro-tour across 15 acres of organic crops, polyhouses, and vegetation.\";s:11:\"description\";s:106:\"Explore sustainable organic farming methods, visit green polyhouses, and reconnect with agriculture roots.\";s:14:\"description_mr\";s:219:\"सेंद्रिय शेती, आधुनिक तंत्रज्ञान आणि हिरवेगार शिवार जवळून अनुभवण्याची उत्तम संधी.\";s:14:\"description_en\";s:106:\"Explore sustainable organic farming methods, visit green polyhouses, and reconnect with agriculture roots.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788171036_JHYDURV2Zk.jpeg\";s:4:\"icon\";s:4:\"🌾\";s:10:\"sort_order\";i:11;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:11;a:15:{s:2:\"id\";i:77;s:5:\"title\";s:32:\"Agricultural Awareness & Culture\";s:8:\"title_mr\";s:88:\"शेती मार्गदर्शन व संस्कार केंद्र\";s:8:\"title_en\";s:32:\"Agricultural Awareness & Culture\";s:17:\"short_description\";s:90:\"Educational awareness about farmers\' hard work and the cultural importance of saving food.\";s:20:\"short_description_mr\";s:221:\"शेतकर्‍यांची मेहनत आणि अन्न वाचवण्याचा संदेश देणारा शैक्षणिक व सांस्कृतिक उपक्रम.\";s:20:\"short_description_en\";s:90:\"Educational awareness about farmers\' hard work and the cultural importance of saving food.\";s:11:\"description\";s:248:\"At Visawa Agro Tourism, we impart values regarding farming and food respect to children and tourists. This activity highlights the dedication of farmers, explaining the lifecycle of crops and promoting the cultural significance of not wasting food.\";s:14:\"description_mr\";s:602:\"विसावा ॲग्रो टुरिझममध्ये येणाऱ्या लहान मुलांना आणि पर्यटकांना शेतीचे महत्त्व, धान्याची निर्मिती आणि अन्नाचा आदर करण्याचे संस्कार दिले जातात. बळीराजाच्या कष्टातून अन्न कसे तयार होते याची जाणीव करून देणारा हा विशेष उपक्रम आहे.\";s:14:\"description_en\";s:248:\"At Visawa Agro Tourism, we impart values regarding farming and food respect to children and tourists. This activity highlights the dedication of farmers, explaining the lifecycle of crops and promoting the cultural significance of not wasting food.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788175548_DtvSEwNtKP.jpeg\";s:4:\"icon\";s:4:\"🌾\";s:10:\"sort_order\";i:12;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T11:25:50+00:00\";}i:12;a:15:{s:2:\"id\";i:79;s:5:\"title\";s:34:\"Vintage Selfie Spots & Photography\";s:8:\"title_mr\";s:82:\"फोटो पॉईंट्स व आठवणींचे केंद्र\";s:8:\"title_en\";s:34:\"Vintage Selfie Spots & Photography\";s:17:\"short_description\";s:69:\"Nostalgic vintage telephone booth spots perfect for photos and reels.\";s:20:\"short_description_mr\";s:170:\"पर्यटकांसाठी जुन्या आठवणींना उजाळा देणारे विंटेज फोटो पॉईंट्स.\";s:20:\"short_description_en\";s:69:\"Nostalgic vintage telephone booth spots perfect for photos and reels.\";s:11:\"description\";s:233:\"The vintage yellow STD PCO booth at Visawa Agro Tourism offers a nostalgic retro backdrop for guests. Surrounded by lush greenery, it is the perfect spot for taking memorable family photos, portraits, and creative social media reels.\";s:14:\"description_mr\";s:683:\"विसावा ॲग्रो टुरिझममधील पिवळाधम्मक विंटेज STD PCO टेलीफोन बूथ पर्यटकांसाठी जुन्या आठवणींना उजाळा देणारा एक खास फोटो पॉईंट आहे. निसर्गरम्य पार्श्वभूमीत कुटुंब आणि मित्रांसोबत सुंदर फोटोज, पोर्ट्रेट्स आणि सोशल मीडिया रील्स (Reels) काढण्यासाठी हे एक उत्तम ठिकाण आहे.\";s:14:\"description_en\";s:233:\"The vintage yellow STD PCO booth at Visawa Agro Tourism offers a nostalgic retro backdrop for guests. Surrounded by lush greenery, it is the perfect spot for taking memorable family photos, portraits, and creative social media reels.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788178485_WhiTwppnRF.jpeg\";s:4:\"icon\";s:4:\"📸\";s:10:\"sort_order\";i:13;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T12:14:49+00:00\";}i:13;a:15:{s:2:\"id\";i:80;s:5:\"title\";s:34:\"Cultural Heritage & Folk Tradition\";s:8:\"title_mr\";s:93:\"महाराष्ट्राची लोकसंस्कृती व वारसा\";s:8:\"title_en\";s:34:\"Cultural Heritage & Folk Tradition\";s:17:\"short_description\";s:73:\"Experience the rich Maharashtrian culture and traditional heritage spots.\";s:20:\"short_description_mr\";s:164:\"महाराष्ट्राच्या समृद्ध लोककला आणि विंटेज संस्कृतीची खास झलक.\";s:20:\"short_description_en\";s:73:\"Experience the rich Maharashtrian culture and traditional heritage spots.\";s:11:\"description\";s:397:\"Experience the rich cultural roots of Maharashtra at Visawa Agro Tourism. This dedicated cultural selfie spot features a traditional Maharashtrian Varkari and folk artist statue, offering guests a glimpse into the state\'s vibrant heritage. Surrounded by scenic views, it serves as a wonderful backdrop for families and visitors to take memorable photos and connect with authentic rural traditions.\";s:14:\"description_mr\";s:1056:\"विसावा ॲग्रो टुरिझममध्ये महाराष्ट्राच्या समृद्ध लोकसंस्कृती आणि परंपरेचा अनोखा संगम अनुभवा. पर्यटकांना आपल्या मातीशी जोडणाऱ्या या सांस्कृतिक फोटो पॉईंटवर पारंपरिक वारकरी आणि शाहीर संस्कृतीची विलोभनीय मूर्ती उभारण्यात आली आहे. ग्रामीण पर्यटनाचा आनंद घेताना कुटुंब आणि मित्रांसोबत महाराष्ट्राच्या लोककलेचा हा समृद्ध वारसा कॅमेऱ्यात कैद करण्यासाठी आणि आठवणी जपण्यासाठी हे एक उत्तम ठिकाण आहे.\";s:14:\"description_en\";s:397:\"Experience the rich cultural roots of Maharashtra at Visawa Agro Tourism. This dedicated cultural selfie spot features a traditional Maharashtrian Varkari and folk artist statue, offering guests a glimpse into the state\'s vibrant heritage. Surrounded by scenic views, it serves as a wonderful backdrop for families and visitors to take memorable photos and connect with authentic rural traditions.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788237689_pCaDQabfwK.jpeg\";s:4:\"icon\";s:4:\"🎭\";s:10:\"sort_order\";i:14;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-09-01T04:41:34+00:00\";}}', 1788794117),
('visava-cache-api_activities_mr', 'a:14:{i:0;a:15:{s:2:\"id\";i:67;s:5:\"title\";s:89:\"स्वच्छ स्विमिंग पूल व विहीर स्नान\";s:8:\"title_mr\";s:89:\"स्वच्छ स्विमिंग पूल व विहीर स्नान\";s:8:\"title_en\";s:13:\"Swimming Pool\";s:17:\"short_description\";s:221:\"शुद्ध आणि स्वच्छ पाण्याचा स्विमिंग पूल, लहान मुलांचा पूल आणि पारंपारिक विहीर स्नान.\";s:20:\"short_description_mr\";s:221:\"शुद्ध आणि स्वच्छ पाण्याचा स्विमिंग पूल, लहान मुलांचा पूल आणि पारंपारिक विहीर स्नान.\";s:20:\"short_description_en\";s:102:\"Crystal-clear filtered swimming pool with kids splash area and authentic farm well bathing experience.\";s:11:\"description\";s:307:\"उन्हाळ्याच्या आणि सुट्टीच्या दिवसात संपूर्ण कुटुंबासाठी मनसोक्त जलविहार आणि पारंपारिक विहिरीच्या पाण्याचा आनंद.\";s:14:\"description_mr\";s:307:\"उन्हाळ्याच्या आणि सुट्टीच्या दिवसात संपूर्ण कुटुंबासाठी मनसोक्त जलविहार आणि पारंपारिक विहिरीच्या पाण्याचा आनंद.\";s:14:\"description_en\";s:117:\"Relax and refresh in our hygienic swimming pool amidst nature, featuring filtered water and traditional well bathing.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788174622_MGV4dIsKNK.png\";s:4:\"icon\";s:13:\"🏊‍♂️\";s:10:\"sort_order\";i:1;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:1;a:15:{s:2:\"id\";i:68;s:5:\"title\";s:76:\"रेन डान्स आणि म्युझिक पार्टी\";s:8:\"title_mr\";s:76:\"रेन डान्स आणि म्युझिक पार्टी\";s:8:\"title_en\";s:10:\"Rain Dance\";s:17:\"short_description\";s:204:\"थंडगार पाण्याच्या सरींमध्ये डीजे संगीताच्या तालावर मनमुराद नाचण्याचा आनंद.\";s:20:\"short_description_mr\";s:204:\"थंडगार पाण्याच्या सरींमध्ये डीजे संगीताच्या तालावर मनमुराद नाचण्याचा आनंद.\";s:20:\"short_description_en\";s:79:\"High-energy rain dance floor with cool water mist showers and live music beats.\";s:11:\"description\";s:233:\"मित्र आणि कुटुंबासह संगीताच्या तालावर थंडगार पाण्याच्या सरींखाली आनंदोत्सव साजरा करा.\";s:14:\"description_mr\";s:233:\"मित्र आणि कुटुंबासह संगीताच्या तालावर थंडगार पाण्याच्या सरींखाली आनंदोत्सव साजरा करा.\";s:14:\"description_en\";s:106:\"Celebrate joyful moments with family and friends on our spacious rain dance arena with high-quality sound.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788176575_9F5sehyrIH.png\";s:4:\"icon\";s:4:\"🎵\";s:10:\"sort_order\";i:2;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:2;a:15:{s:2:\"id\";i:69;s:5:\"title\";s:63:\"द्राक्ष बागा शिवार फेरी\";s:8:\"title_mr\";s:63:\"द्राक्ष बागा शिवार फेरी\";s:8:\"title_en\";s:19:\"Grape Vineyard Tour\";s:17:\"short_description\";s:181:\"१५ एकर विस्तीर्ण द्राक्ष बागा आणि फळबागांची मार्गदर्शित शिवार फेरी.\";s:20:\"short_description_mr\";s:181:\"१५ एकर विस्तीर्ण द्राक्ष बागा आणि फळबागांची मार्गदर्शित शिवार फेरी.\";s:20:\"short_description_en\";s:80:\"Guided educational walk through lush grape vineyards and organic fruit orchards.\";s:11:\"description\";s:258:\"विस्तीर्ण द्राक्ष बागांमध्ये फिरा, आधुनिक शेती पद्धतींची माहिती घ्या आणि गोड फळांचा आस्वाद घ्या.\";s:14:\"description_mr\";s:258:\"विस्तीर्ण द्राक्ष बागांमध्ये फिरा, आधुनिक शेती पद्धतींची माहिती घ्या आणि गोड फळांचा आस्वाद घ्या.\";s:14:\"description_en\";s:105:\"Stroll through sprawling vineyards, learn about cultivation techniques, and taste freshly plucked fruits.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788170900_Pnw5Bsuk4r.jpeg\";s:4:\"icon\";s:4:\"🍇\";s:10:\"sort_order\";i:3;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:3;a:15:{s:2:\"id\";i:78;s:5:\"title\";s:72:\"अस्सल गावरान हुर्डा पार्टी\";s:8:\"title_mr\";s:72:\"अस्सल गावरान हुर्डा पार्टी\";s:8:\"title_en\";s:29:\"Authentic Village Hurda Party\";s:17:\"short_description\";s:224:\"शेकोटीवर भाजलेला गरमागरम ताजा हुर्डा, सोबत गुळ, सुके खोबरे आणि झणझणीत चटण्यांचा आनंद\";s:20:\"short_description_mr\";s:224:\"शेकोटीवर भाजलेला गरमागरम ताजा हुर्डा, सोबत गुळ, सुके खोबरे आणि झणझणीत चटण्यांचा आनंद\";s:20:\"short_description_en\";s:98:\"Enjoy fresh roasted tender jowar (Hurda) over open fire with jaggery and authentic spicy chutneys.\";s:11:\"description\";s:1088:\"विसावा ॲग्रो टुरिझममध्ये हिवाळ्याच्या दिवसांत खास शेतात तयार होणाऱ्या ताज्या आणि मऊ हुर्ड्यांचा आनंद घ्या! पारंपरिक पद्धतीने निखाऱ्यांवर भाजलेला गरम हुर्डा, सोबत सोलापूर-कोल्हापूर प्रसिद्ध शेंगदाणा व लसूण चटणी, सुके खोबरे आणि अस्सल गावरान गूळ पर्यटकांना दिला जातो. संध्याकाळच्या निसर्गरम्य वातावरणात शेकोटीच्या शेजारी बसून या पारंपरिक खाद्यसंस्कृतीचा आनंद घेणे हा पर्यटकांसाठी एक अविस्मरणीय अनुभव ठरतो.\";s:14:\"description_mr\";s:1088:\"विसावा ॲग्रो टुरिझममध्ये हिवाळ्याच्या दिवसांत खास शेतात तयार होणाऱ्या ताज्या आणि मऊ हुर्ड्यांचा आनंद घ्या! पारंपरिक पद्धतीने निखाऱ्यांवर भाजलेला गरम हुर्डा, सोबत सोलापूर-कोल्हापूर प्रसिद्ध शेंगदाणा व लसूण चटणी, सुके खोबरे आणि अस्सल गावरान गूळ पर्यटकांना दिला जातो. संध्याकाळच्या निसर्गरम्य वातावरणात शेकोटीच्या शेजारी बसून या पारंपरिक खाद्यसंस्कृतीचा आनंद घेणे हा पर्यटकांसाठी एक अविस्मरणीय अनुभव ठरतो.\";s:14:\"description_en\";s:438:\"Experience the authentic taste of winter with our farm-fresh tender Hurda (roasted sorghum) at Visawa Agro Tourism. Roasted to perfection over open embers in traditional style, it is served with authentic garlic & peanut chutneys, dry coconut, and organic jaggery. Relaxing around the cozy evening campfire while savoring this rich Maharashtrian culinary tradition offers a delightful and unforgettable experience for families and groups.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788176558_0OI4x1bFJT.png\";s:4:\"icon\";s:4:\"🌾\";s:10:\"sort_order\";i:4;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T11:42:40+00:00\";}i:4;a:15:{s:2:\"id\";i:70;s:5:\"title\";s:72:\"चुलीवरची अस्सल गावरान जेवण\";s:8:\"title_mr\";s:72:\"चुलीवरची अस्सल गावरान जेवण\";s:8:\"title_en\";s:36:\"Traditional Wood-Fired Village Feast\";s:17:\"short_description\";s:189:\"शेतातील ताज्या भाज्या आणि चुलीवर तयार केलेली झणझणीत गावरान मिसळ व जेवण.\";s:20:\"short_description_mr\";s:189:\"शेतातील ताज्या भाज्या आणि चुलीवर तयार केलेली झणझणीत गावरान मिसळ व जेवण.\";s:20:\"short_description_en\";s:96:\"Authentic Maharashtrian farm-to-table dining prepared on traditional wood-fired earthen chulhas.\";s:11:\"description\";s:247:\"गरमागरम बाजरी-ज्वारीची भाकरी, पिठलं-ठेचा, वांग्याचं भरीत आणि शुद्ध गावठी तुपातील चविष्ट जेवण.\";s:14:\"description_mr\";s:247:\"गरमागरम बाजरी-ज्वारीची भाकरी, पिठलं-ठेचा, वांग्याचं भरीत आणि शुद्ध गावठी तुपातील चविष्ट जेवण.\";s:14:\"description_en\";s:208:\"Relish piping hot bajra and jowar bhakris, authentic pithla-thecha, stuffed brinjal (wangyach bharit), spiciest misal, and traditional Maharashtrian village delicacies cooked over firewood with homemade ghee.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788778361_V2oCFrq0np.png\";s:4:\"icon\";s:4:\"🍲\";s:10:\"sort_order\";i:5;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:5;a:15:{s:2:\"id\";i:72;s:5:\"title\";s:59:\"पारंपारिक बैलगाडी सफर\";s:8:\"title_mr\";s:59:\"पारंपारिक बैलगाडी सफर\";s:8:\"title_en\";s:17:\"Bullock Cart Ride\";s:17:\"short_description\";s:210:\"सजावट केलेल्या पारंपारिक बैलगाडीतून मळ्याच्या बांधावरून रपेट मारण्याचा आनंद.\";s:20:\"short_description_mr\";s:210:\"सजावट केलेल्या पारंपारिक बैलगाडीतून मळ्याच्या बांधावरून रपेट मारण्याचा आनंद.\";s:20:\"short_description_en\";s:85:\"Nostalgic ride on beautifully decorated bullock carts around countryside farm trails.\";s:11:\"description\";s:251:\"लहान-मोठ्या सर्वांसाठी बैलगाडीतून फिरण्याचा आणि ग्रामीण संस्कृती अनुभवण्याचा आनंददायी क्षण.\";s:14:\"description_mr\";s:251:\"लहान-मोठ्या सर्वांसाठी बैलगाडीतून फिरण्याचा आणि ग्रामीण संस्कृती अनुभवण्याचा आनंददायी क्षण.\";s:14:\"description_en\";s:99:\"Experience rural transport heritage with authentic bullock cart rides across rustic village tracks.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788179326_cY2nOmcK8E.png\";s:4:\"icon\";s:4:\"🐂\";s:10:\"sort_order\";i:6;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:6;a:15:{s:2:\"id\";i:73;s:5:\"title\";s:59:\"पारंपारिक ग्रामीण खेळ\";s:8:\"title_mr\";s:59:\"पारंपारिक ग्रामीण खेळ\";s:8:\"title_en\";s:11:\"Rural Games\";s:17:\"short_description\";s:184:\"विटी-दांडू, लगोरी, गोट्या, रस्सीखेच आणि जुन्या पारंपारिक खेळांची धमाल.\";s:20:\"short_description_mr\";s:184:\"विटी-दांडू, लगोरी, गोट्या, रस्सीखेच आणि जुन्या पारंपारिक खेळांची धमाल.\";s:20:\"short_description_en\";s:85:\"Classic outdoor village sports: Viti-Dandu, Lagori, Marbles, Tug-of-war, and archery.\";s:11:\"description\";s:233:\"मोबाईलपासून दूर मोकळ्या मैदानात विटी-दांडू, लगोरी आणि जुन्या खेळांचा मनमुराद आनंद घ्या.\";s:14:\"description_mr\";s:233:\"मोबाईलपासून दूर मोकळ्या मैदानात विटी-दांडू, लगोरी आणि जुन्या खेळांचा मनमुराद आनंद घ्या.\";s:14:\"description_en\";s:96:\"Relive childhood nostalgia and bond with family playing traditional Maharashtrian village games.\";s:5:\"image\";s:74:\"http://127.0.0.1:8000/storage/uploads/activities/1788331695_Bj5T8oj4ry.png\";s:4:\"icon\";s:4:\"🎯\";s:10:\"sort_order\";i:7;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:7;a:15:{s:2:\"id\";i:74;s:5:\"title\";s:89:\"मुलांचा खेळ परिसर व ॲडव्हेंचर झोन\";s:8:\"title_mr\";s:89:\"मुलांचा खेळ परिसर व ॲडव्हेंचर झोन\";s:8:\"title_en\";s:22:\"Children’s Play Area\";s:17:\"short_description\";s:182:\"झोपाळे, घसरगुंडी, क्लायंबिंग, ट्रॅम्पोलिन आणि वाळूचे सुरक्षित मैदान.\";s:20:\"short_description_mr\";s:182:\"झोपाळे, घसरगुंडी, क्लायंबिंग, ट्रॅम्पोलिन आणि वाळूचे सुरक्षित मैदान.\";s:20:\"short_description_en\";s:90:\"Dedicated kids outdoor adventure park with swings, slides, nets, trampoline, and sand pit.\";s:11:\"description\";s:227:\"निसर्गाच्या मोकळ्या हवेत लहान मुलांच्या आनंदासाठी सुरक्षित आणि सुसज्ज खेळाचे मैदान.\";s:14:\"description_mr\";s:227:\"निसर्गाच्या मोकळ्या हवेत लहान मुलांच्या आनंदासाठी सुरक्षित आणि सुसज्ज खेळाचे मैदान.\";s:14:\"description_en\";s:97:\"A safe and vibrant outdoor play space specially designed for kids to enjoy active play in nature.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788170567_TA2d7CN5el.jpeg\";s:4:\"icon\";s:4:\"🎈\";s:10:\"sort_order\";i:8;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:8;a:15:{s:2:\"id\";i:75;s:5:\"title\";s:82:\"निसर्ग पायवाट व पक्षी निरीक्षण\";s:8:\"title_mr\";s:82:\"निसर्ग पायवाट व पक्षी निरीक्षण\";s:8:\"title_en\";s:11:\"Nature Walk\";s:17:\"short_description\";s:203:\"हिरवेगार वृक्ष, फुलांच्या बागा आणि पक्ष्यांच्या किलबिलाटात रम्य पायवाट सफर.\";s:20:\"short_description_mr\";s:203:\"हिरवेगार वृक्ष, फुलांच्या बागा आणि पक्ष्यांच्या किलबिलाटात रम्य पायवाट सफर.\";s:20:\"short_description_en\";s:94:\"Peaceful shaded walking trails through tree groves with fresh morning breezes and bird sounds.\";s:11:\"description\";s:230:\"शहरातील प्रदूषणापासून दूर शांत निसर्गात पक्षांचा किलबिलाट ऐकत निवांत चालण्याचा आनंद.\";s:14:\"description_mr\";s:230:\"शहरातील प्रदूषणापासून दूर शांत निसर्गात पक्षांचा किलबिलाट ऐकत निवांत चालण्याचा आनंद.\";s:14:\"description_en\";s:99:\"Breathe fresh unpolluted air, spot native birds, and soak in tranquil greenery along marked trails.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788169295_gkiwKZSVmq.jpeg\";s:4:\"icon\";s:4:\"🌳\";s:10:\"sort_order\";i:9;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:9;a:15:{s:2:\"id\";i:76;s:5:\"title\";s:98:\"हंगामी शेती कामे व पिक प्रात्यक्षिके\";s:8:\"title_mr\";s:98:\"हंगामी शेती कामे व पिक प्रात्यक्षिके\";s:8:\"title_en\";s:27:\"Seasonal Farming Activities\";s:17:\"short_description\";s:201:\"भाजीपाला खुडणे, बीजारोपण, हुरडा भाजणे आणि शेतीच्या प्रत्यक्ष कामांचा अनुभव.\";s:20:\"short_description_mr\";s:201:\"भाजीपाला खुडणे, बीजारोपण, हुरडा भाजणे आणि शेतीच्या प्रत्यक्ष कामांचा अनुभव.\";s:20:\"short_description_en\";s:85:\"Hands-on vegetable harvesting, seed planting, hurda roasting, and farming traditions.\";s:11:\"description\";s:237:\"प्रत्यक्ष शेतात उतरून भाजीपाला खुडणे, बी लावणे आणि हुरडा पार्टीचा खरा ग्रामीण अनुभव घ्या.\";s:14:\"description_mr\";s:237:\"प्रत्यक्ष शेतात उतरून भाजीपाला खुडणे, बी लावणे आणि हुरडा पार्टीचा खरा ग्रामीण अनुभव घ्या.\";s:14:\"description_en\";s:103:\"Experience the joy of harvesting your own farm-fresh vegetables and participate in seasonal traditions.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788173346_3RDB1EXAqd.jpeg\";s:4:\"icon\";s:4:\"🌱\";s:10:\"sort_order\";i:10;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:10;a:15:{s:2:\"id\";i:71;s:5:\"title\";s:70:\"सेंद्रिय शेती व शिवार फेरी\";s:8:\"title_mr\";s:70:\"सेंद्रिय शेती व शिवार फेरी\";s:8:\"title_en\";s:10:\"Farm Visit\";s:17:\"short_description\";s:207:\"सेंद्रिय शेती, भाजीपाला आणि विविध पिकांची माहिती देणारी प्रत्यक्ष शिवार फेरी.\";s:20:\"short_description_mr\";s:207:\"सेंद्रिय शेती, भाजीपाला आणि विविध पिकांची माहिती देणारी प्रत्यक्ष शिवार फेरी.\";s:20:\"short_description_en\";s:83:\"Educational agro-tour across 15 acres of organic crops, polyhouses, and vegetation.\";s:11:\"description\";s:219:\"सेंद्रिय शेती, आधुनिक तंत्रज्ञान आणि हिरवेगार शिवार जवळून अनुभवण्याची उत्तम संधी.\";s:14:\"description_mr\";s:219:\"सेंद्रिय शेती, आधुनिक तंत्रज्ञान आणि हिरवेगार शिवार जवळून अनुभवण्याची उत्तम संधी.\";s:14:\"description_en\";s:106:\"Explore sustainable organic farming methods, visit green polyhouses, and reconnect with agriculture roots.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788171036_JHYDURV2Zk.jpeg\";s:4:\"icon\";s:4:\"🌾\";s:10:\"sort_order\";i:11;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:11;a:15:{s:2:\"id\";i:77;s:5:\"title\";s:88:\"शेती मार्गदर्शन व संस्कार केंद्र\";s:8:\"title_mr\";s:88:\"शेती मार्गदर्शन व संस्कार केंद्र\";s:8:\"title_en\";s:32:\"Agricultural Awareness & Culture\";s:17:\"short_description\";s:221:\"शेतकर्‍यांची मेहनत आणि अन्न वाचवण्याचा संदेश देणारा शैक्षणिक व सांस्कृतिक उपक्रम.\";s:20:\"short_description_mr\";s:221:\"शेतकर्‍यांची मेहनत आणि अन्न वाचवण्याचा संदेश देणारा शैक्षणिक व सांस्कृतिक उपक्रम.\";s:20:\"short_description_en\";s:90:\"Educational awareness about farmers\' hard work and the cultural importance of saving food.\";s:11:\"description\";s:602:\"विसावा ॲग्रो टुरिझममध्ये येणाऱ्या लहान मुलांना आणि पर्यटकांना शेतीचे महत्त्व, धान्याची निर्मिती आणि अन्नाचा आदर करण्याचे संस्कार दिले जातात. बळीराजाच्या कष्टातून अन्न कसे तयार होते याची जाणीव करून देणारा हा विशेष उपक्रम आहे.\";s:14:\"description_mr\";s:602:\"विसावा ॲग्रो टुरिझममध्ये येणाऱ्या लहान मुलांना आणि पर्यटकांना शेतीचे महत्त्व, धान्याची निर्मिती आणि अन्नाचा आदर करण्याचे संस्कार दिले जातात. बळीराजाच्या कष्टातून अन्न कसे तयार होते याची जाणीव करून देणारा हा विशेष उपक्रम आहे.\";s:14:\"description_en\";s:248:\"At Visawa Agro Tourism, we impart values regarding farming and food respect to children and tourists. This activity highlights the dedication of farmers, explaining the lifecycle of crops and promoting the cultural significance of not wasting food.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788175548_DtvSEwNtKP.jpeg\";s:4:\"icon\";s:4:\"🌾\";s:10:\"sort_order\";i:12;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T11:25:50+00:00\";}i:12;a:15:{s:2:\"id\";i:79;s:5:\"title\";s:82:\"फोटो पॉईंट्स व आठवणींचे केंद्र\";s:8:\"title_mr\";s:82:\"फोटो पॉईंट्स व आठवणींचे केंद्र\";s:8:\"title_en\";s:34:\"Vintage Selfie Spots & Photography\";s:17:\"short_description\";s:170:\"पर्यटकांसाठी जुन्या आठवणींना उजाळा देणारे विंटेज फोटो पॉईंट्स.\";s:20:\"short_description_mr\";s:170:\"पर्यटकांसाठी जुन्या आठवणींना उजाळा देणारे विंटेज फोटो पॉईंट्स.\";s:20:\"short_description_en\";s:69:\"Nostalgic vintage telephone booth spots perfect for photos and reels.\";s:11:\"description\";s:683:\"विसावा ॲग्रो टुरिझममधील पिवळाधम्मक विंटेज STD PCO टेलीफोन बूथ पर्यटकांसाठी जुन्या आठवणींना उजाळा देणारा एक खास फोटो पॉईंट आहे. निसर्गरम्य पार्श्वभूमीत कुटुंब आणि मित्रांसोबत सुंदर फोटोज, पोर्ट्रेट्स आणि सोशल मीडिया रील्स (Reels) काढण्यासाठी हे एक उत्तम ठिकाण आहे.\";s:14:\"description_mr\";s:683:\"विसावा ॲग्रो टुरिझममधील पिवळाधम्मक विंटेज STD PCO टेलीफोन बूथ पर्यटकांसाठी जुन्या आठवणींना उजाळा देणारा एक खास फोटो पॉईंट आहे. निसर्गरम्य पार्श्वभूमीत कुटुंब आणि मित्रांसोबत सुंदर फोटोज, पोर्ट्रेट्स आणि सोशल मीडिया रील्स (Reels) काढण्यासाठी हे एक उत्तम ठिकाण आहे.\";s:14:\"description_en\";s:233:\"The vintage yellow STD PCO booth at Visawa Agro Tourism offers a nostalgic retro backdrop for guests. Surrounded by lush greenery, it is the perfect spot for taking memorable family photos, portraits, and creative social media reels.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788178485_WhiTwppnRF.jpeg\";s:4:\"icon\";s:4:\"📸\";s:10:\"sort_order\";i:13;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-08-31T12:14:49+00:00\";}i:13;a:15:{s:2:\"id\";i:80;s:5:\"title\";s:93:\"महाराष्ट्राची लोकसंस्कृती व वारसा\";s:8:\"title_mr\";s:93:\"महाराष्ट्राची लोकसंस्कृती व वारसा\";s:8:\"title_en\";s:34:\"Cultural Heritage & Folk Tradition\";s:17:\"short_description\";s:164:\"महाराष्ट्राच्या समृद्ध लोककला आणि विंटेज संस्कृतीची खास झलक.\";s:20:\"short_description_mr\";s:164:\"महाराष्ट्राच्या समृद्ध लोककला आणि विंटेज संस्कृतीची खास झलक.\";s:20:\"short_description_en\";s:73:\"Experience the rich Maharashtrian culture and traditional heritage spots.\";s:11:\"description\";s:1056:\"विसावा ॲग्रो टुरिझममध्ये महाराष्ट्राच्या समृद्ध लोकसंस्कृती आणि परंपरेचा अनोखा संगम अनुभवा. पर्यटकांना आपल्या मातीशी जोडणाऱ्या या सांस्कृतिक फोटो पॉईंटवर पारंपरिक वारकरी आणि शाहीर संस्कृतीची विलोभनीय मूर्ती उभारण्यात आली आहे. ग्रामीण पर्यटनाचा आनंद घेताना कुटुंब आणि मित्रांसोबत महाराष्ट्राच्या लोककलेचा हा समृद्ध वारसा कॅमेऱ्यात कैद करण्यासाठी आणि आठवणी जपण्यासाठी हे एक उत्तम ठिकाण आहे.\";s:14:\"description_mr\";s:1056:\"विसावा ॲग्रो टुरिझममध्ये महाराष्ट्राच्या समृद्ध लोकसंस्कृती आणि परंपरेचा अनोखा संगम अनुभवा. पर्यटकांना आपल्या मातीशी जोडणाऱ्या या सांस्कृतिक फोटो पॉईंटवर पारंपरिक वारकरी आणि शाहीर संस्कृतीची विलोभनीय मूर्ती उभारण्यात आली आहे. ग्रामीण पर्यटनाचा आनंद घेताना कुटुंब आणि मित्रांसोबत महाराष्ट्राच्या लोककलेचा हा समृद्ध वारसा कॅमेऱ्यात कैद करण्यासाठी आणि आठवणी जपण्यासाठी हे एक उत्तम ठिकाण आहे.\";s:14:\"description_en\";s:397:\"Experience the rich cultural roots of Maharashtra at Visawa Agro Tourism. This dedicated cultural selfie spot features a traditional Maharashtrian Varkari and folk artist statue, offering guests a glimpse into the state\'s vibrant heritage. Surrounded by scenic views, it serves as a wonderful backdrop for families and visitors to take memorable photos and connect with authentic rural traditions.\";s:5:\"image\";s:75:\"http://127.0.0.1:8000/storage/uploads/activities/1788237689_pCaDQabfwK.jpeg\";s:4:\"icon\";s:4:\"🎭\";s:10:\"sort_order\";i:14;s:9:\"is_active\";b:1;s:10:\"created_at\";s:25:\"2026-09-01T04:41:34+00:00\";}}', 1788782275);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('visava-cache-api_blogs_en', 'a:4:{i:0;a:20:{s:2:\"id\";i:8;s:5:\"title\";s:57:\"Welcome to VISAWA Agro Tourism – Your Gateway to Nature\";s:8:\"title_mr\";s:128:\"विसावा ॲग्रो टुरिझममध्ये आपले मनःपूर्वक स्वागत\";s:8:\"title_en\";s:57:\"Welcome to VISAWA Agro Tourism – Your Gateway to Nature\";s:4:\"slug\";s:59:\"welcome-to-visawa-agro-tourism-your-gateway-to-nature-gWA2j\";s:17:\"short_description\";s:201:\"Experience the peaceful entrance of VISAWA Agro Tourism surrounded by lush greenery, open landscapes, and authentic village charm. Step into a relaxing getaway where nature and tradition come together.\";s:20:\"short_description_mr\";s:419:\"हिरव्यागार झाडांनी वेढलेला सुंदर प्रवेशद्वार, मोकळे निसर्गरम्य वातावरण आणि अस्सल ग्रामीण सौंदर्य अनुभवण्यासाठी विसावा अॅग्रो टुरिझममध्ये आपले स्वागत आहे.\";s:20:\"short_description_en\";s:201:\"Experience the peaceful entrance of VISAWA Agro Tourism surrounded by lush greenery, open landscapes, and authentic village charm. Step into a relaxing getaway where nature and tradition come together.\";s:11:\"description\";s:1128:\"Welcome to VISAWA Agro Tourism – Babacha Mala\r\n\r\nEvery journey at VISAWA Agro Tourism begins with a warm village welcome. As you enter through the beautiful entrance surrounded by lush green trees and fresh countryside air, you\'ll instantly experience the peaceful atmosphere that makes VISAWA special.\r\n\r\nThe scenic entrance leads you into a spacious agro-tourism destination where nature, tradition, and comfort come together. Beautiful walkways, open landscapes, and a refreshing environment make it the perfect escape from busy city life.\r\n\r\nWhat makes VISAWA special?\r\n\r\nAuthentic Maharashtrian village cuisine\r\n\r\nTraditional rural games and activities\r\n\r\nFarm and nature experiences\r\n\r\nPeaceful open surroundings\r\n\r\nPerfect for families, couples, and groups\r\n\r\nWhether you\'re planning a day picnic, weekend stay, family outing, or corporate gathering, VISAWA offers unforgettable moments in the heart of nature.\r\n\r\nThis short video gives you a glimpse of our beautiful entrance and serene surroundings—an invitation to experience the charm of rural Maharashtra.\r\n\r\nVISAWA Agro Tourism – Where Nature Meets Tradition.\";s:14:\"description_mr\";s:2376:\"विसावा ॲग्रो टुरिझम – बाबांचा मळा येथे प्रत्येक प्रवासाची सुरुवात होते एका सुंदर ग्रामीण स्वागताने.\r\n\r\nहिरव्यागार झाडांनी वेढलेला प्रवेशमार्ग, ताजी हवा आणि शांत वातावरण पाहताच मनाला एक वेगळाच विसावा मिळतो. हा निसर्गरम्य परिसर शहराच्या धकाधकीपासून दूर शांत आणि आनंददायी अनुभव देतो.\r\n\r\nप्रवेशद्वारातून आत आल्यानंतर विस्तीर्ण परिसर, सुंदर पायवाटा आणि ग्रामीण संस्कृतीची झलक प्रत्येक पाहुण्याला निसर्गाच्या अधिक जवळ घेऊन जाते.\r\n\r\nविसावा ॲग्रो टुरिझममध्ये तुम्हाला मिळतो—\r\n\r\nअस्सल महाराष्ट्रीयन गावरान जेवण\r\n\r\nपारंपरिक ग्रामीण खेळ\r\n\r\nशेतीचा प्रत्यक्ष अनुभव\r\n\r\nकुटुंब आणि मित्रांसोबत निवांत क्षण\r\n\r\nशांत, स्वच्छ आणि हिरवागार परिसर\r\n\r\nडे पिकनिक, विकेंड स्टे, कुटुंब सहल किंवा कॉर्पोरेट गेट-टुगेदर—प्रत्येकासाठी येथे एक वेगळा अनुभव आहे.\r\n\r\nया छोट्याशा व्हिडिओमधून विसावाच्या सुंदर वातावरणाची झलक पहा आणि आपल्या पुढील ग्रामीण सहलीचे नियोजन आजच करा.\r\n\r\nविसावा ॲग्रो टुरिझम – जिथे निसर्ग, परंपरा आणि आनंद एकत्र येतात.\";s:14:\"description_en\";s:1128:\"Welcome to VISAWA Agro Tourism – Babacha Mala\r\n\r\nEvery journey at VISAWA Agro Tourism begins with a warm village welcome. As you enter through the beautiful entrance surrounded by lush green trees and fresh countryside air, you\'ll instantly experience the peaceful atmosphere that makes VISAWA special.\r\n\r\nThe scenic entrance leads you into a spacious agro-tourism destination where nature, tradition, and comfort come together. Beautiful walkways, open landscapes, and a refreshing environment make it the perfect escape from busy city life.\r\n\r\nWhat makes VISAWA special?\r\n\r\nAuthentic Maharashtrian village cuisine\r\n\r\nTraditional rural games and activities\r\n\r\nFarm and nature experiences\r\n\r\nPeaceful open surroundings\r\n\r\nPerfect for families, couples, and groups\r\n\r\nWhether you\'re planning a day picnic, weekend stay, family outing, or corporate gathering, VISAWA offers unforgettable moments in the heart of nature.\r\n\r\nThis short video gives you a glimpse of our beautiful entrance and serene surroundings—an invitation to experience the charm of rural Maharashtra.\r\n\r\nVISAWA Agro Tourism – Where Nature Meets Tradition.\";s:14:\"featured_image\";N;s:10:\"blog_video\";s:76:\"http://127.0.0.1:8000/storage/uploads/blogs/videos/1788518127_Trdo75c4MN.mov\";s:15:\"video_thumbnail\";N;s:11:\"youtube_url\";N;s:10:\"youtube_id\";N;s:13:\"instagram_url\";N;s:9:\"has_media\";a:4:{s:5:\"image\";b:0;s:5:\"video\";b:1;s:7:\"youtube\";b:0;s:9:\"instagram\";b:0;}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-04T10:35:27+00:00\";}i:1;a:20:{s:2:\"id\";i:7;s:5:\"title\";s:65:\"Celebrating a Little Miracle | Baby Shower at VISAWA Agro Tourism\";s:8:\"title_mr\";s:157:\"चिमुकल्या पावलांच्या आगमनाचा आनंद | VISAWA मधील बेबी शॉवर सोहळा\";s:8:\"title_en\";s:65:\"Celebrating a Little Miracle | Baby Shower at VISAWA Agro Tourism\";s:4:\"slug\";s:69:\"celebrating-a-little-miracle-baby-shower-at-visawa-agro-tourism-av5Ao\";s:17:\"short_description\";s:109:\"A beautiful baby shower celebration filled with love, joy, and unforgettable memories at VISAWA Agro Tourism.\";s:20:\"short_description_mr\";s:328:\"चिमुकल्या पाहुण्याच्या स्वागतासाठी प्रेम, आनंद आणि आठवणींनी भरलेला बेबी शॉवर सोहळा VISAWA Agro Tourism मध्ये खास वातावरणात साजरा झाला.\";s:20:\"short_description_en\";s:109:\"A beautiful baby shower celebration filled with love, joy, and unforgettable memories at VISAWA Agro Tourism.\";s:11:\"description\";s:485:\"🌙👣 The tiny footsteps haven\'t arrived yet, but our hearts are already full of joy. 💞🍼\r\n\r\nA heartwarming Baby Shower celebration was beautifully hosted at VISAWA Agro Tourism – Babacha Mala, where nature, love, and family came together to create unforgettable memories.\r\n\r\nSurrounded by lush greenery and a peaceful countryside atmosphere, the celebration became even more special with heartfelt blessings, beautiful decorations, and joyful moments shared with loved ones.\";s:14:\"description_mr\";s:1996:\"🌙👣 चिमुकल्या पावलांचा आवाज अजून ऐकू आला नाही… पण त्याच्या आगमनाने मन मात्र आधीच भरून आलंय. 💞🍼\r\n\r\nVISAWA Agro Tourism – बाबांचा मळा येथे प्रेम, आपुलकी आणि आनंदाने भरलेला एक सुंदर Baby Shower सोहळा साजरा करण्यात आला. निसर्गाच्या सान्निध्यात, हिरवाईने वेढलेल्या शांत वातावरणात हा खास क्षण अधिकच संस्मरणीय बनला.\r\n\r\nहोणाऱ्या आईसाठी प्रेमाने सजवलेली जागा, कुटुंबियांचे आशीर्वाद आणि आनंदाने भरलेले वातावरण या प्रत्येक क्षणाला खास बनवत होते. अशा सुंदर आठवणी जपण्यासाठी VISAWA हे कुटुंबीय समारंभांसाठी एक उत्तम ठिकाण आहे.\r\n\r\nVISAWA मध्ये Baby Shower साठी खास सुविधा\r\n\r\nनिसर्गरम्य आणि शांत वातावरण\r\n\r\nसुंदर फोटो व रील्ससाठी आकर्षक लोकेशन्स\r\n\r\nकुटुंबासाठी प्रशस्त जागा\r\n\r\nपारंपरिक गावरान आदरातिथ्य\r\n\r\nखास समारंभांसाठी योग्य वातावरण\r\n\r\nचिमुकल्या पाहुण्याच्या स्वागताचा हा सुंदर प्रवास VISAWA मध्ये आणखी खास बनवा. ✨\";s:14:\"description_en\";s:485:\"🌙👣 The tiny footsteps haven\'t arrived yet, but our hearts are already full of joy. 💞🍼\r\n\r\nA heartwarming Baby Shower celebration was beautifully hosted at VISAWA Agro Tourism – Babacha Mala, where nature, love, and family came together to create unforgettable memories.\r\n\r\nSurrounded by lush greenery and a peaceful countryside atmosphere, the celebration became even more special with heartfelt blessings, beautiful decorations, and joyful moments shared with loved ones.\";s:14:\"featured_image\";N;s:10:\"blog_video\";s:76:\"http://127.0.0.1:8000/storage/uploads/blogs/videos/1788429533_D72Y8dwi7d.mp4\";s:15:\"video_thumbnail\";N;s:11:\"youtube_url\";N;s:10:\"youtube_id\";N;s:13:\"instagram_url\";s:69:\"https://www.instagram.com/reel/DZhny4xsSRv/?igsi=MW43cDMyd2FtdHpzbQ==\";s:9:\"has_media\";a:4:{s:5:\"image\";b:0;s:5:\"video\";b:1;s:7:\"youtube\";b:0;s:9:\"instagram\";b:1;}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-03T09:58:53+00:00\";}i:2;a:20:{s:2:\"id\";i:6;s:5:\"title\";s:76:\"Heartwarming Rakshabandhan & Get-Together Celebration at Visawa Agro Tourism\";s:8:\"title_mr\";s:208:\"विसावा ॲग्रो टुरिझम (बाबाचा मळा) येथे रक्षाबंधन व स्नेहसंमेलन उत्साहात संपन्न!\";s:8:\"title_en\";s:76:\"Heartwarming Rakshabandhan & Get-Together Celebration at Visawa Agro Tourism\";s:4:\"slug\";s:80:\"heartwarming-rakshabandhan-get-together-celebration-at-visawa-agro-tourism-6ZMkt\";s:17:\"short_description\";s:132:\"Highlights of Rakshabandhan & senior reunion at Visawa Agro Tourism. Get ready for the upcoming Ganeshotsav & Navratri celebrations!\";s:20:\"short_description_mr\";s:350:\"नात्यांचा गोडवा, संस्कृतीची जपणूक आणि आनंद! गुजराती विद्या मंदिराच्या कार्यक्रमाची खास झलक आणि आगामी गणेशोत्सव व नवरात्रीची तयारी.\";s:20:\"short_description_en\";s:132:\"Highlights of Rakshabandhan & senior reunion at Visawa Agro Tourism. Get ready for the upcoming Ganeshotsav & Navratri celebrations!\";s:11:\"description\";s:884:\"🌿 Visawa Agro Tourism – Babacha Mala ❤️🍀\r\n\r\nWe recently had the honor of hosting a wonderful Rakshabandhan & Reunion Get-Together for the \'Gujarati Vidya Mandir\' family at Visawa Agro Tourism.\r\n\r\nThe event was filled with joy, traditional values, and sweet memories. Guests thoroughly enjoyed the scenic green surroundings, fun tractor train rides, and delicious farm-style meals.\r\n\r\n🚩 Upcoming Celebrations: Ganeshotsav & Navratri! 🌺\r\nAfter the grand success of our Rakhi celebration, we are gearing up to celebrate the auspicious festivals of Ganeshotsav and Navratri! Experience the true festive spirit amidst nature with your family and loved ones.\r\n\r\n📍 Location: New Dhule–Solapur Highway, Near Karodi Toll Plaza, Behind Amruta Hotel, Babacha Mala, Karodi, Chhatrapati Sambhajinagar.\r\n\r\n📞 Contact us today to book your group events and weekend packages!\";s:14:\"description_mr\";s:2277:\"🌿 विसावा ॲग्रो टुरिझम – बाबाचा मळा ❤️🍀\r\n\r\nनुकतेच आमच्या विसावा ॲग्रो टुरिझम मध्ये \'गुजराती विद्या मंदिर\' परिवाराचे रक्षाबंधन आणि खास स्नेहसंमेलन (Get-together) अतिशय उत्साहात आणि आनंदी वातावरणात पार पडले.\r\n\r\nनात्यांचा गोडवा, संस्कृतीची जपणूक आणि ज्येष्ठांचा सहवास यामुळे हा दिवस सर्वांसाठीच अविस्मरणीय ठरला. उपस्थितांनी निसर्गाच्या कुशीत ट्रॅक्टर ट्रेनची सफर, गावरान वातावरणाचा आनंद आणि अस्सल भोजनाचा आस्वाद घेतला.\r\n\r\n🚩 लवकरच गणेशोत्सव आणि नवरात्री उत्सव! 🌺\r\nराखी सेलिब्रेशनच्या अभूतपूर्व प्रतिसादानंतर आता विसावा ॲग्रो टुरिझम सज्ज होत आहे आगामी गणेशोत्सव आणि नवरात्री उत्सवासाठी! पारंपरिक संस्कृती, निसर्गाची साथ आणि उत्सवाचा जल्लोष अनुभवण्यासाठी तुमच्या कुटुंबासोबत नक्की भेट द्या.\r\n\r\n📍 पत्ता: नवीन धुळे–सोलापूर हायवे, करोडी टोलनाक्याच्या बाजूला, अमृता हॉटेलच्या पाठीमागे, बाबाचा मळा, करोडी, छत्रपती संभाजीनगर.\r\n\r\n📞 आजच तुमचे बुकिंग करण्यासाठी आमच्याशी संपर्क साधा!\";s:14:\"description_en\";s:884:\"🌿 Visawa Agro Tourism – Babacha Mala ❤️🍀\r\n\r\nWe recently had the honor of hosting a wonderful Rakshabandhan & Reunion Get-Together for the \'Gujarati Vidya Mandir\' family at Visawa Agro Tourism.\r\n\r\nThe event was filled with joy, traditional values, and sweet memories. Guests thoroughly enjoyed the scenic green surroundings, fun tractor train rides, and delicious farm-style meals.\r\n\r\n🚩 Upcoming Celebrations: Ganeshotsav & Navratri! 🌺\r\nAfter the grand success of our Rakhi celebration, we are gearing up to celebrate the auspicious festivals of Ganeshotsav and Navratri! Experience the true festive spirit amidst nature with your family and loved ones.\r\n\r\n📍 Location: New Dhule–Solapur Highway, Near Karodi Toll Plaza, Behind Amruta Hotel, Babacha Mala, Karodi, Chhatrapati Sambhajinagar.\r\n\r\n📞 Contact us today to book your group events and weekend packages!\";s:14:\"featured_image\";N;s:10:\"blog_video\";s:76:\"http://127.0.0.1:8000/storage/uploads/blogs/videos/1788428795_MyG4ARDizK.mp4\";s:15:\"video_thumbnail\";N;s:11:\"youtube_url\";N;s:10:\"youtube_id\";N;s:13:\"instagram_url\";s:61:\"https://www.instagram.com/visawaagrotourism/reel/DcsPx-qTyxa/\";s:9:\"has_media\";a:4:{s:5:\"image\";b:0;s:5:\"video\";b:1;s:7:\"youtube\";b:0;s:9:\"instagram\";b:1;}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-03T09:46:35+00:00\";}i:3;a:20:{s:2:\"id\";i:5;s:5:\"title\";s:73:\"Visawa Agro Tourism – Experience Nature, Rural Culture & Fun Activities\";s:8:\"title_mr\";s:187:\"विसावा ॲग्रो टुरिझम – ग्रामीण संस्कृती आणि निसर्गरम्य पर्यटनाचा आनंद!\";s:8:\"title_en\";s:73:\"Visawa Agro Tourism – Experience Nature, Rural Culture & Fun Activities\";s:4:\"slug\";s:72:\"visawa-agro-tourism-experience-nature-rural-culture-fun-activities-f5Zae\";s:17:\"short_description\";s:128:\"Enjoy fun tractor rides, authentic Maharashtrian meals, traditional rural vibes, and group get-togethers at Visawa Agro Tourism.\";s:20:\"short_description_mr\";s:363:\"ट्रॅक्टर सफर, गावरान हुरडा पार्टी, अस्सल महाराष्ट्रीयन जेवण आणि निसर्गाचा निवांत अनुभव घेण्यासाठी विसावा ॲग्रो टुरिझमला नक्की भेट द्या.\";s:20:\"short_description_en\";s:128:\"Enjoy fun tractor rides, authentic Maharashtrian meals, traditional rural vibes, and group get-togethers at Visawa Agro Tourism.\";s:11:\"description\";s:556:\"Looking for an authentic rural and agro-tourism experience? Visawa Agro Tourism (Babacha Mala) welcomes you to enjoy nature and traditional Maharashtrian hospitality.\r\n\r\nKey Highlights:\r\n\r\nFun Activities: Enjoy unique tractor rides, explore green orchards, and experience traditional village vibes.\r\n\r\nAuthentic Food: Relish Maharashtrian breakfast, Hurda parties, and wholesome farm-style thalis.\r\n\r\nEvents & Gatherings: Ideal venue for family get-togethers, cultural meets, and group outings.\r\n\r\nPlan your visit today and experience the warmth of nature!\";s:14:\"description_mr\";s:1327:\"शहराच्या धावपळीपासून दूर जाऊन निसर्गाच्या सानिध्यात निवांत वेळ घालवायचा असेल, तर विसावा ॲग्रो टुरिझम (बाबाचा मळा) हे एक सर्वोत्तम ठिकाण आहे.\r\n\r\nआमची खास वैशिष्ट्ये:\r\n\r\nग्रामीण संस्कृतीची सफर: बैलगाडी, ट्रॅक्टर ट्रेनची सफर आणि अस्सल गावरान वातावरण.\r\n\r\nअस्सल महाराष्ट्रीयन जेवण: गरमागरम बाजरी-ज्वारीची भाकरी, शेवगा रस्सा, पिठलं आणि गावरान नाश्त्याचा आस्वाद.\r\n\r\nकौटुंबिक व ग्रुप कार्यक्रम: स्नेहमेलन, कौटुंबिक कार्यक्रम आणि गेट-टुगेदरसाठी प्रशस्त हॉल व परिसर.\r\n\r\nआजच तुमचे बुकिंग करण्यासाठी आमच्याशी संपर्क साधा!\";s:14:\"description_en\";s:556:\"Looking for an authentic rural and agro-tourism experience? Visawa Agro Tourism (Babacha Mala) welcomes you to enjoy nature and traditional Maharashtrian hospitality.\r\n\r\nKey Highlights:\r\n\r\nFun Activities: Enjoy unique tractor rides, explore green orchards, and experience traditional village vibes.\r\n\r\nAuthentic Food: Relish Maharashtrian breakfast, Hurda parties, and wholesome farm-style thalis.\r\n\r\nEvents & Gatherings: Ideal venue for family get-togethers, cultural meets, and group outings.\r\n\r\nPlan your visit today and experience the warmth of nature!\";s:14:\"featured_image\";N;s:10:\"blog_video\";s:76:\"http://127.0.0.1:8000/storage/uploads/blogs/videos/1788424031_Vw6wCxibGy.mp4\";s:15:\"video_thumbnail\";N;s:11:\"youtube_url\";N;s:10:\"youtube_id\";N;s:13:\"instagram_url\";s:65:\"https://www.instagram.com/reel/DctDNIfxMD1/?igsi=dTgyenIxNGI4Nmp0\";s:9:\"has_media\";a:4:{s:5:\"image\";b:0;s:5:\"video\";b:1;s:7:\"youtube\";b:0;s:9:\"instagram\";b:1;}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-03T08:27:11+00:00\";}}', 1788782088),
('visava-cache-api_blogs_mr', 'a:4:{i:0;a:20:{s:2:\"id\";i:8;s:5:\"title\";s:128:\"विसावा ॲग्रो टुरिझममध्ये आपले मनःपूर्वक स्वागत\";s:8:\"title_mr\";s:128:\"विसावा ॲग्रो टुरिझममध्ये आपले मनःपूर्वक स्वागत\";s:8:\"title_en\";s:57:\"Welcome to VISAWA Agro Tourism – Your Gateway to Nature\";s:4:\"slug\";s:59:\"welcome-to-visawa-agro-tourism-your-gateway-to-nature-gWA2j\";s:17:\"short_description\";s:419:\"हिरव्यागार झाडांनी वेढलेला सुंदर प्रवेशद्वार, मोकळे निसर्गरम्य वातावरण आणि अस्सल ग्रामीण सौंदर्य अनुभवण्यासाठी विसावा अॅग्रो टुरिझममध्ये आपले स्वागत आहे.\";s:20:\"short_description_mr\";s:419:\"हिरव्यागार झाडांनी वेढलेला सुंदर प्रवेशद्वार, मोकळे निसर्गरम्य वातावरण आणि अस्सल ग्रामीण सौंदर्य अनुभवण्यासाठी विसावा अॅग्रो टुरिझममध्ये आपले स्वागत आहे.\";s:20:\"short_description_en\";s:201:\"Experience the peaceful entrance of VISAWA Agro Tourism surrounded by lush greenery, open landscapes, and authentic village charm. Step into a relaxing getaway where nature and tradition come together.\";s:11:\"description\";s:2376:\"विसावा ॲग्रो टुरिझम – बाबांचा मळा येथे प्रत्येक प्रवासाची सुरुवात होते एका सुंदर ग्रामीण स्वागताने.\r\n\r\nहिरव्यागार झाडांनी वेढलेला प्रवेशमार्ग, ताजी हवा आणि शांत वातावरण पाहताच मनाला एक वेगळाच विसावा मिळतो. हा निसर्गरम्य परिसर शहराच्या धकाधकीपासून दूर शांत आणि आनंददायी अनुभव देतो.\r\n\r\nप्रवेशद्वारातून आत आल्यानंतर विस्तीर्ण परिसर, सुंदर पायवाटा आणि ग्रामीण संस्कृतीची झलक प्रत्येक पाहुण्याला निसर्गाच्या अधिक जवळ घेऊन जाते.\r\n\r\nविसावा ॲग्रो टुरिझममध्ये तुम्हाला मिळतो—\r\n\r\nअस्सल महाराष्ट्रीयन गावरान जेवण\r\n\r\nपारंपरिक ग्रामीण खेळ\r\n\r\nशेतीचा प्रत्यक्ष अनुभव\r\n\r\nकुटुंब आणि मित्रांसोबत निवांत क्षण\r\n\r\nशांत, स्वच्छ आणि हिरवागार परिसर\r\n\r\nडे पिकनिक, विकेंड स्टे, कुटुंब सहल किंवा कॉर्पोरेट गेट-टुगेदर—प्रत्येकासाठी येथे एक वेगळा अनुभव आहे.\r\n\r\nया छोट्याशा व्हिडिओमधून विसावाच्या सुंदर वातावरणाची झलक पहा आणि आपल्या पुढील ग्रामीण सहलीचे नियोजन आजच करा.\r\n\r\nविसावा ॲग्रो टुरिझम – जिथे निसर्ग, परंपरा आणि आनंद एकत्र येतात.\";s:14:\"description_mr\";s:2376:\"विसावा ॲग्रो टुरिझम – बाबांचा मळा येथे प्रत्येक प्रवासाची सुरुवात होते एका सुंदर ग्रामीण स्वागताने.\r\n\r\nहिरव्यागार झाडांनी वेढलेला प्रवेशमार्ग, ताजी हवा आणि शांत वातावरण पाहताच मनाला एक वेगळाच विसावा मिळतो. हा निसर्गरम्य परिसर शहराच्या धकाधकीपासून दूर शांत आणि आनंददायी अनुभव देतो.\r\n\r\nप्रवेशद्वारातून आत आल्यानंतर विस्तीर्ण परिसर, सुंदर पायवाटा आणि ग्रामीण संस्कृतीची झलक प्रत्येक पाहुण्याला निसर्गाच्या अधिक जवळ घेऊन जाते.\r\n\r\nविसावा ॲग्रो टुरिझममध्ये तुम्हाला मिळतो—\r\n\r\nअस्सल महाराष्ट्रीयन गावरान जेवण\r\n\r\nपारंपरिक ग्रामीण खेळ\r\n\r\nशेतीचा प्रत्यक्ष अनुभव\r\n\r\nकुटुंब आणि मित्रांसोबत निवांत क्षण\r\n\r\nशांत, स्वच्छ आणि हिरवागार परिसर\r\n\r\nडे पिकनिक, विकेंड स्टे, कुटुंब सहल किंवा कॉर्पोरेट गेट-टुगेदर—प्रत्येकासाठी येथे एक वेगळा अनुभव आहे.\r\n\r\nया छोट्याशा व्हिडिओमधून विसावाच्या सुंदर वातावरणाची झलक पहा आणि आपल्या पुढील ग्रामीण सहलीचे नियोजन आजच करा.\r\n\r\nविसावा ॲग्रो टुरिझम – जिथे निसर्ग, परंपरा आणि आनंद एकत्र येतात.\";s:14:\"description_en\";s:1128:\"Welcome to VISAWA Agro Tourism – Babacha Mala\r\n\r\nEvery journey at VISAWA Agro Tourism begins with a warm village welcome. As you enter through the beautiful entrance surrounded by lush green trees and fresh countryside air, you\'ll instantly experience the peaceful atmosphere that makes VISAWA special.\r\n\r\nThe scenic entrance leads you into a spacious agro-tourism destination where nature, tradition, and comfort come together. Beautiful walkways, open landscapes, and a refreshing environment make it the perfect escape from busy city life.\r\n\r\nWhat makes VISAWA special?\r\n\r\nAuthentic Maharashtrian village cuisine\r\n\r\nTraditional rural games and activities\r\n\r\nFarm and nature experiences\r\n\r\nPeaceful open surroundings\r\n\r\nPerfect for families, couples, and groups\r\n\r\nWhether you\'re planning a day picnic, weekend stay, family outing, or corporate gathering, VISAWA offers unforgettable moments in the heart of nature.\r\n\r\nThis short video gives you a glimpse of our beautiful entrance and serene surroundings—an invitation to experience the charm of rural Maharashtra.\r\n\r\nVISAWA Agro Tourism – Where Nature Meets Tradition.\";s:14:\"featured_image\";N;s:10:\"blog_video\";s:76:\"http://127.0.0.1:8000/storage/uploads/blogs/videos/1788518127_Trdo75c4MN.mov\";s:15:\"video_thumbnail\";N;s:11:\"youtube_url\";N;s:10:\"youtube_id\";N;s:13:\"instagram_url\";N;s:9:\"has_media\";a:4:{s:5:\"image\";b:0;s:5:\"video\";b:1;s:7:\"youtube\";b:0;s:9:\"instagram\";b:0;}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-04T10:35:27+00:00\";}i:1;a:20:{s:2:\"id\";i:7;s:5:\"title\";s:157:\"चिमुकल्या पावलांच्या आगमनाचा आनंद | VISAWA मधील बेबी शॉवर सोहळा\";s:8:\"title_mr\";s:157:\"चिमुकल्या पावलांच्या आगमनाचा आनंद | VISAWA मधील बेबी शॉवर सोहळा\";s:8:\"title_en\";s:65:\"Celebrating a Little Miracle | Baby Shower at VISAWA Agro Tourism\";s:4:\"slug\";s:69:\"celebrating-a-little-miracle-baby-shower-at-visawa-agro-tourism-av5Ao\";s:17:\"short_description\";s:328:\"चिमुकल्या पाहुण्याच्या स्वागतासाठी प्रेम, आनंद आणि आठवणींनी भरलेला बेबी शॉवर सोहळा VISAWA Agro Tourism मध्ये खास वातावरणात साजरा झाला.\";s:20:\"short_description_mr\";s:328:\"चिमुकल्या पाहुण्याच्या स्वागतासाठी प्रेम, आनंद आणि आठवणींनी भरलेला बेबी शॉवर सोहळा VISAWA Agro Tourism मध्ये खास वातावरणात साजरा झाला.\";s:20:\"short_description_en\";s:109:\"A beautiful baby shower celebration filled with love, joy, and unforgettable memories at VISAWA Agro Tourism.\";s:11:\"description\";s:1996:\"🌙👣 चिमुकल्या पावलांचा आवाज अजून ऐकू आला नाही… पण त्याच्या आगमनाने मन मात्र आधीच भरून आलंय. 💞🍼\r\n\r\nVISAWA Agro Tourism – बाबांचा मळा येथे प्रेम, आपुलकी आणि आनंदाने भरलेला एक सुंदर Baby Shower सोहळा साजरा करण्यात आला. निसर्गाच्या सान्निध्यात, हिरवाईने वेढलेल्या शांत वातावरणात हा खास क्षण अधिकच संस्मरणीय बनला.\r\n\r\nहोणाऱ्या आईसाठी प्रेमाने सजवलेली जागा, कुटुंबियांचे आशीर्वाद आणि आनंदाने भरलेले वातावरण या प्रत्येक क्षणाला खास बनवत होते. अशा सुंदर आठवणी जपण्यासाठी VISAWA हे कुटुंबीय समारंभांसाठी एक उत्तम ठिकाण आहे.\r\n\r\nVISAWA मध्ये Baby Shower साठी खास सुविधा\r\n\r\nनिसर्गरम्य आणि शांत वातावरण\r\n\r\nसुंदर फोटो व रील्ससाठी आकर्षक लोकेशन्स\r\n\r\nकुटुंबासाठी प्रशस्त जागा\r\n\r\nपारंपरिक गावरान आदरातिथ्य\r\n\r\nखास समारंभांसाठी योग्य वातावरण\r\n\r\nचिमुकल्या पाहुण्याच्या स्वागताचा हा सुंदर प्रवास VISAWA मध्ये आणखी खास बनवा. ✨\";s:14:\"description_mr\";s:1996:\"🌙👣 चिमुकल्या पावलांचा आवाज अजून ऐकू आला नाही… पण त्याच्या आगमनाने मन मात्र आधीच भरून आलंय. 💞🍼\r\n\r\nVISAWA Agro Tourism – बाबांचा मळा येथे प्रेम, आपुलकी आणि आनंदाने भरलेला एक सुंदर Baby Shower सोहळा साजरा करण्यात आला. निसर्गाच्या सान्निध्यात, हिरवाईने वेढलेल्या शांत वातावरणात हा खास क्षण अधिकच संस्मरणीय बनला.\r\n\r\nहोणाऱ्या आईसाठी प्रेमाने सजवलेली जागा, कुटुंबियांचे आशीर्वाद आणि आनंदाने भरलेले वातावरण या प्रत्येक क्षणाला खास बनवत होते. अशा सुंदर आठवणी जपण्यासाठी VISAWA हे कुटुंबीय समारंभांसाठी एक उत्तम ठिकाण आहे.\r\n\r\nVISAWA मध्ये Baby Shower साठी खास सुविधा\r\n\r\nनिसर्गरम्य आणि शांत वातावरण\r\n\r\nसुंदर फोटो व रील्ससाठी आकर्षक लोकेशन्स\r\n\r\nकुटुंबासाठी प्रशस्त जागा\r\n\r\nपारंपरिक गावरान आदरातिथ्य\r\n\r\nखास समारंभांसाठी योग्य वातावरण\r\n\r\nचिमुकल्या पाहुण्याच्या स्वागताचा हा सुंदर प्रवास VISAWA मध्ये आणखी खास बनवा. ✨\";s:14:\"description_en\";s:485:\"🌙👣 The tiny footsteps haven\'t arrived yet, but our hearts are already full of joy. 💞🍼\r\n\r\nA heartwarming Baby Shower celebration was beautifully hosted at VISAWA Agro Tourism – Babacha Mala, where nature, love, and family came together to create unforgettable memories.\r\n\r\nSurrounded by lush greenery and a peaceful countryside atmosphere, the celebration became even more special with heartfelt blessings, beautiful decorations, and joyful moments shared with loved ones.\";s:14:\"featured_image\";N;s:10:\"blog_video\";s:76:\"http://127.0.0.1:8000/storage/uploads/blogs/videos/1788429533_D72Y8dwi7d.mp4\";s:15:\"video_thumbnail\";N;s:11:\"youtube_url\";N;s:10:\"youtube_id\";N;s:13:\"instagram_url\";s:69:\"https://www.instagram.com/reel/DZhny4xsSRv/?igsi=MW43cDMyd2FtdHpzbQ==\";s:9:\"has_media\";a:4:{s:5:\"image\";b:0;s:5:\"video\";b:1;s:7:\"youtube\";b:0;s:9:\"instagram\";b:1;}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-03T09:58:53+00:00\";}i:2;a:20:{s:2:\"id\";i:6;s:5:\"title\";s:208:\"विसावा ॲग्रो टुरिझम (बाबाचा मळा) येथे रक्षाबंधन व स्नेहसंमेलन उत्साहात संपन्न!\";s:8:\"title_mr\";s:208:\"विसावा ॲग्रो टुरिझम (बाबाचा मळा) येथे रक्षाबंधन व स्नेहसंमेलन उत्साहात संपन्न!\";s:8:\"title_en\";s:76:\"Heartwarming Rakshabandhan & Get-Together Celebration at Visawa Agro Tourism\";s:4:\"slug\";s:80:\"heartwarming-rakshabandhan-get-together-celebration-at-visawa-agro-tourism-6ZMkt\";s:17:\"short_description\";s:350:\"नात्यांचा गोडवा, संस्कृतीची जपणूक आणि आनंद! गुजराती विद्या मंदिराच्या कार्यक्रमाची खास झलक आणि आगामी गणेशोत्सव व नवरात्रीची तयारी.\";s:20:\"short_description_mr\";s:350:\"नात्यांचा गोडवा, संस्कृतीची जपणूक आणि आनंद! गुजराती विद्या मंदिराच्या कार्यक्रमाची खास झलक आणि आगामी गणेशोत्सव व नवरात्रीची तयारी.\";s:20:\"short_description_en\";s:132:\"Highlights of Rakshabandhan & senior reunion at Visawa Agro Tourism. Get ready for the upcoming Ganeshotsav & Navratri celebrations!\";s:11:\"description\";s:2277:\"🌿 विसावा ॲग्रो टुरिझम – बाबाचा मळा ❤️🍀\r\n\r\nनुकतेच आमच्या विसावा ॲग्रो टुरिझम मध्ये \'गुजराती विद्या मंदिर\' परिवाराचे रक्षाबंधन आणि खास स्नेहसंमेलन (Get-together) अतिशय उत्साहात आणि आनंदी वातावरणात पार पडले.\r\n\r\nनात्यांचा गोडवा, संस्कृतीची जपणूक आणि ज्येष्ठांचा सहवास यामुळे हा दिवस सर्वांसाठीच अविस्मरणीय ठरला. उपस्थितांनी निसर्गाच्या कुशीत ट्रॅक्टर ट्रेनची सफर, गावरान वातावरणाचा आनंद आणि अस्सल भोजनाचा आस्वाद घेतला.\r\n\r\n🚩 लवकरच गणेशोत्सव आणि नवरात्री उत्सव! 🌺\r\nराखी सेलिब्रेशनच्या अभूतपूर्व प्रतिसादानंतर आता विसावा ॲग्रो टुरिझम सज्ज होत आहे आगामी गणेशोत्सव आणि नवरात्री उत्सवासाठी! पारंपरिक संस्कृती, निसर्गाची साथ आणि उत्सवाचा जल्लोष अनुभवण्यासाठी तुमच्या कुटुंबासोबत नक्की भेट द्या.\r\n\r\n📍 पत्ता: नवीन धुळे–सोलापूर हायवे, करोडी टोलनाक्याच्या बाजूला, अमृता हॉटेलच्या पाठीमागे, बाबाचा मळा, करोडी, छत्रपती संभाजीनगर.\r\n\r\n📞 आजच तुमचे बुकिंग करण्यासाठी आमच्याशी संपर्क साधा!\";s:14:\"description_mr\";s:2277:\"🌿 विसावा ॲग्रो टुरिझम – बाबाचा मळा ❤️🍀\r\n\r\nनुकतेच आमच्या विसावा ॲग्रो टुरिझम मध्ये \'गुजराती विद्या मंदिर\' परिवाराचे रक्षाबंधन आणि खास स्नेहसंमेलन (Get-together) अतिशय उत्साहात आणि आनंदी वातावरणात पार पडले.\r\n\r\nनात्यांचा गोडवा, संस्कृतीची जपणूक आणि ज्येष्ठांचा सहवास यामुळे हा दिवस सर्वांसाठीच अविस्मरणीय ठरला. उपस्थितांनी निसर्गाच्या कुशीत ट्रॅक्टर ट्रेनची सफर, गावरान वातावरणाचा आनंद आणि अस्सल भोजनाचा आस्वाद घेतला.\r\n\r\n🚩 लवकरच गणेशोत्सव आणि नवरात्री उत्सव! 🌺\r\nराखी सेलिब्रेशनच्या अभूतपूर्व प्रतिसादानंतर आता विसावा ॲग्रो टुरिझम सज्ज होत आहे आगामी गणेशोत्सव आणि नवरात्री उत्सवासाठी! पारंपरिक संस्कृती, निसर्गाची साथ आणि उत्सवाचा जल्लोष अनुभवण्यासाठी तुमच्या कुटुंबासोबत नक्की भेट द्या.\r\n\r\n📍 पत्ता: नवीन धुळे–सोलापूर हायवे, करोडी टोलनाक्याच्या बाजूला, अमृता हॉटेलच्या पाठीमागे, बाबाचा मळा, करोडी, छत्रपती संभाजीनगर.\r\n\r\n📞 आजच तुमचे बुकिंग करण्यासाठी आमच्याशी संपर्क साधा!\";s:14:\"description_en\";s:884:\"🌿 Visawa Agro Tourism – Babacha Mala ❤️🍀\r\n\r\nWe recently had the honor of hosting a wonderful Rakshabandhan & Reunion Get-Together for the \'Gujarati Vidya Mandir\' family at Visawa Agro Tourism.\r\n\r\nThe event was filled with joy, traditional values, and sweet memories. Guests thoroughly enjoyed the scenic green surroundings, fun tractor train rides, and delicious farm-style meals.\r\n\r\n🚩 Upcoming Celebrations: Ganeshotsav & Navratri! 🌺\r\nAfter the grand success of our Rakhi celebration, we are gearing up to celebrate the auspicious festivals of Ganeshotsav and Navratri! Experience the true festive spirit amidst nature with your family and loved ones.\r\n\r\n📍 Location: New Dhule–Solapur Highway, Near Karodi Toll Plaza, Behind Amruta Hotel, Babacha Mala, Karodi, Chhatrapati Sambhajinagar.\r\n\r\n📞 Contact us today to book your group events and weekend packages!\";s:14:\"featured_image\";N;s:10:\"blog_video\";s:76:\"http://127.0.0.1:8000/storage/uploads/blogs/videos/1788428795_MyG4ARDizK.mp4\";s:15:\"video_thumbnail\";N;s:11:\"youtube_url\";N;s:10:\"youtube_id\";N;s:13:\"instagram_url\";s:61:\"https://www.instagram.com/visawaagrotourism/reel/DcsPx-qTyxa/\";s:9:\"has_media\";a:4:{s:5:\"image\";b:0;s:5:\"video\";b:1;s:7:\"youtube\";b:0;s:9:\"instagram\";b:1;}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-03T09:46:35+00:00\";}i:3;a:20:{s:2:\"id\";i:5;s:5:\"title\";s:187:\"विसावा ॲग्रो टुरिझम – ग्रामीण संस्कृती आणि निसर्गरम्य पर्यटनाचा आनंद!\";s:8:\"title_mr\";s:187:\"विसावा ॲग्रो टुरिझम – ग्रामीण संस्कृती आणि निसर्गरम्य पर्यटनाचा आनंद!\";s:8:\"title_en\";s:73:\"Visawa Agro Tourism – Experience Nature, Rural Culture & Fun Activities\";s:4:\"slug\";s:72:\"visawa-agro-tourism-experience-nature-rural-culture-fun-activities-f5Zae\";s:17:\"short_description\";s:363:\"ट्रॅक्टर सफर, गावरान हुरडा पार्टी, अस्सल महाराष्ट्रीयन जेवण आणि निसर्गाचा निवांत अनुभव घेण्यासाठी विसावा ॲग्रो टुरिझमला नक्की भेट द्या.\";s:20:\"short_description_mr\";s:363:\"ट्रॅक्टर सफर, गावरान हुरडा पार्टी, अस्सल महाराष्ट्रीयन जेवण आणि निसर्गाचा निवांत अनुभव घेण्यासाठी विसावा ॲग्रो टुरिझमला नक्की भेट द्या.\";s:20:\"short_description_en\";s:128:\"Enjoy fun tractor rides, authentic Maharashtrian meals, traditional rural vibes, and group get-togethers at Visawa Agro Tourism.\";s:11:\"description\";s:1327:\"शहराच्या धावपळीपासून दूर जाऊन निसर्गाच्या सानिध्यात निवांत वेळ घालवायचा असेल, तर विसावा ॲग्रो टुरिझम (बाबाचा मळा) हे एक सर्वोत्तम ठिकाण आहे.\r\n\r\nआमची खास वैशिष्ट्ये:\r\n\r\nग्रामीण संस्कृतीची सफर: बैलगाडी, ट्रॅक्टर ट्रेनची सफर आणि अस्सल गावरान वातावरण.\r\n\r\nअस्सल महाराष्ट्रीयन जेवण: गरमागरम बाजरी-ज्वारीची भाकरी, शेवगा रस्सा, पिठलं आणि गावरान नाश्त्याचा आस्वाद.\r\n\r\nकौटुंबिक व ग्रुप कार्यक्रम: स्नेहमेलन, कौटुंबिक कार्यक्रम आणि गेट-टुगेदरसाठी प्रशस्त हॉल व परिसर.\r\n\r\nआजच तुमचे बुकिंग करण्यासाठी आमच्याशी संपर्क साधा!\";s:14:\"description_mr\";s:1327:\"शहराच्या धावपळीपासून दूर जाऊन निसर्गाच्या सानिध्यात निवांत वेळ घालवायचा असेल, तर विसावा ॲग्रो टुरिझम (बाबाचा मळा) हे एक सर्वोत्तम ठिकाण आहे.\r\n\r\nआमची खास वैशिष्ट्ये:\r\n\r\nग्रामीण संस्कृतीची सफर: बैलगाडी, ट्रॅक्टर ट्रेनची सफर आणि अस्सल गावरान वातावरण.\r\n\r\nअस्सल महाराष्ट्रीयन जेवण: गरमागरम बाजरी-ज्वारीची भाकरी, शेवगा रस्सा, पिठलं आणि गावरान नाश्त्याचा आस्वाद.\r\n\r\nकौटुंबिक व ग्रुप कार्यक्रम: स्नेहमेलन, कौटुंबिक कार्यक्रम आणि गेट-टुगेदरसाठी प्रशस्त हॉल व परिसर.\r\n\r\nआजच तुमचे बुकिंग करण्यासाठी आमच्याशी संपर्क साधा!\";s:14:\"description_en\";s:556:\"Looking for an authentic rural and agro-tourism experience? Visawa Agro Tourism (Babacha Mala) welcomes you to enjoy nature and traditional Maharashtrian hospitality.\r\n\r\nKey Highlights:\r\n\r\nFun Activities: Enjoy unique tractor rides, explore green orchards, and experience traditional village vibes.\r\n\r\nAuthentic Food: Relish Maharashtrian breakfast, Hurda parties, and wholesome farm-style thalis.\r\n\r\nEvents & Gatherings: Ideal venue for family get-togethers, cultural meets, and group outings.\r\n\r\nPlan your visit today and experience the warmth of nature!\";s:14:\"featured_image\";N;s:10:\"blog_video\";s:76:\"http://127.0.0.1:8000/storage/uploads/blogs/videos/1788424031_Vw6wCxibGy.mp4\";s:15:\"video_thumbnail\";N;s:11:\"youtube_url\";N;s:10:\"youtube_id\";N;s:13:\"instagram_url\";s:65:\"https://www.instagram.com/reel/DctDNIfxMD1/?igsi=dTgyenIxNGI4Nmp0\";s:9:\"has_media\";a:4:{s:5:\"image\";b:0;s:5:\"video\";b:1;s:7:\"youtube\";b:0;s:9:\"instagram\";b:1;}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-03T08:27:11+00:00\";}}', 1788782275),
('visava-cache-api_dining_en_all', 'a:6:{i:0;a:19:{s:2:\"id\";i:1;s:5:\"title\";s:39:\"Authentic Gavran Thali & Village Feasts\";s:8:\"title_mr\";s:92:\"अस्सल गावरान जेवण व अमर्यादित थाळी\";s:8:\"title_en\";s:39:\"Authentic Gavran Thali & Village Feasts\";s:5:\"badge\";s:12:\"Gavran Lunch\";s:8:\"badge_mr\";s:28:\"अस्सल जेवण\";s:8:\"badge_en\";s:12:\"Gavran Lunch\";s:10:\"badge_icon\";s:4:\"🍛\";s:8:\"category\";s:14:\"Lunch & Dinner\";s:11:\"category_mr\";s:61:\"दुपारचे / रात्रीचे जेवण\";s:11:\"category_en\";s:14:\"Lunch & Dinner\";s:17:\"short_description\";s:152:\"Enjoy a traditional Gavran Thali with hot Jowar/Bajra Bhakri, authentic Pithla, Thecha, roasted Baingan Bharta, fresh farm greens, and homemade flavors.\";s:20:\"short_description_mr\";s:339:\"ज्वारी-बाजरीची गरमागरम चुलीवरची भाकरी, अस्सल गावरान पिठलं, खर्डा/ठेचा, वांग्याचे भरीत, शेतातील ताजी भाजी, ताक आणि चुलीवरचा सुगंध.\";s:20:\"short_description_en\";s:152:\"Enjoy a traditional Gavran Thali with hot Jowar/Bajra Bhakri, authentic Pithla, Thecha, roasted Baingan Bharta, fresh farm greens, and homemade flavors.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/dining/1788245707_7M5w1jvB2s.jpg\";s:12:\"dietary_type\";s:8:\"pure_veg\";s:10:\"sort_order\";i:1;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-01T06:30:21+00:00\";}i:1;a:19:{s:2:\"id\";i:2;s:5:\"title\";s:29:\"Traditional Village Breakfast\";s:8:\"title_mr\";s:62:\"पारंपरिक गावरान नाश्ता\";s:8:\"title_en\";s:29:\"Traditional Village Breakfast\";s:5:\"badge\";s:17:\"Village Breakfast\";s:8:\"badge_mr\";s:37:\"सकाळचा नाश्ता\";s:8:\"badge_en\";s:17:\"Village Breakfast\";s:10:\"badge_icon\";s:4:\"🌅\";s:8:\"category\";s:9:\"Breakfast\";s:11:\"category_mr\";s:37:\"सकाळचा नाश्ता\";s:11:\"category_en\";s:9:\"Breakfast\";s:17:\"short_description\";s:140:\"Start your morning with freshly prepared Thalipeeth with white butter, steaming Kande Pohe, Upma, and wood-fired organic Jaggery/Ginger Tea.\";s:20:\"short_description_mr\";s:273:\"सकाळच्या शुद्ध हवेत गरमागरम थालिपीठ-लोणी, कांदे पोहे, उपमा आणि चुलीवरचा अस्सल गुळाचा किंवा आल्याचा चहा.\";s:20:\"short_description_en\";s:140:\"Start your morning with freshly prepared Thalipeeth with white butter, steaming Kande Pohe, Upma, and wood-fired organic Jaggery/Ginger Tea.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/dining/1788330609_GVOylBYUwi.jpg\";s:12:\"dietary_type\";s:8:\"pure_veg\";s:10:\"sort_order\";i:2;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-01T06:30:21+00:00\";}i:2;a:19:{s:2:\"id\";i:3;s:5:\"title\";s:34:\"Wood-Fired Maharashtrian Misal Pav\";s:8:\"title_mr\";s:56:\"चुलीवरची झणझणीत मिसळ\";s:8:\"title_en\";s:34:\"Wood-Fired Maharashtrian Misal Pav\";s:5:\"badge\";s:18:\"Wood-Fired Special\";s:8:\"badge_mr\";s:28:\"खास आकर्षण\";s:8:\"badge_en\";s:18:\"Wood-Fired Special\";s:10:\"badge_icon\";s:4:\"🔥\";s:8:\"category\";s:8:\"Specials\";s:11:\"category_mr\";s:28:\"खास आकर्षण\";s:11:\"category_en\";s:8:\"Specials\";s:17:\"short_description\";s:135:\"Slow-simmered on traditional clay stoves with handmade village spices, sprouted moth beans, crunchy farsan, onion, lemon, and soft pav.\";s:20:\"short_description_mr\";s:278:\"खास गावरान मसाल्यांमध्ये चुलीवर शिजवलेला कट, मटकी उसळ, कुरकुरीत फरसाण, कांदा-लिंबू आणि मऊ पावासह अस्सल चव.\";s:20:\"short_description_en\";s:135:\"Slow-simmered on traditional clay stoves with handmade village spices, sprouted moth beans, crunchy farsan, onion, lemon, and soft pav.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/dining/1788245769_mye5oSqRrM.jpg\";s:12:\"dietary_type\";s:8:\"pure_veg\";s:10:\"sort_order\";i:3;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-01T06:30:21+00:00\";}i:3;a:19:{s:2:\"id\";i:4;s:5:\"title\";s:29:\"High Tea & Countryside Snacks\";s:8:\"title_mr\";s:64:\"संध्याकाळचा हाय-टी व भजी\";s:8:\"title_en\";s:29:\"High Tea & Countryside Snacks\";s:5:\"badge\";s:11:\"Evening Tea\";s:8:\"badge_mr\";s:43:\"संध्याकाळचा चहा\";s:8:\