('visava-cache-api_dining_mr_all', 'a:6:{i:0;a:19:{s:2:\"id\";i:1;s:5:\"title\";s:92:\"अस्सल गावरान जेवण व अमर्यादित थाळी\";s:8:\"title_mr\";s:92:\"अस्सल गावरान जेवण व अमर्यादित थाळी\";s:8:\"title_en\";s:39:\"Authentic Gavran Thali & Village Feasts\";s:5:\"badge\";s:28:\"अस्सल जेवण\";s:8:\"badge_mr\";s:28:\"अस्सल जेवण\";s:8:\"badge_en\";s:12:\"Gavran Lunch\";s:10:\"badge_icon\";s:4:\"🍛\";s:8:\"category\";s:61:\"दुपारचे / रात्रीचे जेवण\";s:11:\"category_mr\";s:61:\"दुपारचे / रात्रीचे जेवण\";s:11:\"category_en\";s:14:\"Lunch & Dinner\";s:17:\"short_description\";s:339:\"ज्वारी-बाजरीची गरमागरम चुलीवरची भाकरी, अस्सल गावरान पिठलं, खर्डा/ठेचा, वांग्याचे भरीत, शेतातील ताजी भाजी, ताक आणि चुलीवरचा सुगंध.\";s:20:\"short_description_mr\";s:339:\"ज्वारी-बाजरीची गरमागरम चुलीवरची भाकरी, अस्सल गावरान पिठलं, खर्डा/ठेचा, वांग्याचे भरीत, शेतातील ताजी भाजी, ताक आणि चुलीवरचा सुगंध.\";s:20:\"short_description_en\";s:152:\"Enjoy a traditional Gavran Thali with hot Jowar/Bajra Bhakri, authentic Pithla, Thecha, roasted Baingan Bharta, fresh farm greens, and homemade flavors.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/dining/1788245707_7M5w1jvB2s.jpg\";s:12:\"dietary_type\";s:8:\"pure_veg\";s:10:\"sort_order\";i:1;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-01T06:30:21+00:00\";}i:1;a:19:{s:2:\"id\";i:2;s:5:\"title\";s:62:\"पारंपरिक गावरान नाश्ता\";s:8:\"title_mr\";s:62:\"पारंपरिक गावरान नाश्ता\";s:8:\"title_en\";s:29:\"Traditional Village Breakfast\";s:5:\"badge\";s:37:\"सकाळचा नाश्ता\";s:8:\"badge_mr\";s:37:\"सकाळचा नाश्ता\";s:8:\"badge_en\";s:17:\"Village Breakfast\";s:10:\"badge_icon\";s:4:\"🌅\";s:8:\"category\";s:37:\"सकाळचा नाश्ता\";s:11:\"category_mr\";s:37:\"सकाळचा नाश्ता\";s:11:\"category_en\";s:9:\"Breakfast\";s:17:\"short_description\";s:273:\"सकाळच्या शुद्ध हवेत गरमागरम थालिपीठ-लोणी, कांदे पोहे, उपमा आणि चुलीवरचा अस्सल गुळाचा किंवा आल्याचा चहा.\";s:20:\"short_description_mr\";s:273:\"सकाळच्या शुद्ध हवेत गरमागरम थालिपीठ-लोणी, कांदे पोहे, उपमा आणि चुलीवरचा अस्सल गुळाचा किंवा आल्याचा चहा.\";s:20:\"short_description_en\";s:140:\"Start your morning with freshly prepared Thalipeeth with white butter, steaming Kande Pohe, Upma, and wood-fired organic Jaggery/Ginger Tea.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/dining/1788330609_GVOylBYUwi.jpg\";s:12:\"dietary_type\";s:8:\"pure_veg\";s:10:\"sort_order\";i:2;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-01T06:30:21+00:00\";}i:2;a:19:{s:2:\"id\";i:3;s:5:\"title\";s:56:\"चुलीवरची झणझणीत मिसळ\";s:8:\"title_mr\";s:56:\"चुलीवरची झणझणीत मिसळ\";s:8:\"title_en\";s:34:\"Wood-Fired Maharashtrian Misal Pav\";s:5:\"badge\";s:28:\"खास आकर्षण\";s:8:\"badge_mr\";s:28:\"खास आकर्षण\";s:8:\"badge_en\";s:18:\"Wood-Fired Special\";s:10:\"badge_icon\";s:4:\"🔥\";s:8:\"category\";s:28:\"खास आकर्षण\";s:11:\"category_mr\";s:28:\"खास आकर्षण\";s:11:\"category_en\";s:8:\"Specials\";s:17:\"short_description\";s:278:\"खास गावरान मसाल्यांमध्ये चुलीवर शिजवलेला कट, मटकी उसळ, कुरकुरीत फरसाण, कांदा-लिंबू आणि मऊ पावासह अस्सल चव.\";s:20:\"short_description_mr\";s:278:\"खास गावरान मसाल्यांमध्ये चुलीवर शिजवलेला कट, मटकी उसळ, कुरकुरीत फरसाण, कांदा-लिंबू आणि मऊ पावासह अस्सल चव.\";s:20:\"short_description_en\";s:135:\"Slow-simmered on traditional clay stoves with handmade village spices, sprouted moth beans, crunchy farsan, onion, lemon, and soft pav.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/dining/1788245769_mye5oSqRrM.jpg\";s:12:\"dietary_type\";s:8:\"pure_veg\";s:10:\"sort_order\";i:3;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-09-01T06:30:21+00:00\";}i:3;a:19:{s:2:\"id\";i:4;s:5:\"title\";s:64:\"संध्याकाळचा हाय-टी व भजी\";s:8:\"title_mr\";s:64:\"संध्याकाळचा हाय-टी व भजी\";s:8:\"title_en\";s:29:\"High Tea & Countryside Snacks\";s:5:\"badge\";s:43:\"संध्याकाळचा चहा\";s:8:\"badge_mr\";s:43:\"संध्याकाळचा चहा\";s:8:\"badge_en\";s:11:\"Evening Tea\";s:10:\"badge_icon\";s:3:\"☕\";s:8:\"category\";s:38:\"पेये व स्नॅक्स\";s:11:\"ca