('visava-cache-api_events_en', 'a:6:{i:0;a:18:{s:2:\"id\";i:23;s:5:\"title\";s:16:\"Birthday Parties\";s:8:\"title_mr\";s:75:\"वाढदिवस व पार्टी सेलिब्रेशन\";s:8:\"title_en\";s:16:\"Birthday Parties\";s:4:\"slug\";s:16:\"birthday-parties\";s:8:\"location\";s:44:\"Babacha Mala – Celebration Lawn & Poolside\";s:11:\"location_mr\";s:102:\"बाबांचा मळा – सेलिब्रेशन लॉन व पूलसाइड\";s:11:\"location_en\";s:44:\"Babacha Mala – Celebration Lawn & Poolside\";s:10:\"event_date\";s:25:\"2026-09-05T08:40:00+00:00\";s:17:\"short_description\";s:123:\"Grand birthday celebration packages with theme decorations, DJ music, poolside party, cake table, and mouthwatering buffet.\";s:20:\"short_description_mr\";s:269:\"थीम डेकोरेशन, डीजे म्युझिक, पूलसाइड पार्टी, केक कटिंग आणि स्वादिष्ट जेवणासह अविस्मरणीय वाढदिवस सोहळा.\";s:20:\"short_description_en\";s:123:\"Grand birthday celebration packages with theme decorations, DJ music, poolside party, cake table, and mouthwatering buffet.\";s:11:\"description\";s:212:\"Celebrate your special milestone amidst the beauty of nature. We provide vibrant balloons and floral décor, outdoor sound setup, pool & rain dance access, tasty starters, and unlimited traditional/buffet dining.\";s:14:\"description_mr\";s:466:\"निसर्गरम्य वातावरणात आपल्या प्रियजनांचा वाढदिवस साजरा करा. आकर्षक सजावट, डीजे साउंड, स्विमिंग पूल, रेन डान्स, स्वादिष्ट स्टार्टर्स आणि अस्सल गावरान जेवणाची परिपूर्ण व्यवस्था.\";s:14:\"description_en\";s:212:\"Celebrate your special milestone amidst the beauty of nature. We provide vibrant balloons and floral décor, outdoor sound setup, pool & rain dance access, tasty starters, and unlimited traditional/buffet dining.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/events/1788169644_nM3u9BvAQj.jpg\";s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:1;a:18:{s:2:\"id\";i:24;s:5:\"title\";s:14:\"School Picnics\";s:8:\"title_mr\";s:45:\"शालेय व कॉलेज सहल\";s:8:\"title_en\";s:14:\"School Picnics\";s:4:\"slug\";s:14:\"school-picnics\";s:8:\"location\";s:45:\"Babacha Mala – Agro Science & Sports Ground\";s:11:\"location_mr\";s:102:\"बाबांचा मळा – कृषी विज्ञान व क्रीडांगण\";s:11:\"location_en\";s:45:\"Babacha Mala – Agro Science & Sports Ground\";s:10:\"event_date\";s:25:\"2026-09-10T08:40:00+00:00\";s:17:\"short_description\";s:119:\"Safe, educational, and fun-filled outdoor school picnics with guided farm tours, student meals, and traditional sports.\";s:20:\"short_description_mr\";s:290:\"विद्यार्थ्यांसाठी सुरक्षित, माहितीपूर्ण आणि आनंददायी सहल; सेंद्रिय शेती धडे, पौष्टिक अल्पोपहार आणि देशी खेळ.\";s:20:\"short_description_en\";s:119:\"Safe, educational, and fun-filled outdoor school picnics with guided farm tours, student meals, and traditional sports.\";s:11:\"description\";s:219:\"Tailored specifically for schools, colleges, and educational academies. Includes botanical knowledge sessions, water conservation workshops, pottery making, tree plantation, sports coordinators, and clean student meals.\";s:14:\"description_mr\";s:385:\"शाळा आणि महाविद्यालयांसाठी विशेष सहल आयोजन. वनस्पतींची ओळख, सेंद्रिय खत निर्मिती, जलसंवर्धन, कुंभारकाम, मैदानी खेळ आणि शुद्ध सात्विक भोजनाची सोय.\";s:14:\"description_en\";s:219:\"Tailored specifically for schools, colleges, and educational academies. Includes botanical knowledge sessions, water conservation workshops, pottery making, tree plantation, sports coordinators, and clean student meals.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/events/1788169667_BuXJ0CCTTF.jpg\";s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:2;a:18:{s:2:\"id\";i:25;s:5:\"title\";s:16:\"Corporate Events\";s:8:\"title_mr\";s:91:\"कॉर्पोरेट टीम बिल्डिंग व मिटिंग्ज\";s:8:\"title_en\";s:16:\"Corporate Events\";s:4:\"slug\";s:16:\"corporate-events\";s:8:\"location\";s:41:\"Babacha Mala – Open-Air Conference Lawn\";s:11:\"location_mr\";s:93:\"बाबांचा मळा – ओपन-एअर कॉन्फरन्स लॉन\";s:11:\"location_en\";s:41:\"Babacha Mala – Open-Air Conference Lawn\";s:10:\"event_date\";s:25:\"2026-09-15T08:40:00+00:00\";s:17:\"short_description\";s:119:\"Team retreats, leadership offsites, annual day celebrations, and employee engagement games in a scenic open-air campus.\";s:20:\"short_description_mr\";s:284:\"कर्मचाऱ्यांसाठी टीम बिल्डिंग उपक्रम, वार्षिक स्नेहसंमेलन, लीडरशिप रिट्रीट आणि प्रशस्त लॉनवरील इव्हेंट्स.\";s:20:\"short_description_en\";s:119:\"Team retreats, leadership offsites, annual day celebrations, and employee engagement games in a scenic open-air campus.\";s:11:\"description\";s:189:\"Escape stressful boardroom settings. Host team outings, presentations, outdoor team building exercises, cocktail-free retreats, and grand barbecue dinners in a calm countryside environment.\";s:14:\"description_mr\";s:393:\"ऑफिसच्या चार भिंतींच्या पलीकडे निसर्गरम्य ठिकाणी टीम बॉन्डिंग. ओपन लॉन, पीए सिस्टीम, ग्रुप गेम्स, डीजे रेन डान्स आणि व्हीआयपी बुफे जेवणासह उत्तम सोय.\";s:14:\"description_en\";s:189:\"Escape stressful boardroom settings. Host team outings, presentations, outdoor team building exercises, cocktail-free retreats, and grand barbecue dinners in a calm countryside environment.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/events/1788169695_1TfMbc8xcQ.jpg\";s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:3;a:18:{s:2:\"id\";i:26;s:5:\"title\";s:17:\"Family Gatherings\";s:8:\"title_mr\";s:81:\"कौटुंबिक स्नेहसंमेलन व मेळावे\";s:8:\"title_en\";s:17:\"Family Gatherings\";s:4:\"slug\";s:17:\"family-gatherings\";s:8:\"location\";s:40:\"Babacha Mala – Shaded Heritage Gazebos\";s:11:\"location_mr\";s:101:\"बाबांचा मळा – सावलीदार हेरिटेज गझेबोज\";s:11:\"location_en\";s:40:\"Babacha Mala – Shaded Heritage Gazebos\";s:10:\"event_date\";s:25:\"2026-09-20T08:40:00+00:00\";s:17:\"short_description\";s:118:\"Spacious gazebos, kids play parks, bullock cart rides, and hot wood-fired chulha food for large joint family reunions.\";s:20:\"short_description_mr\";s:278:\"एकत्र कुटुंबासाठी प्रशस्त जागा, लहान मुलांचे खेळ, बैलगाडी सफर आणि गरमागरम चुलीवरची अस्सल गावरान मेजवानी.\";s:20:\"short_description_en\";s:118:\"Spacious gazebos, kids play parks, bullock cart rides, and hot wood-fired chulha food for large joint family reunions.\";s:11:\"description\";s:206:\"Create cherished lifetime memories with multiple generations coming together. Enjoy private shaded pavilions, elderly-friendly walking paths, children play zones, music, and wholesome Maharashtrian cuisine.\";s:14:\"description_mr\";s:384:\"आजी-आजोबांपासून नातवंडांपर्यंत सर्वांना आनंद देणारा कौटुंबिक सोहळा. शांत सावली, विहीर स्नान, संगीत, पारंपारिक खेळ आणि पोटभर गावरान जेवणाचा आनंद.\";s:14:\"description_en\";s:206:\"Create cherished lifetime memories with multiple generations coming together. Enjoy private shaded pavilions, elderly-friendly walking paths, children play zones, music, and wholesome Maharashtrian cuisine.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/events/1788782464_1pxGkwrg0T.png\";s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:4;a:18:{s:2:\"id\";i:27;s:5:\"title\";s:23:\"Pre-Wedding Photoshoots\";s:8:\"title_mr\";s:67:\"प्री-वेडिंग व कपल फोटोशूट\";s:8:\"title_en\";s:23:\"Pre-Wedding Photoshoots\";s:4:\"slug\";s:23:\"pre-wedding-photoshoots\";s:8:\"location\";s:50:\"Babacha Mala – Vineyard Trails & Scenic Lakeview\";s:11:\"location_mr\";s:121:\"बाबांचा मळा – द्राक्ष बागा व निसर्गरम्य परिसर\";s:11:\"location_en\";s:50:\"Babacha Mala – Vineyard Trails & Scenic Lakeview\";s:10:\"event_date\";s:25:\"2026-09-25T08:40:00+00:00\";s:17:\"short_description\";s:126:\"Stunning agro backdrops, sunset vineyard trails, rustic wooden cottages, decorated bullock carts, and private changing suites.\";s:20:\"short_description_mr\";s:283:\"द्राक्ष बागा, हिरवेगार शिवार, लाकडी कॉटेज, विहीर, पारंपारिक बैलगाडी आणि विहंगम सनसेट स्पॉट्ससह खास फोटोशूट.\";s:20:\"short_description_en\";s:126:\"Stunning agro backdrops, sunset vineyard trails, rustic wooden cottages, decorated bullock carts, and private changing suites.\";s:11:\"description\";s:216:\"Capture your timeless romantic moments with 20+ photogenic locations across 15 acres. Includes lush grape vineyards, rustic bullock carts, floral swings, poolside reflections, and dedicated private AC changing rooms.\";s:14:\"description_mr\";s:465:\"तुमच्या लग्नापूर्वीचे सोनेरी क्षण कॅमेऱ्यात टिपण्यासाठी परिपूर्ण जागा. १५ एकर परिसर, २०+ नैसर्गिक बॅकड्रॉप्स, सनसेट पॉईंट्स, प्रायव्हेट ड्रेसिंग रूम्स आणि रिफ्रेशमेंटची सोय.\";s:14:\"description_en\";s:216:\"Capture your timeless romantic moments with 20+ photogenic locations across 15 acres. Includes lush grape vineyards, rustic bullock carts, floral swings, poolside reflections, and dedicated private AC changing rooms.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/events/1788781987_ez5Ot0ZcZd.png\";s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:5;a:18:{s:2:\"id\";i:28;s:5:\"title\";s:17:\"Cultural Programs\";s:8:\"title_mr\";s:109:\"सांस्कृतिक व पारंपारिक लोककला कार्यक्रम\";s:8:\"title_en\";s:17:\"Cultural Programs\";s:4:\"slug\";s:17:\"cultural-programs\";s:8:\"location\";s:38:\"Babacha Mala – Heritage Amphitheatre\";s:11:\"location_mr\";s:88:\"बाबांचा मळा – हेरिटेज ॲम्फीथिएटर\";s:11:\"location_en\";s:38:\"Babacha Mala – Heritage Amphitheatre\";s:10:\"event_date\";s:25:\"2026-09-30T08:40:00+00:00\";s:17:\"short_description\";s:125:\"Folk dances (Lavani, Gondhal), traditional music nights, seasonal harvest festivals, and Maharashtrian cultural celebrations.\";s:20:\"short_description_mr\";s:248:\"पारंपारिक लोकनृत्य, गोंधळ, भारुड, संगीत रजनी आणि महाराष्ट्राच्या समृद्ध लोकसंस्कृतीचे दर्शन.\";s:20:\"short_description_en\";s:125:\"Folk dances (Lavani, Gondhal), traditional music nights, seasonal harvest festivals, and Maharashtrian cultural celebrations.\";s:11:\"description\";s:200:\"Immerse in the rich traditions of Maharashtra. Experience live folk performances, Powada ballads, rhythmic Lezim dances, Dhol-Tasha beats, traditional crafts exhibitions, and authentic festive treats.\";s:14:\"description_mr\";s:340:\"महाराष्ट्राच्या लोककलेचा आणि संस्कृतीचा गौरव. लावणी, पोवाडा, लेझीम, ढोल-ताशा गजर आणि अस्सल गावरान सण-उत्सवांचा अविस्मरणीय अनुभव.\";s:14:\"description_en\";s:200:\"Immerse in the rich traditions of Maharashtra. Experience live folk performances, Powada ballads, rhythmic Lezim dances, Dhol-Tasha beats, traditional crafts exhibitions, and authentic festive treats.\";s:5:\"image\";s:70:\"http://127.0.0.1:8000/storage/uploads/events/1788782003_Eopha9UfQo.png\";s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}}', 1788794116),
