('visava-cache-api_packages_mr', 'a:7:{i:0;a:19:{s:2:\"id\";i:30;s:5:\"title\";s:41:\"डे पिकनिक पॅकेज\";s:8:\"title_mr\";s:41:\"डे पिकनिक पॅकेज\";s:8:\"title_en\";s:18:\"Day Picnic Package\";s:4:\"slug\";s:18:\"day-picnic-package\";s:8:\"duration\";s:94:\"१ दिवस (सकाळी ९:०० ते संध्याकाळी ६:३०)\";s:11:\"duration_mr\";s:94:\"१ दिवस (सकाळी ९:०० ते संध्याकाळी ६:३०)\";s:11:\"duration_en\";s:27:\"1 Day (9:00 AM – 6:30 PM)\";s:17:\"short_description\";s:283:\"सकाळचा नाश्ता, चुलीवरचे अस्सल गावरान जेवण, स्विमिंग पूल, रेन डान्स आणि शिवार फेरीसह संपूर्ण दिवसाची मौजमजा.\";s:20:\"short_description_mr\";s:283:\"सकाळचा नाश्ता, चुलीवरचे अस्सल गावरान जेवण, स्विमिंग पूल, रेन डान्स आणि शिवार फेरीसह संपूर्ण दिवसाची मौजमजा.\";s:20:\"short_description_en\";s:120:\"Full-day agro picnic with breakfast, wood-fired Maharashtrian lunch, high tea, swimming pool, rain dance, and farm tour.\";s:11:\"description\";s:440:\"निसर्गाच्या सान्निध्यात एक अविस्मरणीय दिवस घालवा. अस्सल चुलीवरची गावरान मिसळ, जेवण, स्विमिंग पूल, रेन डान्स, द्राक्ष बागांची सफर आणि बैलगाडी राईडचा मनमुराद आनंद घ्या.\";s:14:\"description_mr\";s:440:\"निसर्गाच्या सान्निध्यात एक अविस्मरणीय दिवस घालवा. अस्सल चुलीवरची गावरान मिसळ, जेवण, स्विमिंग पूल, रेन डान्स, द्राक्ष बागांची सफर आणि बैलगाडी राईडचा मनमुराद आनंद घ्या.\";s:14:\"description_en\";s:214:\"Experience a refreshing full-day outing with your loved ones. Enjoy farm-fresh authentic village food, access to swimming pool, pulsating rain dance, vineyard tour, bullock cart rides, and traditional rural sports.\";s:14:\"featured_image\";s:72:\"http://127.0.0.1:8000/storage/uploads/packages/1788177436_AcFjHixVBB.png\";s:10:\"inclusions\";a:6:{i:0;s:39:\"Welcome Drink & Morning Breakfast / Tea\";i:1;s:58:\"Unlimited Wood-Fired Authentic Maharashtrian Lunch & Misal\";i:2;s:33:\"Evening High Tea & Village Snacks\";i:3;s:39:\"Swimming Pool & Music Rain Dance Access\";i:4;s:41:\"Grape Vineyard & Organic Farm Guided Tour\";i:5;s:52:\"Bullock Cart Ride & Rural Games (Viti-Dandu, Lagori)\";}s:10:\"exclusions\";a:3:{i:0;s:22:\"Overnight Cottage Stay\";i:1;s:37:\"Personal Shopping & Nursery Purchases\";i:2;s:23:\"Extra Bottled Beverages\";}s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-31T08:40:07+00:00\";}i:1;a:19:{s:2:\"id\";i:31;s:5:\"title\";s:59:\"कौटुंबिक फॅमिली पॅकेज\";s:8:\"title_mr\";s:59:\"कौटुंबिक फॅमिली पॅकेज\";s:8:\"title_en\";s:14:\"Family Package\";s:4:\"slug\";s:14:\"family-package\";s:8:\"duration\";s:91:\"पूर्ण दिवस / १ रात्र मुक्काम पर्याय\";s:11:\"duration_mr\";s:91:\"पूर्ण दिवस / १ रात्र मुक्काम पर्याय\";s:11:\"duration_en\";s:25:\"Full Day / 1 Night Option\";s:17:\"short_description\";s:283:\"कुटुंबासाठी (२ मोठे + २ लहान मुले) सर्व जेवण, मुलांचा ॲडव्हेंचर झोन आणि कौटुंबिक मनोरंजनासह खास कॉम्बो पॅकेज.\";s:20:\"short_description_mr\";s:283:\"कुटुंबासाठी (२ मोठे + २ लहान मुले) सर्व जेवण, मुलांचा ॲडव्हेंचर झोन आणि कौटुंबिक मनोरंजनासह खास कॉम्बो पॅकेज.\";s:20:\"short_description_en\";s:115:\"Special combo package for families (2 Adults + 2 Kids) with all meals, kids adventure zone, and bullock cart rides.\";s:11:\"description\";s:428:\"शहरी धकाधकीपासून दूर संपूर्ण कुटुंबासाठी आनंददायी क्षण. लहान मुलांसाठी सुरक्षित खेळ परिसर, स्विमिंग पूल, बैलगाडी सफर आणि शुद्ध सात्विक गावरान जेवणाची उत्तम सोय.\";s:14:\"description_mr\";s:428:\"शहरी धकाधकीपासून दूर संपूर्ण कुटुंबासाठी आनंददायी क्षण. लहान मुलांसाठी सुरक्षित खेळ परिसर, स्विमिंग पूल, बैलगाडी सफर आणि शुद्ध सात्विक गावरान जेवणाची उत्तम सोय.\";s:14:\"description_en\";s:200:\"Specially crafted for families looking for peaceful quality time away from city stress. Includes safe children play areas, organic farm activities, poolside relaxation, and wholesome traditional food.\";s:14:\"featured_image\";s:72:\"http://127.0.0.1:8000/storage/uploads/packages/1788177450_MaRGbaROFW.png\";s:10:\"inclusions\";a:6:{i:0;s:40:\"Entry for 2 Adults & 2 Children under 10\";i:1;s:46:\"All Meals: Breakfast, Lunch, High Tea & Snacks\";i:2;s:46:\"Dedicated Family Shaded Cottage / Seating Area\";i