('visava-cache-api_testimonials_en', 'a:3:{i:0;a:12:{s:2:\"id\";i:1;s:11:\"client_name\";s:55:\"सचिन कुलकर्णी (Sachin Kulkarni)\";s:18:\"client_designation\";s:21:\"Pune (Family Visitor)\";s:21:\"client_designation_mr\";s:58:\"पुणे (कौटुंबिक पर्यटक)\";s:21:\"client_designation_en\";s:21:\"Pune (Family Visitor)\";s:6:\"review\";s:166:\"Our entire family had a fabulous experience at Babacha Mala! The wood-fired Misal and fresh Hurda party were outstanding. The kids loved the farm activities and pool.\";s:9:\"review_mr\";s:397:\"बाबांचा मळा येथे आमच्या संपूर्ण कुटुंबाला प्रचंड आनंद मिळाला. चुलीवरची मिसळ आणि हुरडा पार्टी अप्रतिम होती. मुले शेती आणि स्विमिंग पूलमध्ये रमून गेली.\";s:9:\"review_en\";s:166:\"Our entire family had a fabulous experience at Babacha Mala! The wood-fired Misal and fresh Hurda party were outstanding. The kids loved the farm activities and pool.\";s:6:\"rating\";i:5;s:12:\"client_image\";N;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-25T11:02:17+00:00\";}i:1;a:12:{s:2:\"id\";i:2;s:11:\"client_name\";s:49:\"प्रिया सावंत (Priya Sawant)\";s:18:\"client_designation\";s:24:\"Mumbai (Corporate Group)\";s:21:\"client_designation_mr\";s:74:\"मुंबई (कॉर्पोरेट ग्रुप लीडर)\";s:21:\"client_designation_en\";s:24:\"Mumbai (Corporate Group)\";s:6:\"review\";s:163:\"A serene and rejuvenating getaway from city life. The cottages are sparkling clean and the staff hospitality is heartwarming. Highly recommended for group outings!\";s:9:\"review_mr\";s:342:\"शहरी गोंगाटापासून दूर अतिशय शांत आणि निसर्गरम्य जागा. कॉटेजेस स्वच्छ आहेत आणि आदरातिथ्य घरच्यासारखे आहे. आम्ही नक्की पुन्हा येऊ!\";s:9:\"review_en\";s:163:\"A serene and rejuvenating getaway from city life. The cottages are sparkling clean and the staff hospitality is heartwarming. Highly recommended for group outings!\";s:6:\"rating\";i:5;s:12:\"client_image\";N;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:25:\"2026-08-25T11:02:17+00:00\";}i:2;a:12:{s:2:\"id\";i:3;s:11:\"client_name\";