INSERT INTO `dining_items` (`id`, `title_mr`, `title_en`, `badge_mr`, `badge_en`, `badge_icon`, `category_mr`, `category_en`, `short_description_mr`, `short_description_en`, `image`, `dietary_type`, `sort_order`, `is_active`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'अस्सल गावरान जेवण व अमर्यादित थाळी', 'Authentic Gavran Thali & Village Feasts', 'अस्सल जेवण', 'Gavran Lunch', '🍛', 'दुपारचे / रात्रीचे जेवण', 'Lunch & Dinner', 'ज्वारी-बाजरीची गरमागरम चुलीवरची भाकरी, अस्सल गावरान पिठलं, खर्डा/ठेचा, वांग्याचे भरीत, शेतातील ताजी भाजी, ताक आणि चुलीवरचा सुगंध.', 'Enjoy a traditional Gavran Thali with hot Jowar/Bajra Bhakri, authentic Pithla, Thecha, roasted Baingan Bharta, fresh farm greens, and homemade flavors.', 'uploads/dining/1788245707_7M5w1jvB2s.jpg', 'pure_veg', 1, 1, 'active', NULL, 1, '2026-09-01 01:00:21', '2026-09-01 01:25:07', NULL),
(2, 'पारंपरिक गावरान नाश्ता', 'Traditional Village Breakfast', 'सकाळचा नाश्ता', 'Village Breakfast', '🌅', 'सकाळचा नाश्ता', 'Breakfast', 'सकाळच्या शुद्ध हवेत गरमागरम थालिपीठ-लोणी, कांदे पोहे, उपमा आणि चुलीवरचा अस्सल गुळाचा किंवा आल्याचा चहा.', 'Start your morning with freshly prepared Thalipeeth with white butter, steaming Kande Pohe, Upma, and wood-fired organic Jaggery/Ginger Tea.', 'uploads/dining/1788330609_GVOylBYUwi.jpg', 'pure_veg', 2, 1, 'active', NULL, 1, '2026-09-01 01:00:21', '2026-09-02 01:00:09', NULL),
(3, 'चुलीवरची झणझणीत मिसळ', 'Wood-Fired Maharashtrian Misal Pav', 'खास आकर्षण', 'Wood-Fired Special', '🔥', 'खास आकर्षण', 'Specials', 'खास गावरान मसाल्यांमध्ये चुलीवर शिजवलेला कट, मटकी उसळ, कुरकुरीत फरसाण, कांदा-लिंबू आणि मऊ पावासह अस्सल चव.', 'Slow-simmered on traditional clay stoves with handmade village spices, sprouted moth beans, crunchy farsan, onion, lemon, and soft pav.', 'uploads/dining/1788245769_mye5oSqRrM.jpg', 'pure_veg', 3, 1, 'active', NULL, 1, '2026-09-01 01:00:21', '2026-09-01 01:26:09', NULL),
(4, 'संध्याकाळचा हाय-टी व भजी', 'High Tea & Countryside Snacks', 'संध्याकाळचा चहा', 'Evening Tea', '☕', 'पेये व स्नॅक्स', 'High Tea & Snacks', 'निसर्गाच्या सान्निध्यात संध्याकाळचा गरमागरम कडक चहा आणि सोबत कुरकुरीत कांदा भजी व पारंपरिक स्नॅक्स.', 'Crispy Kanda Bhaji, steaming tea infused with natural spices, and evening tranquility amid lush farms and country breeze.', 'uploads/dining/1788245853_v8alAvxyke.jpg', 'pure_veg', 4, 1, 'active', NULL, 1, '2026-09-01 01:00:21', '2026-09-01 01:27:33', NULL),
(5, 'बागेतील ताजी सेंद्रिय फळे व गूळ', 'Seasonal Farm-Fresh Organic Fruits', 'ताज्या फळांची मेजवानी', 'Organic Fruits', '🍍', 'शेतातील फळे', 'Farm Fruits', 'हंगामानुसार बागेतील ताजी द्राक्षे, डाळिंब, पेरू, बोरं, सीताफळ आणि उसाचा ताजा गूळ चाखण्याची नामी संधी.', 'Taste seasonal sweetness straight from our orchards — fresh grapes, pomegranates, guavas, sweet limes, and pure sugarcane jaggery.', 'uploads/dining/1788245788_KbJ3qcjItH.jpg', 'pure_veg', 5, 1, 'active', NULL, 1, '2026-09-01 01:00:21', '2026-09-01 01:26:28', NULL),
(6, 'कौटुंबिक व ग्रुप मेजवानी पॅकेजेस', 'Customized Group Feasts & Outing Menus', 'ग्रुप मेजवानी', 'Group Feasts', '👨‍👩‍👧‍👦', 'ग्रुप मेजवानी', 'Group Feasts', 'शालेय सहली, कौटुंबिक स्नेहसंमेलन, वाढदिवस आणि कॉर्पोरेट आऊटिंगसाठी खास सानुकूलित मेन्यू व अमर्यादित डायनिंग.', 'Customized unlimited meal packages for school picnics, corporate outings, birthdays, and family gatherings with authentic village hospitality.', 'uploads/dining/1788251540_Xv3Jv8mtJu.jpg', 'pure_veg', 6, 1, 'active', NULL, 1, '2026-09-01 01:00:21', '2026-09-01 03:02:20', NULL),
(7, 'चाचणी थाळी', 'Test Thali', 'नवीन', 'New', '🍛', 'थाळी', 'Thali', 'चाचणी वर्णन', 'Test description', NULL, 'pure_veg', 99, 1, 'active', NULL, NULL, '2026-09-01 01:07:12', '2026-09-01 01:07:12', '2026-09-01 01:07:12');

