INSERT INTO `events` (`id`, `title_mr`, `title_en`, `title`, `slug`, `location_mr`, `location_en`, `event_date`, `short_description_mr`, `short_description_en`, `description_mr`, `description_en`, `image`, `status`, `created_by`, `updated_by`, `description`, `location`, `start_date`, `end_date`, `price`, `banner_image`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(23, 'वाढदिवस व पार्टी सेलिब्रेशन', 'Birthday Parties', 'Birthday Parties', 'birthday-parties', 'बाबांचा मळा – सेलिब्रेशन लॉन व पूलसाइड', 'Babacha Mala – Celebration Lawn & Poolside', '2026-09-05 08:40:00', 'थीम डेकोरेशन, डीजे म्युझिक, पूलसाइड पार्टी, केक कटिंग आणि स्वादिष्ट जेवणासह अविस्मरणीय वाढदिवस सोहळा.', 'Grand birthday celebration packages with theme decorations, DJ music, poolside party, cake table, and mouthwatering buffet.', 'निसर्गरम्य वातावरणात आपल्या प्रियजनांचा वाढदिवस साजरा करा. आकर्षक सजावट, डीजे साउंड, स्विमिंग पूल, रेन डान्स, स्वादिष्ट स्टार्टर्स आणि अस्सल गावरान जेवणाची परिपूर्ण व्यवस्था.', 'Celebrate your special milestone amidst the beauty of nature. We provide vibrant balloons and floral décor, outdoor sound setup, pool & rain dance access, tasty starters, and unlimited traditional/buffet dining.', 'uploads/events/1788169644_nM3u9BvAQj.jpg', 'active', 1, 1, 'Celebrate your special milestone amidst the beauty of nature. We provide vibrant balloons and floral décor, outdoor sound setup, pool & rain dance access, tasty starters, and unlimited traditional/buffet dining.', 'Babacha Mala – Celebration Lawn & Poolside', '2026-09-05 08:40:00', NULL, 599.00, 'uploads/events/1788169644_nM3u9BvAQj.jpg', 1, '2026-08-31 03:10:07', '2026-08-31 04:17:24', NULL),
(24, 'शालेय व कॉलेज सहल', 'School Picnics', 'School Picnics', 'school-picnics', 'बाबांचा मळा – कृषी विज्ञान व क्रीडांगण', 'Babacha Mala – Agro Science & Sports Ground', '2026-09-10 08:40:00', 'विद्यार्थ्यांसाठी सुरक्षित, माहितीपूर्ण आणि आनंददायी सहल; सेंद्रिय शेती धडे, पौष्टिक अल्पोपहार आणि देशी खेळ.', 'Safe, educational, and fun-filled outdoor school picnics with guided farm tours, student meals, and traditional sports.', 'शाळा आणि महाविद्यालयांसाठी विशेष सहल आयोजन. वनस्पतींची ओळख, सेंद्रिय खत निर्मिती, जलसंवर्धन, कुंभारकाम, मैदानी खेळ आणि शुद्ध सात्विक भोजनाची सोय.', 'Tailored specifically for schools, colleges, and educational academies. Includes botanical knowledge sessions, water conservation workshops, pottery making, tree plantation, sports coordinators, and clean student meals.', 'uploads/events/1788169667_BuXJ0CCTTF.jpg', 'active', 1, 1, 'Tailored specifically for schools, colleges, and educational academies. Includes botanical knowledge sessions, water conservation workshops, pottery making, tree plantation, sports coordinators, and clean student meals.', 'Babacha Mala – Agro Science & Sports Ground', '2026-09-10 08:40:00', NULL, 449.00, 'uploads/events/1788169667_BuXJ0CCTTF.jpg', 1, '2026-08-31 03:10:07', '2026-08-31 04:17:47', NULL),
(25, 'कॉर्पोरेट टीम बिल्डिंग व मिटिंग्ज', 'Corporate Events', 'Corporate Events', 'corporate-events', 'बाबांचा मळा – ओपन-एअर कॉन्फरन्स लॉन', 'Babacha Mala – Open-Air Conference Lawn', '2026-09-15 08:40:00', 'कर्मचाऱ्यांसाठी टीम बिल्डिंग उपक्रम, वार्षिक स्नेहसंमेलन, लीडरशिप रिट्रीट आणि प्रशस्त लॉनवरील इव्हेंट्स.', 'Team retreats, leadership offsites, annual day celebrations, and employee engagement games in a scenic open-air campus.', 'ऑफिसच्या चार भिंतींच्या पलीकडे निसर्गरम्य ठिकाणी टीम बॉन्डिंग. ओपन लॉन, पीए सिस्टीम, ग्रुप गेम्स, डीजे रेन डान्स आणि व्हीआयपी बुफे जेवणासह उत्तम सोय.', 'Escape stressful boardroom settings. Host team outings, presentations, outdoor team building exercises, cocktail-free retreats, and grand barbecue dinners in a calm countryside environment.', 'uploads/events/1788169695_1TfMbc8xcQ.jpg', 'active', 1, 1, 'Escape stressful boardroom settings. Host team outings, presentations, outdoor team building exercises, cocktail-free retreats, and grand barbecue dinners in a calm countryside environment.', 'Babacha Mala – Open-Air Conference Lawn', '2026-09-15 08:40:00', NULL, 1099.00, 'uploads/events/1788169695_1TfMbc8xcQ.jpg', 1, '2026-08-31 03:10:07', '2026-08-31 04:18:16', NULL),
(26, 'कौटुंबिक स्नेहसंमेलन व मेळावे', 'Family Gatherings', 'Family Gatherings', 'family-gatherings', 'बाबांचा मळा – सावलीदार हेरिटेज गझेबोज', 'Babacha Mala – Shaded Heritage Gazebos', '2026-09-20 08:40:00', 'एकत्र कुटुंबासाठी प्रशस्त जागा, लहान मुलांचे खेळ, बैलगाडी सफर आणि गरमागरम चुलीवरची अस्सल गावरान मेजवानी.', 'Spacious gazebos, kids play parks, bullock cart rides, and hot wood-fired chulha food for large joint family reunions.', 'आजी-आजोबांपासून नातवंडांपर्यंत सर्वांना आनंद देणारा कौटुंबिक सोहळा. शांत सावली, विहीर स्नान, संगीत, पारंपारिक खेळ आणि पोटभर गावरान जेवणाचा आनंद.', 'Create cherished lifetime memories with multiple generations coming together. Enjoy private shaded pavilions, elderly-friendly walking paths, children play zones, music, and wholesome Maharashtrian cuisine.', 'uploads/events/1788782464_1pxGkwrg0T.png', 'active', 1, 1, 'Create cherished lifetime memories with multiple generations coming together. Enjoy private shaded pavilions, elderly-friendly walking paths, children play zones, music, and wholesome Maharashtrian cuisine.', 'Babacha Mala – Shaded Heritage Gazebos', '2026-09-20 08:40:00', NULL, 699.00, 'uploads/events/1788782464_1pxGkwrg0T.png', 1, '2026-08-31 03:10:07', '2026-09-07 06:31:05', NULL),
(27, 'प्री-वेडिंग व कपल फोटोशूट', 'Pre-Wedding Photoshoots', 'Pre-Wedding Photoshoots', 'pre-wedding-photoshoots', 'बाबांचा मळा – द्राक्ष बागा व निसर्गरम्य परिसर', 'Babacha Mala – Vineyard Trails & Scenic Lakeview', '2026-09-25 08:40:00', 'द्राक्ष बागा, हिरवेगार शिवार, लाकडी कॉटेज, विहीर, पारंपारिक बैलगाडी आणि विहंगम सनसेट स्पॉट्ससह खास फोटोशूट.', 'Stunning agro backdrops, sunset vineyard trails, rustic wooden cottages, decorated bullock carts, and private changing suites.', 'तुमच्या लग्नापूर्वीचे सोनेरी क्षण कॅमेऱ्यात टिपण्यासाठी परिपूर्ण जागा. १५ एकर परिसर, २०+ नैसर्गिक बॅकड्रॉप्स, सनसेट पॉईंट्स, प्रायव्हेट ड्रेसिंग रूम्स आणि रिफ्रेशमेंटची सोय.', 'Capture your timeless romantic moments with 20+ photogenic locations across 15 acres. Includes lush grape vineyards, rustic bullock carts, floral swings, poolside reflections, and dedicated private AC changing rooms.', 'uploads/events/1788781987_ez5Ot0ZcZd.png', 'active', 1, 1, 'Capture your timeless romantic moments with 20+ photogenic locations across 15 acres. Includes lush grape vineyards, rustic bullock carts, floral swings, poolside reflections, and dedicated private AC changing rooms.', 'Babacha Mala – Vineyard Trails & Scenic Lakeview', '2026-09-25 08:40:00', NULL, 2499.00, 'uploads/events/1788781987_ez5Ot0ZcZd.png', 1, '2026-08-31 03:10:07', '2026-09-07 06:23:09', NULL),
(28, 'सांस्कृतिक व पारंपारिक लोककला कार्यक्रम', 'Cultural Programs', 'Cultural Programs', 'cultural-programs', 'बाबांचा मळा – हेरिटेज ॲम्फीथिएटर', 'Babacha Mala – Heritage Amphitheatre', '2026-09-30 08:40:00', 'पारंपारिक लोकनृत्य, गोंधळ, भारुड, संगीत रजनी आणि महाराष्ट्राच्या समृद्ध लोकसंस्कृतीचे दर्शन.', 'Folk dances (Lavani, Gondhal), traditional music nights, seasonal harvest festivals, and Maharashtrian cultural celebrations.', 'महाराष्ट्राच्या लोककलेचा आणि संस्कृतीचा गौरव. लावणी, पोवाडा, लेझीम, ढोल-ताशा गजर आणि अस्सल गावरान सण-उत्सवांचा अविस्मरणीय अनुभव.', 'Immerse in the rich traditions of Maharashtra. Experience live folk performances, Powada ballads, rhythmic Lezim dances, Dhol-Tasha beats, traditional crafts exhibitions, and authentic festive treats.', 'uploads/events/1788782003_Eopha9UfQo.png', 'active', 1, 1, 'Immerse in the rich traditions of Maharashtra. Experience live folk performances, Powada ballads, rhythmic Lezim dances, Dhol-Tasha beats, traditional crafts exhibitions, and authentic festive treats.', 'Babacha Mala – Heritage Amphitheatre', '2026-09-30 08:40:00', NULL, 499.00, 'uploads/events/1788782003_Eopha9UfQo.png', 1, '2026-08-31 03:10:07', '2026-09-07 06:23:24', NULL),
(29, 'चाचणी इव्हेंट', 'Test Event', NULL, 'test-event-Ge7Zq', NULL, NULL, '2026-09-08 06:03:13', NULL, NULL, NULL, NULL, NULL, 'active', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-09-01 00:33:13', '2026-09-01 00:33:13', '2026-09-01 00:33:13');

