INSERT INTO `packages` (`id`, `title_mr`, `title_en`, `name`, `slug`, `duration_mr`, `duration_en`, `summary`, `description`, `duration`, `price`, `short_description_mr`, `short_description_en`, `description_mr`, `description_en`, `discounted_price`, `featured_image`, `status`, `created_by`, `updated_by`, `inclusions`, `exclusions`, `is_featured`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(30, 'डे पिकनिक पॅकेज', 'Day Picnic Package', 'Day Picnic Package', 'day-picnic-package', '१ दिवस (सकाळी ९:०० ते संध्याकाळी ६:३०)', '1 Day (9:00 AM – 6:30 PM)', 'Full-day agro picnic with breakfast, wood-fired Maharashtrian lunch, high tea, swimming pool, rain dance, and farm tour.', 'Experience a refreshing full-day outing with your loved ones. Enjoy farm-fresh authentic village food, access to swimming pool, pulsating rain dance, vineyard tour, bullock cart rides, and traditional rural sports.', '1 Day (9:00 AM – 6:30 PM)', 799.00, 'सकाळचा नाश्ता, चुलीवरचे अस्सल गावरान जेवण, स्विमिंग पूल, रेन डान्स आणि शिवार फेरीसह संपूर्ण दिवसाची मौजमजा.', 'Full-day agro picnic with breakfast, wood-fired Maharashtrian lunch, high tea, swimming pool, rain dance, and farm tour.', 'निसर्गाच्या सान्निध्यात एक अविस्मरणीय दिवस घालवा. अस्सल चुलीवरची गावरान मिसळ, जेवण, स्विमिंग पूल, रेन डान्स, द्राक्ष बागांची सफर आणि बैलगाडी राईडचा मनमुराद आनंद घ्या.', 'Experience a refreshing full-day outing with your loved ones. Enjoy farm-fresh authentic village food, access to swimming pool, pulsating rain dance, vineyard tour, bullock cart rides, and traditional rural sports.', 699.00, 'uploads/packages/1788177436_AcFjHixVBB.png', 'active', 1, 1, '\"[\\\"Welcome Drink & Morning Breakfast \\\\\\/ Tea\\\",\\\"Unlimited Wood-Fired Authentic Maharashtrian Lunch & Misal\\\",\\\"Evening High Tea & Village Snacks\\\",\\\"Swimming Pool & Music Rain Dance Access\\\",\\\"Grape Vineyard & Organic Farm Guided Tour\\\",\\\"Bullock Cart Ride & Rural Games (Viti-Dandu, Lagori)\\\"]\"', '\"[\\\"Overnight Cottage Stay\\\",\\\"Personal Shopping & Nursery Purchases\\\",\\\"Extra Bottled Beverages\\\"]\"', 1, 1, '2026-08-31 03:10:07', '2026-08-31 06:27:17', NULL),
(31, 'कौटुंबिक फॅमिली पॅकेज', 'Family Package', 'Family Package', 'family-package', 'पूर्ण दिवस / १ रात्र मुक्काम पर्याय', 'Full Day / 1 Night Option', 'Special combo package for families (2 Adults + 2 Kids) with all meals, kids adventure zone, and bullock cart rides.', 'Specially crafted for families looking for peaceful quality time away from city stress. Includes safe children play areas, organic farm activities, poolside relaxation, and wholesome traditional food.', 'Full Day / 1 Night Option', 2499.00, 'कुटुंबासाठी (२ मोठे + २ लहान मुले) सर्व जेवण, मुलांचा ॲडव्हेंचर झोन आणि कौटुंबिक मनोरंजनासह खास कॉम्बो पॅकेज.', 'Special combo package for families (2 Adults + 2 Kids) with all meals, kids adventure zone, and bullock cart rides.', 'शहरी धकाधकीपासून दूर संपूर्ण कुटुंबासाठी आनंददायी क्षण. लहान मुलांसाठी सुरक्षित खेळ परिसर, स्विमिंग पूल, बैलगाडी सफर आणि शुद्ध सात्विक गावरान जेवणाची उत्तम सोय.', 'Specially crafted for families looking for peaceful quality time away from city stress. Includes safe children play areas, organic farm activities, poolside relaxation, and wholesome traditional food.', 2199.00, 'uploads/packages/1788177450_MaRGbaROFW.png', 'active', 1, 1, '\"[\\\"Entry for 2 Adults & 2 Children under 10\\\",\\\"All Meals: Breakfast, Lunch, High Tea & Snacks\\\",\\\"Dedicated Family Shaded Cottage \\\\\\/ Seating Area\\\",\\\"Kids Fun & Adventure Zone Access\\\",\\\"Private Bullock Cart Ride Experience\\\",\\\"Swimming Pool & Rain Dance with Floats\\\"]\"', '\"[\\\"Overnight Room Stay (Available on Upgrade)\\\",\\\"Driver \\\\\\/ Extra Guest Charges\\\"]\"', 1, 1, '2026-08-31 03:10:07', '2026-08-31 06:27:30', NULL),
(32, 'शालेय व महाविद्यालयीन सहल पॅकेज', 'School & College Trip Package', 'School & College Trip Package', 'school-college-trip-package', '१ दिवस (सकाळी ८:३० ते संध्याकाळी ५:३०)', '1 Day (8:30 AM – 5:30 PM)', 'Educational agro-tourism visit with hands-on farming demos, botanical guidance, student meals, and rural sports.', 'A fun-filled educational picnic tailored for students. Kids learn organic agriculture, water harvesting, botanical diversity, pottery making, and enjoy safe supervised games.', '1 Day (8:30 AM – 5:30 PM)', 499.00, 'विद्यार्थ्यांसाठी सेंद्रिय शेती प्रात्यक्षिके, निसर्ग मार्गदर्शन, पौष्टिक जेवण आणि पारंपारिक मैदानी खेळांची सहल.', 'Educational agro-tourism visit with hands-on farming demos, botanical guidance, student meals, and rural sports.', 'विद्यार्थ्यांना शेती आणि निसर्गाचे महत्त्व शिकवणारी आनंददायी सहल. सेंद्रिय खत निर्मिती, जलसंवर्धन, बीजारोपण प्रात्यक्षिके आणि सुरक्षित मैदानी खेळांचे आयोजन.', 'A fun-filled educational picnic tailored for students. Kids learn organic agriculture, water harvesting, botanical diversity, pottery making, and enjoy safe supervised games.', 449.00, 'uploads/packages/1788177516_dO8JWYfwhr.png', 'active', 1, 1, '\"[\\\"Specially Curated Hygienic Student Breakfast & Lunch\\\",\\\"Guided Educational Farm & Botany Tour\\\",\\\"Hands-on Agricultural Activity & Potting Demonstration\\\",\\\"Traditional Outdoor Games & Sports Coordinator\\\",\\\"Swimming Pool Access under Lifeguard Supervision\\\",\\\"Complimentary Entry for Accompanying Teachers (1 per 20 students)\\\"]\"', '\"[\\\"School Bus Transportation\\\",\\\"Personal Memorabilia\\\"]\"', 1, 1, '2026-08-31 03:10:07', '2026-08-31 06:28:37', NULL),
(33, 'कॉर्पोरेट टीम आऊटिंग पॅकेज', 'Corporate Outing Package', 'Corporate Outing Package', 'corporate-outing-package', '१ दिवस / बहु-दिवसीय टीम रिट्रीट', '1 Day / Multi-Day Team Retreat', 'Team building retreat with open-air conference lawn, team games, DJ rain dance, buffet dining, and relaxation.', 'Boost team morale and relieve corporate burnout with curated team activities, spacious lush green lawns for group games, rain dance party, and grand buffet meals.', '1 Day / Multi-Day Team Retreat', 1299.00, 'कंपनी कर्मचाऱ्यांसाठी टीम बिल्डिंग खेळ, ओपन-एअर लॉन, डीजे रेन डान्स, बुफे जेवण आणि रिलॅक्सेशन.', 'Team building retreat with open-air conference lawn, team games, DJ rain dance, buffet dining, and relaxation.', 'कंपनीच्या सहकाऱ्यांसाठी ताणतणावमुक्त आणि उत्साही दिवस. टीम बॉन्डिंग उपक्रम, प्रशस्त लॉन, डीजे रेन डान्स, स्वादिष्ट बुफे जेवण आणि उत्तम सोयीसुविधा.', 'Boost team morale and relieve corporate burnout with curated team activities, spacious lush green lawns for group games, rain dance party, and grand buffet meals.', 1099.00, 'uploads/packages/1788242608_aPTFqiQ6UI.png', 'active', 1, 1, '\"[\\\"Welcome Mocktails & Executive Breakfast\\\",\\\"Unlimited Royal Buffet Lunch & Evening High Tea\\\",\\\"Spacious Lawn for Corporate Team Building Activities\\\",\\\"Dedicated Event Anchor \\\\\\/ Coordinator for Team Games\\\",\\\"Rain Dance with DJ Sound System\\\",\\\"Projector \\\\\\/ PA System Setup on Request\\\"]\"', '\"[\\\"Alcoholic Beverages\\\",\\\"Special Custom Stage Setup (Available on Add-on)\\\"]\"', 0, 1, '2026-08-31 03:10:07', '2026-09-01 00:33:28', NULL),
(34, 'ग्रुप व ग्रुप गेट-टुगेदर पॅकेज', 'Group Package', 'Group Package', 'group-package', '१ दिवस (किमान १५ व्यक्ती)', '1 Day (Minimum 15 Guests)', 'Special discounted group rates for kitty parties, senior citizen groups, society gatherings, and friend reunions.', 'Perfect for large gatherings of 15+ members. Enjoy private seating gazebos, nostalgic rural games, farm tours, swimming pool fun, and hot traditional food together.', '1 Day (Minimum 15 Guests)', 749.00, 'मित्र-मैत्रिणी, ज्येष्ठ नागरिक मंडळे आणि सोसायटी ग्रुप्ससाठी सवलतीच्या दरातील खास ग्रुप पॅकेज.', 'Special discounted group rates for kitty parties, senior citizen groups, society gatherings, and friend reunions.', '१५ पेक्षा जास्त व्यक्तींच्या समूहासाठी खास सवलत. एकत्र गप्पा मारण्यासाठी खाजगी जागा, स्विमिंग पूल, बैलगाडी राईड आणि गरमागरम चुलीवरच्या जेवणाची मेजवानी.', 'Perfect for large gatherings of 15+ members. Enjoy private seating gazebos, nostalgic rural games, farm tours, swimming pool fun, and hot traditional food together.', 649.00, 'uploads/packages/1788246211_MuL5OIkQNX.jpg', 'active', 1, 1, '\"[\\\"Special Group Discounted Pricing\\\",\\\"Complete Meal Package: Breakfast, Lunch, Evening Snacks\\\",\\\"Reserved Group Dining & Relaxation Area\\\",\\\"Full Access to Pool, Rain Dance, and Farm Walks\\\",\\\"Group Photoshoot Spots & Props\\\",\\\"Musical Setup for Antakshari \\\\\\/ Group Singing\\\"]\"', '\"[\\\"Individual Room Allocation\\\",\\\"Transportation\\\"]\"', 0, 1, '2026-08-31 03:10:07', '2026-09-01 01:33:31', NULL),
(35, 'मुक्काम कॉटेज स्टे पॅकेज (२४ तास)', 'Overnight Stay Package', 'Overnight Stay Package', 'overnight-stay-package', '२४ तास (चेक-इन दुपारी १२:०० – दुसऱ्या दिवशी १०:००)', '24 Hours (Check-in 12:00 PM – Next Day 10:00 AM)', 'Luxury AC eco-cottage stay with all 4 meals (Lunch, High Tea, Dinner, Breakfast), night bonfire, and sunrise walk.', 'Rejuvenate with a serene night amidst nature. Stay in cozy AC wooden cottages with private verandas, relish evening bonfires under starry skies, 4 complete meals, and peaceful morning bird walks.', '24 Hours (Check-in 12:00 PM – Next Day 10:00 AM)', 3999.00, 'वातानुकूलित लक्झरी कॉटेज मुक्काम, सर्व ४ वेळचे जेवण, रात्रीची शेकोटी आणि रम्य पहाट शिवार फेरी.', 'Luxury AC eco-cottage stay with all 4 meals (Lunch, High Tea, Dinner, Breakfast), night bonfire, and sunrise walk.', 'निसर्गाच्या कुशीत शांत रात्रीचा मुक्काम. वातानुकूलित लाकडी कॉटेज, संध्याकाळी शेकोटी, चारही वेळचे स्वादिष्ट जेवण आणि सकाळी पक्षांच्या किलबिलाटात प्रसन्न शिवार फेरी.', 'Rejuvenate with a serene night amidst nature. Stay in cozy AC wooden cottages with private verandas, relish evening bonfires under starry skies, 4 complete meals, and peaceful morning bird walks.', 3499.00, 'uploads/packages/1788178782_qyi4sXquWZ.png', 'active', 1, 1, '\"[\\\"AC Deluxe Nature-View Wooden Cottage Accommodation\\\",\\\"4 Complete Meals: Lunch, High Tea, Dinner & Next Day Breakfast\\\",\\\"Evening Cozy Bonfire & Music Gathering\\\",\\\"Early Morning Guided Sunrise Farm Walk\\\",\\\"Full 2-Day Access to Pool, Rain Dance & Activities\\\",\\\"Free Wi-Fi & 24x7 Power Backup\\\"]\"', '\"[\\\"Late Check-out beyond 11:00 AM\\\",\\\"Special Midnight Room Service\\\"]\"', 0, 1, '2026-08-31 03:10:07', '2026-08-31 06:49:44', NULL),
(36, 'स्पेशल गावरान हुर्डा पार्टी पॅकेज', 'Special Village Hurda Party Package', 'Special Village Hurda Party Package', 'special-village-hurda-party-package-kYDBG', '१ दिवस (सकाळी ९ ते संध्याकाळी ६)', '1 Day (9:00 AM to 6:00 PM)', 'Unlimited Fresh Roasted Hurda, Traditional Chutneys, Wood-Fired Meals, Pool Access & Agro Activities.', 'Experience the rich winter traditions with our special Hurda Party Package at Visawa Agro Tourism! Enjoy tender, farm-fresh roasted jowar (Hurda) served with authentic spicy chutneys, organic jaggery, and dry coconut. The package includes a welcome breakfast, unlimited wood-fired Maharashtrian lunch, swimming pool & rain dance, bullock cart rides, farm walk, and evening high-tea.', '1 Day (9:00 AM to 6:00 PM)', 999.00, 'ताजा भाजलेला हुर्डा, विविध चटण्या, गुळ-खोबरे, अमर्याद जेवण, स्विमिंग पूल आणि ॲग्रो ॲक्टिव्हिटीज्.', 'Unlimited Fresh Roasted Hurda, Traditional Chutneys, Wood-Fired Meals, Pool Access & Agro Activities.', 'विसावा ॲग्रो टुरिझमचे खास हिवाळी हुर्डा पार्टी पॅकेज! यामध्ये पर्यटकांना शेतात थेट निखाऱ्यावर भाजलेला गरमागरम हुर्डा, शेंगदाणा-लसूण चटणी, गुळ आणि खोबऱ्याचा आस्वाद घेता येईल. यासोबत सकाळचा नाश्ता, चुलीवरचे अस्सल गावरान दुपारचे जेवण, स्विमिंग पूल, बैलगाडी सफर, शेतीची सफर आणि संध्याकाळचा चहा-नाश्ता समाविष्ट आहे.', 'Experience the rich winter traditions with our special Hurda Party Package at Visawa Agro Tourism! Enjoy tender, farm-fresh roasted jowar (Hurda) served with authentic spicy chutneys, organic jaggery, and dry coconut. The package includes a welcome breakfast, unlimited wood-fired Maharashtrian lunch, swimming pool & rain dance, bullock cart rides, farm walk, and evening high-tea.', 799.00, 'uploads/packages/1788177763_vf8c3CCDSB.png', 'active', 1, NULL, NULL, NULL, 0, 1, '2026-08-31 06:32:44', '2026-08-31 06:32:44', NULL),
(37, 'चाचणी पॅकेज', 'Test Package', NULL, 'test-package-g84kn', '१ दिवस', '1 Day', NULL, NULL, NULL, 0.00, NULL, NULL, NULL, NULL, NULL, NULL, 'active', NULL, NULL, NULL, NULL, 0, 1, '2026-09-01 00:32:59', '2026-09-01 00:32:59', '2026-09-01 00:32:59');

