(23, 'hero_title_mr', 'निसर्गाच्या सानिध्यात, ग्रामीण संस्कृतीचा अविस्मरणीय विसावा', 'hero', '2026-08-25 00:50:13', '2026-08-25 05:21:42'),
(24, 'hero_title_en', 'Experience Nature, Tradition & Unforgettable Hospitality', 'hero', '2026-08-25 00:50:13', '2026-08-25 05:21:42'),
(25, 'hero_subtitle_mr', 'विसावा ॲग्रो टुरिझम – बाबांचा मळा येथे कौटुंबिक आनंद, चुलीवरची चव, द्राक्ष बागांची सफर, ग्रामीण खेळ आणि शांत मुक्कामाचा आनंद घ्या.', 'hero', '2026-08-25 00:50:13', '2026-08-25 05:21:42'),
(26, 'hero_subtitle_en', 'Discover the rustic charm of rural Maharashtra with vineyard tours, wood-fired dining, pool, and peaceful cottage stays.', 'hero', '2026-08-25 00:50:13', '2026-08-25 05:21:42'),
(27, 'hero_image', 'uploads/settings/visawa_grand_entrance_hero.jpg', 'homepage', '2026-08-25 00:50:13', '2026-08-31 05:48:53'),
(28, 'about_title_mr', 'विसावा रिसॉर्ट बद्दल', 'about', '2026-08-25 00:50:13', '2026-08-25 01:09:55'),
(29, 'about_title_en', 'About Visava Resort', 'about', '2026-08-25 00:50:13', '2026-08-25 00:50:13'),
(30, 'about_description_mr', 'विसावा हे महाराष्ट्रातील अग्रगण्य ॲम्युझमेंट आणि वॉटर पार्क रिसॉर्ट आहे, जे निसर्गरम्य वातावरणात जागतिक दर्जाच्या सुविधा पुरवते.', 'about', '2026-08-25 00:50:13', '2026-08-25 01:09:55'),
(31, 'about_description_en', 'Visava is a premier amusement and water park resort offering world-class hospitality and adventure amidst lush greenery.', 'about', '2026-08-25 00:50:13', '2026-08-25 00:50:13'),
(32, 'about_image', 'uploads/settings/visawa_farmer_bullocks_about.jpg', 'about', '2026-08-25 00:50:13', '2026-08-31 03:00:57'),
(33, 'why_title_mr', 'विसावा रिसॉर्ट का निवडावे?', 'why_us', '2026-08-25 00:50:13', '2026-08-25 01:09:55'),
(34, 'why_title_en', 'Why Choose Visava Resort?', 'why_us', '2026-08-25 00:50:13', '2026-08-25 00:50:13'),
(35, 'why_description_mr', 'सुरक्षित राइड्स, शुद्ध व स्वादिष्ट अन्न, आलिशान खोल्या आणि उत्कृष्ट ग्राहक सेवा.', 'why_us', '2026-08-25 00:50:13', '2026-08-25 01:09:55'),
(36, 'why_description_en', 'Safe thrilling rides, hygienic delicious dining, luxury rooms, and 24/7 dedicated guest support.', 'why_us', '2026-08-25 00:50:13', '2026-08-25 00:50:13'),
(37, 'contact_title_mr', 'आमच्याशी संपर्क साधा', 'contact_section', '2026-08-25 00:50:13', '2026-08-25 01:09:55'),
(38, 'contact_title_en', 'Get in Touch With Us', 'contact_section', '2026-08-25 00:50:13', '2026-08-25 00:50:13'),
(39, 'contact_description_mr', 'बुकिंग आणि अधिक माहितीसाठी आजच आम्हाला संपर्क करा.', 'contact_section', '2026-08-25 00:50:13', '2026-08-25 01:09:55'),
(40, 'contact_description_en', 'Reach out to our team for custom packages and instant bookings.', 'contact_section', '2026-08-25 00:50:13', '2026-08-25 00:50:13'),
(41, 'whatsapp_owner_number', '919158141414', 'contact', '2026-08-28 23:51:29', '2026-08-28 23:51:29'),
(42, 'google_map_url', 'https://www.google.com/maps/place/Visawa+Agro+Tourism+Babacha+Mala/@19.8854008,75.2079868,656m/data=!3m2!1e3!4b1!4m6!3m5!1s0x3bdb9ba9bea86c1b:0x9e599923d483e0fb!8m2!3d19.8854008!4d75.2079868!16s%2Fg%2F11nvgsrrzz', 'contact', '2026-09-04 00:57:55', '2026-09-04 00:57:55');

