CREATE TABLE `testimonials` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `client_name` varchar(255) DEFAULT NULL,
  `client_designation_mr` varchar(255) DEFAULT NULL,
  `client_designation_en` varchar(255) DEFAULT NULL,
  `review_mr` text DEFAULT NULL,
  `review_en` text DEFAULT NULL,
  `client_image` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `designation` varchar(255) DEFAULT NULL,
  `rating` tinyint(3) UNSIGNED NOT NULL DEFAULT 5,
  `status` varchar(255) NOT NULL DEFAULT 'active',
  `comment` text DEFAULT NULL,
  `avatar` varchar(255) DEFAULT NULL,
  `is_approved` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `testimonials`
--

INSERT INTO `testimonials` (`id`, `client_name`, `client_designation_mr`, `client_designation_en`, `review_mr`, `review_en`, `client_image`, `name`, `designation`, `rating`, `status`, `comment`, `avatar`, `is_approved`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'सचिन कुलकर्णी (Sachin Kulkarni)', 'पुणे (कौटुंबिक पर्यटक)', 'Pune (Family Visitor)', 'बाबांचा मळा येथे आमच्या संपूर्ण कुटुंबाला प्रचंड आनंद मिळाला. चुलीवरची मिसळ आणि हुरडा पार्टी अप्रतिम होती. मुले शेती आणि स्विमिंग पूलमध्ये रमून गेली.', 'Our entire family had a fabulous experience at Babacha Mala! The wood-fired Misal and fresh Hurda party were outstanding. The kids loved the farm activities and pool.', NULL, 'सचिन कुलकर्णी (Sachin Kulkarni)', 'Pune (Family Visitor)', 5, 'active', 'Our entire family had a fabulous experience at Babacha Mala! The wood-fired Misal and fresh Hurda party were outstanding. The kids loved the farm activities and pool.', NULL, 1, '2026-08-25 05:32:17', '2026-08-25 05:32:17', NULL),
(2, 'प्रिया सावंत (Priya Sawant)', 'मुंबई (कॉर्पोरेट ग्रुप लीडर)', 'Mumbai (Corporate Group)', 'शहरी गोंगाटापासून दूर अतिशय शांत आणि निसर्गरम्य जागा. कॉटेजेस स्वच्छ आहेत आणि आदरातिथ्य घरच्यासारखे आहे. आम्ही नक्की पुन्हा येऊ!', 'A serene and rejuvenating getaway from city life. The cottages are sparkling clean and the staff hospitality is heartwarming. Highly recommended for group outings!', NULL, 'प्रिया सावंत (Priya Sawant)', 'Mumbai (Corporate Group)', 5, 'active', 'A serene and rejuvenating getaway from city life. The cottages are sparkling clean and the staff hospitality is heartwarming. Highly recommended for group outings!', NULL, 1, '2026-08-25 05:32:17', '2026-08-25 05:32:17', NULL),
(3, 'अमित पाटील (Amit Patil)', 'नाशिक (डे पिकनिक पाहुणे)', 'Nashik (Day Picnic Guest)', 'द्राक्ष बागांची सफर आणि बैलगाडी राईड खूपच छान होती. अस्सल गावरान जेवणाची चव जिभेवर रेंगाळत राहते. वाजवी दरात सर्वोत्तम पॅकेज!', 'The vineyard tour and bullock cart ride took us back to our childhood roots. The pure rustic Gavran food is unforgettable. Best value for money agro tour!', NULL, 'अमित पाटील (Amit Patil)', 'Nashik (Day Picnic Guest)', 5, 'active', 'The vineyard tour and bullock cart ride took us back to our childhood roots. The pure rustic Gavran food is unforgettable. Best value for money agro tour!', NULL, 1, '2026-08-25 05:32:17', '2026-08-25 05:32:17', NULL);

